const ARTISTS = [
  // ===== NU METAL / ALT METAL / GROOVE =====
  { name: "Five Finger Death Punch", genre: "Groove / Alt Metal", desc: "Groove metal moderno, pesado y directo, con ganchos. Más formuláico que lo que sueles preferir, pero potente. Cercano a Disturbed.", origin: "lista", p: 4, y: 2005 },
  { name: "System of a Down", genre: "Nu Metal / Alt Metal", desc: "Caótico y político, con saltos bruscos de lo brutal a lo melódico dentro del mismo compás y escalas armenias en los riffs de Daron Malakian, que además canta contrapunto contra Serj Tankian en vez de coros. John Dolmayan cambia de patrón constantemente por debajo. Riqueza e imprevisibilidad altísimas en canciones de tres minutos. Entrada: Toxicity o Mezmerize.", origin: "lista", pick: true, p: 1, y: 1994 },
  { name: "Disturbed", genre: "Nu Metal / Alt Metal", desc: "Metal alternativo robusto y melódico. Más directo, menos experimental. Vibe cercano a FFDP.", origin: "lista", p: 4, y: 1994 },
  { name: "Korn", genre: "Nu Metal", desc: "Padres del nu metal: bajo de 7 cuerdas, groove enfermo y angustia. Cercano a Limp Bizkit, Coal Chamber, Mudvayne.", origin: "lista", p: 2, y: 1993 },
  { name: "Limp Bizkit", genre: "Nu Metal", desc: "Nu metal con rap, festivo y crudo. Menos sobre instrumental compleja, más sobre actitud.", origin: "lista", p: 4, y: 1994 },
  { name: "Mudvayne", genre: "Nu Metal", desc: "Ryan Martinie redefinió el bajo en el metal: polirritmias, compases impares, slaps y taps percusivos, dobles y triples cuerdas y arpegios melódicos, con técnica propia de tapping y afinaciones raras (F# B F# B E). El bajo va por delante de la guitarra en la mezcla y lleva las líneas principales. Entrada: L.D. 50.", origin: "lista", pick: true, p: 1, y: 1996 },
  { name: "Coal Chamber", genre: "Nu Metal", desc: "Nu metal gótico de los 90. Atmosférico y oscuro. Cercano a Korn temprano.", origin: "lista", p: 3, y: 1993 },
  { name: "Mushroomhead", genre: "Nu Metal / Industrial", desc: "Nu metal con máscaras, teclados e industrial. Comparado siempre con Slipknot pero más experimental y teatral.", origin: "lista", p: 3, y: 1993 },
  { name: "Static-X", genre: "Industrial Metal", desc: "Metal industrial 'evil disco': ritmos mecánicos y veloces. Cercano a Rob Zombie.", origin: "lista", p: 3, y: 1994 },
  { name: "Rob Zombie", genre: "Industrial Metal", desc: "Metal industrial con estética de cine de terror: samples de películas usados como parte del arreglo, groove pegajoso y producción muy comprimida. La escritura por debajo es de canción con estribillo. Entrada: Hellbilly Deluxe.", origin: "lista", p: 3, y: 1997 },
  { name: "Rammstein", genre: "Industrial Metal", desc: "Industrial alemán (Neue Deutsche Härte): riffs pesados, teatralidad operística y humor oscuro. Único. Cada disco tiene su carácter.", origin: "lista", pick: true, p: 3, y: 1994 },
  { name: "Sevendust", genre: "Alt Metal", desc: "Metal alternativo de groove con la voz de Lajon Witherspoon, que canta con fraseo de soul en lugar de gritar, sobre riffs graves a medio tiempo y la batería de Morgan Rose muy adelante en la mezcla. Melódico y pesado a la vez, dentro de una estructura de canción bastante fija. Entrada: Home.", origin: "lista", p: 3, y: 1994 },
  { name: "Sick Puppies", genre: "Alt Rock / Alt Metal", desc: "Rock alternativo australiano melódico y de gancho fácil, con estructura de estrofa y estribillo y producción de radio. Trío de guitarra, bajo y batería sin adornos. Está en nivel de contexto porque es lo más directo y menos ambicioso de esta sección. Entrada: Tri-Polar.", origin: "lista", p: 4, y: 1997 },

  // ===== EXPERIMENTAL / AVANT-GARDE / FUNK ROCK =====
  { name: "Mr. Bungle", genre: "Avant-garde / Experimental", desc: "La sustancia es que los cortes estan escritos, no improvisados: cada seccion dura pocos compases y encaja con la siguiente por metrica, no por transicion, con arreglos de viento y percusion escritos nota a nota sobre esos saltos. California ordena esa tecnica en canciones; Disco Volante la lleva al extremo. Entrada: California, luego Disco Volante.", origin: "lista", pick: true, p: 1, y: 1985, c: 1 },
  { name: "Faith No More", genre: "Alt Metal / Experimental", desc: "Mike Patton usa la voz como instrumento con un rango absurdo, pasando de crooner a grito gutural dentro de un compás. Angel Dust salta de rap a lounge, a funk, a metal y a coros infantiles sin transición, con Mike Bordin tocando una batería de pulso tribal y platos abiertos que no se parece a la de nadie del género. Entrada: Angel Dust.", origin: "lista", pick: true, p: 1, y: 1979, c: 1 },
  { name: "Frank Zappa", genre: "Avant-garde / Experimental", desc: "Escribía partitura completa para banda de rock, con métricas que cambian compás a compás y líneas al unísono entre guitarra, marimba y vientos que hay que leer, no sacar de oído. Sesenta discos en vida cruzando rock, jazz, doo-wop y orquestal sin repetir formato. Entrada: Hot Rats o One Size Fits All.", origin: "lista", pick: true, p: 1, y: 1966, c: 1 },
  { name: "Dog Fashion Disco", genre: "Avant-garde Metal", desc: "Metal experimental teatral con saxo, vaivenes de género y narrativa. En la línea Mr. Bungle / Dog Fashion. Muy ecléctico.", p: 3, origin: "lista", pick: true, y: 1995 },
  { name: "Pinkly Smooth", genre: "Avant-garde / Experimental", desc: "Vodevil oscuro y excéntrico: cabaret macabro con cambios de compás, piano de circo y estructuras que se descosen. Un solo EP, y no se parece a nada de lo que hicieron sus miembros después.", p: 3, origin: "lista", pick: true, y: 2001 },
  { name: "Fishbone", genre: "Funk / Ska / Punk", desc: "Fusión frenética de ska, funk, punk y metal. Energía pura y mezcla de géneros. Influyentes para RHCP, Faith No More.", origin: "lista", p: 2, y: 1979 },
  { name: "Oingo Boingo", genre: "New Wave / Experimental", desc: "Banda de Danny Elfman (el compositor de cine). New wave teatral con vientos y ritmos raros. Excéntrica y melódica.", origin: "lista", p: 2, y: 1979 },
  { name: "Red Hot Chili Peppers", genre: "Funk Rock", desc: "Funk rock con bajo virtuoso (Flea) y melodía. Mezcla de funk, punk y baladas. Clásico.", origin: "lista", p: 3, y: 1983 },
  { name: "Thundercat", genre: "Jazz / Funk", desc: "Toca armonía de jazz completa en un bajo de seis cuerdas, acordes y no solo líneas, a velocidad de fusión y con groove de funk, mientras canta en falsete por encima. Y lo mantiene disco a disco: Apocalypse, Drunk e It Is What It Is son el mismo planteamiento con distinta paleta. Entrada: Drunk o Apocalypse.", origin: "lista", pick: true, p: 1, y: 2011 },

  // ===== PROG ROCK / PROG METAL CLÁSICO =====
  { name: "Pink Floyd", genre: "Prog Rock", desc: "Gilmour toca doblando y sosteniendo notas largas en vez de acumular velocidad, dejando huecos enormes; Nick Mason toca contenido y muy atrás, casi sin adornos, y esa quietud es la que sostiene las piezas largas; Roger Waters escribe líneas de bajo simples y repetitivas que hacen de ancla mientras todo lo demás se mueve encima. De Meddle a The Dark Side of the Moon a Wish You Were Here y Animals, cinco discos seguidos con esa misma lógica de espacio. Entra por Wish You Were Here.", origin: "lista", pick: true, p: 1, y: 1965 },
  { name: "Yes", genre: "Prog Rock", desc: "Chris Squire toca un bajo Rickenbacker con púa y sonido metálico y agudo, tan al frente que funciona como segunda guitarra, y Bill Bruford aporta un fraseo de jazz con acentos desplazados. Encima, Wakeman con varios teclados a la vez y armonías vocales a tres voces. Fragile, Close to the Edge y Relayer son tres discos seguidos con suites de veinte minutos que se desarrollan de verdad. Entra por Close to the Edge.", origin: "lista", pick: true, p: 1, y: 1968 },
  { name: "Genesis", genre: "Prog Rock", desc: "En la era Gabriel: Tony Banks escribe en los teclados como si fueran la sección principal, Steve Hackett usaba tapping a dos manos años antes de que se popularizara, y Phil Collins toca la batería con formación de jazz mientras Gabriel narra personajes. Supper's Ready son veintitrés minutos en siete secciones encadenadas. Luego viraron a pop de estadio con Collins cantando, y ahí se parte la banda en dos según a quién preguntes. Entrada: Selling England by the Pound o Foxtrot.", origin: "lista", p: 2, y: 1967 },
  { name: "Rush", genre: "Prog Rock", desc: "Trío donde los tres son solistas a la vez: Neil Peart toca una batería enorme con arreglos escritos como composición y no como base, Geddy Lee canta agudísimo mientras toca líneas de bajo independientes y pedales de sintetizador con los pies, y Lifeson rellena con acordes abiertos. Compases impares constantes y suites largas. Entrada: Moving Pictures o Hemispheres.", origin: "lista", pick: true, p: 1, y: 1968 },
  { name: "Tool", genre: "Prog Metal", desc: "Los compases raros no son adorno: Danny Carey monta patrones que se cruzan con el bajo en ciclos que tardan varios compases en volver a coincidir, y las piezas se levantan por acumulación durante diez minutos antes de estallar. Lo sostienen de Ænima a Lateralus a Fear Inoculum. Entrada: Lateralus.", origin: "lista", pick: true, p: 1, y: 1990 , c: 2 },
  { name: "A Perfect Circle", genre: "Prog / Alt Metal", desc: "Banda de Maynard (Tool) más melódica y atmosférica. Elegante y oscura.", p: 3, origin: "lista", pick: true, y: 1999 },
  { name: "Porcupine Tree", genre: "Prog Rock / Metal", desc: "Prog moderno de Steven Wilson: producción limpísima y melódica con punzadas pesadas, y sobre todo Gavin Harrison a la batería tocando polirritmias y desplazamientos de acento por debajo de riffs aparentemente simples. Entrada: In Absentia o Fear of a Blank Planet.", origin: "lista", pick: true, p: 1, y: 1987 , c: 2 },
  { name: "Opeth", genre: "Prog Death / Prog Rock", desc: "Death metal y prog setentero dentro del mismo tema, con Åkerfeldt pasando de gutural a voz limpia y de riff pesado a guitarra acústica sin costura, y Martín López tocando una batería de raíz latina y jazz en vez de blast beats. Cada disco se mueve, hasta abandonar los guturales del todo. Entrada: Blackwater Park.", origin: "lista", pick: true, p: 1, y: 1990 },
  { name: "Arcturus", genre: "Avant-garde Black / Prog", desc: "Black metal noruego cósmico y teatral con teclados sinfónicos. Excéntrico y único: La Masquerade Infernale es un hito del metal avant-garde. Entrada: La Masquerade Infernale.", origin: "lista", p: 2, y: 1991, c: 1 },

  // ===== PROG METAL MODERNO (la veta Dream Theater / Haken) =====
  { name: "Haken", genre: "Prog Metal", desc: "Prog metal moderno melódico y técnico, con humor deliberado y guiños ochenteros: alternan secciones de djent con pasajes de piano y armonías vocales a varias voces, y los discos cambian de enfoque entre sí (The Mountain es narrativo, Affinity imita la producción de los ochenta). Escritura densa pero accesible. Entrada: The Mountain.", origin: "lista", pick: true, p: 1, y: 2007 , c: 2 },
  { name: "Caligula's Horse", genre: "Prog Metal", desc: "Prog australiano melódico y emotivo, guitarrista excelente. Accesible dentro del prog.", p: 2, origin: "lista", pick: true, y: 2011 },
  { name: "Leprous", genre: "Prog Metal", desc: "Riffs en compases impares que se resuelven tarde, con el chelo integrado como voz armonica y la bateria de Baard Kolstad desplazando el acento respecto a la guitarra. La tension se construye por acumulacion ritmica, no por volumen. Entrada: The Congregation, luego Coal.", origin: "lista", pick: true, p: 1, y: 2001, c: 1 },
  { name: "Einar Solberg", genre: "Prog / Art", desc: "Prog sinfónico de cámara con orquesta y arreglos de cuerda escritos, y capas vocales de una complejidad real: el material se sostiene solo, no por venir de Leprous. Para cuando quieras el lado más artístico.", origin: "lista", p: 2, y: 2023 },
  { name: "Devin Townsend", genre: "Prog Metal / Experimental", desc: "La sustancia es la arquitectura del sonido: decenas de capas de guitarra y coro apiladas hasta formar un muro con armonia interna, no ruido. En Strapping Young Lad esa pared va sobre el doble bombo compositivo de Gene Hoglan; en Ocean Machine y Empath la misma tecnica se usa para pasajes ambientales y orquestales. Entrada: Ocean Machine.", origin: "lista", pick: true, p: 1, y: 1996, c: 1 },
  { name: "Ayreon", genre: "Prog Metal / Rock Opera", desc: "Óperas rock conceptuales de Arjen Lucassen con decenas de vocalistas invitados. Ciencia ficción épica. Ambición desbordada.", p: 3, origin: "lista", pick: true, y: 1995 },
  { name: "Symphony X", genre: "Prog / Power Metal", desc: "Prog metal neoclásico, virtuoso y épico. Russell Allen tiene una voz potente. Cercano a Dream Theater con más filo.", p: 2, origin: "lista", pick: true, y: 1994 },
  { name: "Shadow Gallery", genre: "Prog Metal", desc: "Prog metal melódico y emotivo, muy de los 90. Composiciones largas y cuidadas.", p: 3, origin: "lista", y: 1985 },
  { name: "Redemption", genre: "Prog Metal", desc: "Prog metal estadounidense denso y melódico, con miembros de Fates Warning. Emotivo.", p: 3, origin: "lista", y: 2001 },
  { name: "Pain of Salvation", genre: "Prog Metal", desc: "El tier se queda porque la música lo sostiene sola. Daniel Gildenlöw escribe con un rango de dinámica enorme dentro de un mismo disco, pasando de riff pesado a guitarra acústica y voz desnuda sin que suene a collage, y usa la voz como instrumento principal con la instrumental moviéndose debajo. Nivel de Dream Theater, Leprous y Haken, que ya tienes arriba. Entra por Remedy Lane o The Perfect Element.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Threshold", genre: "Prog Metal", desc: "Prog metal británico melódico y robusto, con ganchos. Subestimados.", p: 3, origin: "lista", y: 1988 },
  { name: "Vanden Plas", genre: "Prog Metal", desc: "Prog metal alemán teatral (han hecho musicales). Melódico y dramático.", p: 3, origin: "lista", y: 1986 },
  { name: "Daydream XI", genre: "Prog Metal", desc: "Prog metal brasileño moderno, dramático y técnico. En la veta Dream Theater / Symphony X.", p: 3, origin: "lista", y: 2010 },
  { name: "Circus Maximus", genre: "Prog Metal", desc: "Prog metal noruego melódico y accesible, con buena voz. Cercano a Dream Theater.", p: 3, origin: "lista", y: 2000 },
  { name: "Fates Warning", genre: "Prog Metal", desc: "Pioneros del prog metal junto a Dream Theater. Más sobrios y atmosféricos. Raíz del género.", origin: "lista", p: 2, y: 1982 },
  { name: "Transatlantic", genre: "Prog Rock", desc: "Supergrupo prog (Mike Portnoy, Neal Morse...). Suites épicas larguísimas en clave 70s moderna.", origin: "lista", p: 3, y: 1999 },
  { name: "Seventh Wonder", genre: "Prog Metal", desc: "Prog metal sueco con vocalista espectacular (Tommy Karevik) y bajo melódico. Brillante y luminoso.", p: 3, origin: "lista", pick: true, y: 2000 },
  { name: "Flying Colors", genre: "Prog Rock / Pop", desc: "Supergrupo prog accesible y melódico (Steve Morse, Mike Portnoy), pero el material es prog amable con ganchos pop: la ambición instrumental está muy por debajo de lo que hacen esos mismos músicos en Dixie Dregs o Dream Theater. El cartel no compensa la falta de complejidad.", origin: "lista", p: 3, y: 2011 },
  { name: "Art by Numbers", genre: "Prog Metal", desc: "Prog metal técnico y jazzístico, poco conocido. Para explorar a fondo el género.", p: 3, origin: "lista" },

  // ===== DJENT / PROG TÉCNICO MODERNO (veta Periphery) =====
  { name: "Tesseract", genre: "Djent / Prog", desc: "Djent atmosférico e hipnótico con voz limpia excelente. Groove envolvente.", p: 2, origin: "lista", pick: true, y: 2003 },
  { name: "Monuments", genre: "Djent / Prog", desc: "Djent melódico y groovy, técnico pero con ganchos. En la veta Periphery / Tesseract.", p: 2, origin: "lista", y: 2010 },
  { name: "Erra", genre: "Metalcore / Djent", desc: "Metalcore progresivo con melodías etéreas y djent. Equilibrio entre belleza y pegada. Muy recomendable.", p: 2, origin: "lista", pick: true, y: 2009 },
  { name: "Animals as Leaders", genre: "Prog / Instrumental", desc: "Instrumental puro, sin una sola voz: Tosin Abasi usa el thumping y el tapping a dos manos como técnica compositiva y no como truco, sobre armonía de jazz en métrica desplazada. Han ido cambiando la paleta disco a disco, más electrónica o más acústico, sin bajar la exigencia. Entrada: The Joy of Motion.", origin: "lista", pick: true, p: 1, y: 2007 , c: 2 },
  { name: "The Contortionist", genre: "Prog Metal / Djent", desc: "Empezaron en deathcore técnico y acabaron en prog atmosférico con teclados y voz limpia, cambiando de sonido cada disco hasta volverse irreconocibles. Language es el punto de giro. Entrada: Language.", p: 2, origin: "lista", pick: true, y: 2007, c: 1 },
  { name: "Sikth", genre: "Tech Metal / Mathcore", desc: "Dos vocalistas que no se turnan sino que se solapan y se contestan dentro de la misma frase, uno gritando y otro hablando o cantando agudo, sobre riffs de guitarra que saltan entre intervalos incómodos con la batería subdividiendo por debajo en otra métrica. Suena desordenado y está escrito al milímetro. Británicos. Entra por The Trees Are Dead & Dried Out Wait for Something Wild.", origin: "rec", p: 1, y: 1999, c: 2 },
  { name: "Intronaut", genre: "Prog / Post Metal", desc: "Prog metal con post-metal y jazz, con el bajo como protagonista real. Dos de tus preferencias declaradas en la misma banda. Atmosférico y rítmico.", origin: "lista", p: 2, y: 2004 },
  { name: "Mandroid Echostar", genre: "Prog Metal", desc: "Prog metal melódico con narrativa de cómic sci-fi. Colorido y técnico.", p: 3, origin: "lista" },
  { name: "Corelia", genre: "Prog Metal / Djent", desc: "Prog djent melódico, poco conocido. Para los rincones del género.", p: 3, origin: "lista" },
  { name: "The Human Abstract", genre: "Prog Metalcore", desc: "Metalcore técnico con guitarra neoclásica de verdad (arpegios y contrapunto barroco dentro del riff) y estructuras progresivas. Bello y agresivo, y bastante más instrumental que el resto de su generación.", origin: "lista", p: 2, y: 2004 },

  // ===== METALCORE / POST-HARDCORE (veta Avenged / Trivium) =====
  { name: "Trivium", genre: "Metalcore / Thrash", desc: "Metalcore-thrash con muchísima técnica de guitarra: Matt Heafy y Corey Beaulieu trabajan armonías gemelas y solos largos, y Shogun es donde más lejos llevan la ambición estructural. Evolucionan mucho entre discos. Tu matiz declarado: te gustan sus cambios, pero Vengeance Falls y Silence in the Snow te parecieron metal de fórmula aburrido, y eso está anotado. Entra por Shogun o Ascendancy.", origin: "heard", p: 1, y: 1999, c: 1 },
  { name: "All That Remains", genre: "Metalcore", desc: "Metalcore melódico con solos destacados (Oli Herbert). Accesible y con gancho.", p: 3, origin: "lista", y: 1998 },
  { name: "Parkway Drive", genre: "Metalcore", desc: "Metalcore australiano que fue creciendo hacia lo épico y melódico (Reverence, Ire). Evolución notable.", p: 3, origin: "lista", y: 2003 },
  { name: "Bury Tomorrow", genre: "Metalcore", desc: "Metalcore británico melódico con balance limpio/gutural. Sólido.", p: 3, origin: "lista", y: 2006 },
  { name: "August Burns Red", genre: "Metalcore", desc: "Metalcore técnico con riffs intrincados y cambios complejos. De lo más instrumental del género. Brad Bulla y JB Brubaker escriben riffs que cambian de compas dentro del estribillo y Matt Greiner mete fills de bateria con acentos desplazados donde el genero normalmente pone un breakdown recto.", p: 2, origin: "lista", pick: true, y: 2003 },
  { name: "Bring Me the Horizon", genre: "Metalcore / Alt", desc: "De deathcore brutal a pop-rock electrónico: pocos han cambiado tanto de disco a disco.", origin: "lista", pick: true, p: 2, y: 2004, c: 1 },
  { name: "Motionless in White", genre: "Metalcore / Industrial", desc: "Metalcore gótico e industrial con teclados al frente y estética muy marcada. Ganchos claros y estructura de estrofa y estribillo, sin ambición instrumental. Entrada: Graveyard Shift.", p: 3, origin: "lista", y: 2005 },
  { name: "Of Mice & Men", genre: "Metalcore", desc: "Metalcore melódico moderno con limpio/gutural. Accesible.", p: 3, origin: "lista", y: 2009 },
  { name: "Beartooth", genre: "Hardcore / Metalcore", desc: "Hardcore melódico enérgico y catártico. Directo, pegada y melodía.", p: 3, origin: "lista", y: 2012 },
  { name: "A Day to Remember", genre: "Pop Punk / Metalcore", desc: "Mezcla pop punk con metalcore (breakdowns + estribillos pegajosos). Híbrido divertido.", origin: "lista", p: 4, y: 2003 },
  { name: "Architects", genre: "Metalcore", desc: "Metalcore británico técnico y emotivo que fue puliendo un sonido enorme y atmosférico. Excelente evolución.", p: 3, origin: "lista", pick: true, y: 2004, c: 1 },
  { name: "While She Sleeps", genre: "Metalcore", desc: "Metalcore británico enérgico con espíritu comunitario y riffs grandes.", p: 3, origin: "lista", y: 2006 },
  { name: "The Devil Wears Prada", genre: "Metalcore", desc: "Metalcore con teclados atmosféricos. Han madurado mucho su sonido.", p: 3, origin: "lista", y: 2005 },
  { name: "Fit for a King", genre: "Metalcore", desc: "Metalcore moderno melódico y pesado, con mensaje. Sólido y consistente.", p: 3, origin: "lista", y: 2007 },
  { name: "Miss May I", genre: "Metalcore", desc: "Metalcore melódico clásico de los 2010 con buen balance. Pegada.", origin: "lista", p: 4, y: 2007 },
  { name: "Light the Torch", genre: "Metalcore / Hard Rock", desc: "Proyecto de Howard Jones (ex Killswitch): metalcore melódico con énfasis en estribillos y voz limpia potente.", p: 3, origin: "lista", y: 2012 },
  { name: "War of Ages", genre: "Metalcore", desc: "Metalcore con solos melódicos y temática de fe. Buena guitarra.", p: 3, origin: "lista", y: 2002 },
  { name: "Demon Hunter", genre: "Metalcore / Alt Metal", desc: "Metalcore versátil que va de lo brutal a baladas. Identidad propia fuerte.", p: 3, origin: "lista", y: 2000 },
  { name: "Shadows Fall", genre: "Metalcore / Thrash", desc: "Metalcore con raíz thrash y solos melódicos. De la ola de Nueva Inglaterra.", p: 3, origin: "lista", y: 1996 },
  { name: "Bad Wolves", genre: "Alt Metal / Metalcore", desc: "Metal moderno melódico con ganchos radiables. Más accesible.", origin: "lista", p: 4, y: 2017 },
  { name: "I Prevail", genre: "Metalcore", desc: "Metalcore moderno con electrónica y estribillos pop. Energía y gancho.", origin: "lista", p: 4, y: 2013 },
  { name: "Asking Alexandria", genre: "Metalcore", desc: "De metalcore/electronicore a rock más maduro. Evolución marcada entre discos.", origin: "lista", p: 4, y: 2008 },
  { name: "Disciple", genre: "Hard Rock / Metalcore", desc: "Rock/metal con mensaje, melódico y enérgico. Veteranos.", origin: "lista", p: 4, y: 1992 },
  { name: "The Raven Age", genre: "Metalcore / Melodic", desc: "Metalcore melódico británico (con lazos a Iron Maiden — el hijo de Steve Harris). Atmosférico.", p: 3, origin: "lista", y: 2009 },
  { name: "Bleed from Within", genre: "Metalcore", desc: "Metalcore escocés moderno, técnico y groovy. En ascenso, muy sólido.", p: 3, origin: "lista", y: 2005 },
  { name: "Hope for the Dying", genre: "Prog Metalcore / Death", desc: "Metalcore progresivo sinfónico con death melódico. Ambicioso y poco conocido.", p: 3, origin: "lista", y: 2006 },
  { name: "Blinded by Faith", genre: "Melodic Death / Symphonic", desc: "Death sinfónico melódico canadiense. Oscuro y orquestal.", origin: "lista", p: 3, y: 1996 },

  // ===== POST-HARDCORE / SCREAMO / MELÓDICO RARO =====
  { name: "Underoath", genre: "Post-Hardcore", desc: "Post-hardcore atmosférico y emocional, muy influyente. 'Define the Great Line' es un clásico denso.", origin: "lista", p: 2, y: 1997 },
  { name: "Chiodos", genre: "Post-Hardcore", desc: "Post-hardcore teatral con piano y dramatismo. Voz peculiar. Dinámicos.", p: 3, origin: "lista", y: 2001 },
  { name: "Alesana", genre: "Post-Hardcore / Screamo", desc: "Post-hardcore narrativo y teatral con conceptos literarios. (Ya lo escuchaste.)", p: 3, origin: "lista", y: 2004 },
  { name: "Closure in Moscow", genre: "Prog / Post-Hardcore", desc: "Prog rock australiano excéntrico con groove: cambios de compás dentro del estribillo, falsete teatral y armonías que se van por sitios raros, todo con una ligereza que disimula lo complicado que es. Entrada: First Temple.", p: 2, origin: "lista", pick: true, y: 2006 },
  { name: "Fall of Troy", genre: "Post-Hardcore / Math", desc: "Trío donde Thomas Erak toca líneas de guitarra retorcidas Y canta a la vez: estructuras caóticas, cambios de tempo constantes y tapping sobre disonancia. La crítica compara Doppelganger con los discos de The Mars Volta, que ya tienes en ①. Reedición de 20 aniversario en mayo de 2025. Entrada: Doppelganger.", origin: "lista", pick: true, p: 1, y: 2002 , c: 2 },
  { name: "Every Time I Die", genre: "Metalcore / Southern", desc: "Metalcore con groove sureño y riffs angulares mucho más raros de lo que aparentan: Jordan Buckley cruza blues sureño con disonancia caótica. Letras ingeniosas y energía salvaje.", origin: "lista", p: 2, y: 1998 },
  { name: "Dance Gavin Dance", genre: "Post-Hardcore / Math", desc: "(asociado a tu zona) Post-hardcore con math rock, funk y voz limpia soul + screamo. Muy ecléctico.", p: 3, origin: "rec", y: 2005, via: "PTH" },

  // ===== POWER / SYMPHONIC / FOLK METAL =====
  { name: "Helloween", genre: "Power Metal", desc: "Padres del power metal europeo: veloz, melódico, épico y optimista. Clásico fundacional.", origin: "lista", p: 2, y: 1984 },
  { name: "Blind Guardian", genre: "Power Metal", desc: "Hansi Kürsch graba su propia voz en decenas de capas hasta formar un coro entero él solo, y pasa de esos muros a línea solista limpia y a grito sin costura, mientras las guitarras hacen contrapunto a dos voces en vez de doblarse. Los discos están arreglados con detalle casi orquestal, con interludios acústicos y narrados que hacen de estructura. Entra por Nightfall in Middle-Earth o Somewhere Far Beyond.", origin: "rec", p: 1, y: 1984, c: 2 },
  { name: "Dragonforce", genre: "Power Metal", desc: "Power metal extremo: velocidad absurda y solos de videojuego. Diversión técnica.", origin: "lista", p: 3, y: 1999 },
  { name: "Sabaton", genre: "Power Metal", desc: "Power metal sobre historia bélica, himnos pegajosos. Cada disco, un tema histórico.", origin: "lista", pick: true, p: 3, y: 1999 },
  { name: "Nightwish", genre: "Symphonic Metal", desc: "Tuomas Holopainen escribe partes orquestales de verdad, grabadas con orquesta y coro reales, y ahí sí hay trabajo; pero lo que hay debajo son canciones de estrofa y estribillo de power metal, con la orquesta encima como capa y no como parte de la estructura. Cuando la voz cambió de operística (Tarja) a más rock (Floor Jansen) el esqueleto siguió siendo el mismo. Espectacular de producción, convencional de escritura. Entra por Once o Endless Forms Most Beautiful. (voz femenina)", origin: "rec", p: 2, y: 1996, c: 2, female: true },
  { name: "Unleash the Archers", genre: "Power Metal", desc: "Power metal con vocalista potentísima (Brittney Slayes) que canta limpio y épico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2007 },
  { name: "Holy Grail", genre: "Power / Thrash", desc: "Power-thrash con solos veloces y melódicos. Energía clásica.", origin: "lista", p: 3, y: 2008 },
  { name: "Imperanon", genre: "Melodic / Power Metal", desc: "Melodic metal finlandés veloz y técnico, con teclados. Raro de encontrar, en la veta Children of Bodom.", origin: "lista", p: 3, y: 1999 },
  { name: "Eluveitie", genre: "Folk Melodic Death", desc: "Folk metal suizo: death melódico con violín, gaita y flautas celtas. Mezcla única. (voz femenina compartida)", origin: "lista", female: true, p: 2, y: 2002 },
  { name: "Alestorm", genre: "Folk / Pirate Metal", desc: "Power/folk metal pirata: divertido, festivo y autoconsciente. Para soltar.", origin: "lista", p: 4, y: 2004 },

  // ===== HEAVY / THRASH / CLÁSICO =====
  { name: "Black Sabbath", genre: "Heavy Metal (clásico)", desc: "Bill Ward se formó con bateristas de jazz y entra y sale del tempo en vez de clavarlo, con un swing que ninguna banda pesada tenía; Geezer Butler no dobla el riff, toca líneas propias por debajo; e Iommi construyó todo sobre el tritono, con las cuerdas destensadas para poder tocar tras perder las yemas de dos dedos. Y eso se sostiene seis discos seguidos, de Paranoid a Master of Reality a Sabotage, sin repetirse. Entra por Master of Reality o Vol. 4.", origin: "rec", p: 1, y: 1968, c: 2 },
  { name: "Judas Priest", genre: "Heavy Metal (clásico)", desc: "Fijaron la plantilla de las dos guitarras armonizando en terceras que copió el género entero, con Halford cantando en un registro agudísimo por encima y una base rítmica que va recta y sin adornos. Las canciones son himnos de estructura simple y directa, hechos para corearse: esa claridad es su virtud y también su límite para lo que tú buscas. Entra por Painkiller o Sad Wings of Destiny.", origin: "rec", p: 2, y: 1969, c: 2 },
  { name: "Dio", genre: "Heavy Metal (clásico)", desc: "La voz de Ronnie James Dio: épica y mística. Heavy melódico clásico.", origin: "lista", p: 2, y: 1982 },
  { name: "Ozzy Osbourne", genre: "Heavy Metal (clásico)", desc: "El Príncipe de las Tinieblas en solitario, con guitarristas legendarios (Randy Rhoads). Melódico y oscuro.", origin: "lista", p: 2, y: 1979 },
  { name: "Grim Reaper", genre: "Heavy Metal (NWOBHM)", desc: "Heavy metal británico de los 80, directo y enérgico. Clásico de culto.", origin: "lista", p: 4, y: 1979 },
  { name: "Anthrax", genre: "Thrash Metal", desc: "Uno de los 'Big Four' del thrash, con groove y actitud neoyorquina. Pionero del crossover.", origin: "lista", p: 2, y: 1981 },
  { name: "Exodus", genre: "Thrash Metal", desc: "Thrash de la Bay Area, agresivo y veloz. Riffs implacables.", origin: "lista", p: 2, y: 1979 },
  { name: "Slayer", genre: "Thrash Metal", desc: "El thrash más extremo y oscuro de los Big Four: tempos al límite, riffs cromáticos sin melodía y solos atonales de Hanneman y King que suenan a ruido controlado, con Lombardo tocando blast beats antes de que existiera el término. Directo y sin adornos, y esa crudeza es el punto. Entrada: Reign in Blood.", origin: "lista", p: 2, y: 1981 },
  { name: "Sepultura", genre: "Thrash / Groove", desc: "De thrash brutal a groove tribal: en Roots, Igor Cavalera reconstruyó su forma de tocar alrededor de la percusión indígena brasileña, grabando con los Xavante, y el disco se afinó gravísimo para que el ritmo pesara más que el riff. Evolución radical entre discos. Entrada: Chaos A.D. o Roots.", origin: "lista", pick: true, p: 2, y: 1984, c: 1 },
  { name: "Soulfly", genre: "Groove / Tribal Metal", desc: "Proyecto de Max Cavalera (ex Sepultura): groove tribal y world music. Pesado y rítmico.", origin: "lista", p: 3, y: 1997 },
  { name: "Exhorder", genre: "Thrash / Groove", desc: "Pioneros del groove metal (anteriores a Pantera en ese sonido). De culto.", origin: "lista", p: 3, y: 1985 },
  { name: "Hatebreed", genre: "Metalcore / Hardcore", desc: "Hardcore-metal de pura adrenalina y breakdowns. Directo y catártico.", origin: "lista", p: 4, y: 1994 },
  { name: "Down", genre: "Sludge / Doom", desc: "Supergrupo sludge sureño (Phil Anselmo). Riffs pantanosos y pesados. Cercano a Crowbar.", origin: "lista", p: 4, y: 1991 },
  { name: "Crowbar", genre: "Sludge / Doom", desc: "Sludge de Nueva Orleans: lento, demoledor y emotivo. Pesadez física.", origin: "lista", p: 3, y: 1990 },

  // ===== DEATH METAL / TÉCNICO / EXTREMO =====
  { name: "Death", genre: "Death Metal (clásico)", desc: "Chuck Schuldiner reescribio su propia banda cuatro veces: del riff primitivo de Scream Bloody Gore a la escritura modal y de metrica impar de Human en adelante, con Steve DiGiorgio al bajo fretless y Gene Hoglan a la bateria en esa etapa. Los solos pasan de cromatismo a construccion armonica real. Entrada: Human, luego Symbolic.", origin: "lista", pick: true, p: 1, y: 1984 },
  { name: "Morbid Angel", genre: "Death Metal", desc: "Death metal clásico de Florida, técnico y oscuro. Pilar del género.", origin: "lista", p: 2, y: 1983 },
  { name: "Necrophagist", genre: "Technical Death", desc: "Muhammed Suiçmez escribe los solos como piezas neoclásicas completas, con armonía funcional dentro del death técnico, y los riffs siguen esa misma conducción de voces. Solo tienen dos discos y los dos están a ese nivel. Entrada: Epitaph.", origin: "lista", p: 1, y: 1992 },
  { name: "Revocation", genre: "Technical Death / Thrash", desc: "Death técnico con thrash y jazz, guitarra brillante (Dave Davidson). Inteligente y veloz.", p: 2, origin: "lista", pick: true, y: 2006 },
  { name: "Decapitated", genre: "Technical Death", desc: "Death técnico polaco, groovy y preciso. Modernos y demoledores.", p: 2, origin: "lista", y: 1996 },
  { name: "Cattle Decapitation", genre: "Death / Grind", desc: "Deathgrind con mensaje ecologista y voz inhumana (Travis Ryan). Brutal pero melódico en momentos sorprendentes.", p: 2, origin: "lista", pick: true, y: 1996 },
  { name: "Job for a Cowboy", genre: "Death Metal", desc: "De deathcore a death progresivo. Evolución notable. Reciente regreso prog.", p: 3, origin: "lista", y: 2003 },
  { name: "Cannibal Corpse", genre: "Death Metal", desc: "Se queda en nivel de contexto: death metal rápido y directo, con Alex Webster al bajo haciendo líneas bastante más elaboradas de lo que la fama de la banda sugiere, pero riffs que priorizan el impacto sobre el desarrollo. Históricamente imprescindible; para tu gusto, no.", origin: "heard", p: 4, y: 1988, c: 2 },
  { name: "Slugdge", genre: "Progressive Death", desc: "Death progresivo británico con mitología de babosas (en serio) y muchísima melodía y técnica. Joya rara. Muy recomendable.", p: 2, origin: "lista", pick: true, y: 2012 },
  { name: "Anciients", genre: "Prog Death / Sludge", desc: "Prog death canadiense con groove y melodía tipo Mastodon/Opeth. Excelente.", p: 2, origin: "lista", pick: true, y: 2010 },
  { name: "Inter Arma", genre: "Post / Sludge / Death", desc: "Metal extremo que cruza sludge, death, doom y post dentro del mismo disco, con T.J. Childers cambiando de lenguaje de batería entero según la sección (blast, marcha lenta, redoble tribal). Temas largos que no vuelven al punto de partida. Entrada: Sulphur English.", p: 2, origin: "lista", pick: true, y: 2006 },
  { name: "Rivers of Nihil", genre: "Progressive Death", desc: "Death progresivo con saxofón y atmósfera (concepto de las estaciones). 'Where Owls Know My Name' es brillante. Altamente recomendable.", p: 2, origin: "lista", pick: true, y: 2009 },
  { name: "Fit for an Autopsy", genre: "Deathcore", desc: "Will Putney, que además produce a media escena, escribe los riffs alternando pasajes graves a medio tiempo con secciones de guitarra limpia y melódica, y dejan que los temas bajen de intensidad de verdad en lugar de encadenar breakdowns. Letras de crítica social sin gore. Es de los pocos del género con dinámica real. Entrada: The Sea of Tragic Beasts.", origin: "lista", pick: true, p: 2, y: 2008 },
  { name: "Whitechapel", genre: "Deathcore", desc: "Tienen tres guitarristas, lo que les permite superponer una línea melódica sobre dos rítmicas a la vez en vez de doblar el mismo riff, y en los últimos discos han metido voz limpia y pasajes atmosféricos que cambian bastante el peso de la banda. Entrada: The Valley.", origin: "lista", pick: true, p: 2, y: 2006 },
  { name: "Slaughter to Prevail", genre: "Deathcore", desc: "Cierto que Alex Terrible tiene uno de los registros guturales más graves y potentes del género, pero por debajo la escritura es deathcore de manual, riff grave, breakdown y vuelta, con producción enorme y muy poco desarrollo. Funciona por impacto, no por composición. Entrada: Kostolom.", origin: "lista", p: 3, y: 2014 },
  { name: "Slice the Cake", genre: "Prog Deathcore", desc: "Banda internacional con miembros de Inglaterra, Suecia y Australia. Odyssey to the West (1 de abril de 2016) son setenta y siete minutos concebidos como una sola obra continua, con orquesta, coro y pasajes acústicos entre lo pesado. Se formaron en 2009, se separaron ese mismo 2016, volvieron en 2019 y se separaron de nuevo en 2022. Entrada: Odyssey to the West.", origin: "lista", p: 2, y: 2009, c: 2 },
  { name: "Within the Ruins", genre: "Technical Deathcore", desc: "Joe Cocchi escribe la guitarra como si fuera un instrumento solista dentro del deathcore, con líneas melódicas rapidísimas, barridos y armonías a dos voces por encima de la base, en vez de limitarse al riff grave. Los discos son cortos y sin relleno. Entrada: Elite o Halfway Human.", origin: "lista", pick: true, p: 2, y: 2003 },
  { name: "Enterprise Earth", genre: "Deathcore", desc: "Deathcore sinfónico con orquestación programada por encima de riffs técnicos y blast beats, y voces que alternan gutural profundo con agudo. Bien ejecutado y con producción enorme, pero se mueve dentro de la plantilla sinfónica que Lorna Shore y Shadow of Intent hacen con más personalidad. Entrada: The Chosen.", origin: "lista", p: 3, y: 2014 },
  { name: "Future Corpse", genre: "Progressive Metal / Prog Rock", desc: "Melbourne, Australia, 2015. No es deathcore como figuraba aqui: es prog metal independiente con temas de distopia y misantropia. Dos discos, Another World to Consume (2016) y Culture Ruins Everything Around Me (2018).", origin: "lista", p: 3, y: 2018, c: 2 },
  { name: "Physics of Demise", genre: "Melodic Death Metal", desc: "Danbury, Connecticut, 2011. Melodeath de escena local con debut en 2012, Farewell to Better Days. Ejecucion correcta dentro del molde de Gotemburgo, sin nada que lo separe del resto.", origin: "lista", p: 3, y: 2012, c: 2 },
  { name: "Car Bomb", genre: "Mathcore / Tech", desc: "Desplazan el acento del riff respecto al pulso de la batería de forma que el oído pierde dónde está el uno, y usan silencios cortados en seco a mitad de frase como elemento rítmico. Greg Kubacki toca figuras que se repiten con una nota de diferencia cada vuelta, y eso produce la sensación de máquina averiada que los define. Entra por Meta.", origin: "rec", p: 1, y: 2000, c: 2 },
  { name: "Dillinger Escape Plan", genre: "Mathcore", desc: "Calculating Infinity está escrito en compases que cambian casi por compás, con la guitarra y la batería ejecutando al unísono figuras que suenan aleatorias y no lo son, y armonía tomada del jazz (acordes disminuidos y alterados) puesta a velocidad de hardcore. Chris Pennie escribía las partes de batería como composición, no como acompañamiento. Con Greg Puciato metieron después limpios y electrónica sin soltar el caos. Entra por Calculating Infinity, luego Ire Works.", origin: "rec", p: 1, y: 1997, c: 2 },
  { name: "Tony Danza Tapdance Extravaganza", genre: "Mathcore", desc: "Mathcore caótico con nombre absurdo. Técnico y feroz.", origin: "lista", p: 3, y: 2004 },
  { name: "Portal", genre: "Dissonant Death", desc: "Death metal disonante y atonal australiano, aterrador y abstracto. Experiencia abrasiva. Para mente muy abierta.", p: 2, origin: "lista", y: 1994 },
  { name: "Vein", genre: "Mathcore / Nu Metalcore", desc: "Mathcore caótico con toques nu metal de los 90. Vértigo y agresión modernos.", origin: "lista", p: 3, y: 2013 },

  // ===== MELODIC DEATH METAL (tu zona declarada) =====
  { name: "At the Gates", genre: "Melodic Death", desc: "Melodeath rápido y directo, construido sobre riffs de tresillos y armonías de guitarra a dos voces muy cortas y memorables, con Tomas Lindberg gritando en un registro alto y seco. Slaughter of the Soul es deliberadamente conciso y sin grasa, y esa concisión es su virtud y su techo: es la plantilla que copiaron mil bandas, no un ejercicio de complejidad. Entra por Slaughter of the Soul, y The Red in the Sky Is Ours si quieres su lado raro.", origin: "rec", p: 2, y: 1990, c: 2 },
  { name: "Dark Tranquillity", genre: "Melodic Death", desc: "Melodeath melódico con teclados que llevan contramelodía en vez de hacer colchón, y Mikael Stanne alternando gutural y limpio con más rango que la media del género. Muy bien hechos y con una carrera sin discos malos, pero trabajan dentro de la plantilla que ellos mismos ayudaron a fijar. Entra por The Gallery o Character.", origin: "rec", p: 2, y: 1989, c: 2 },
  { name: "Soilwork", genre: "Melodic Death", desc: "Melodeath sueco que incorporó mucho estribillo limpio y groove. Evolución clara entre discos.", origin: "lista", p: 3, y: 1995, c: 1 },
  { name: "Sylosis", genre: "Melodic Thrash / Death", desc: "Melodeath-thrash británico técnico con riffs y solos brillantes. Muy infravalorado. Te encantará.", p: 3, origin: "lista", pick: true, y: 2000 },
  { name: "Arch Enemy", genre: "Melodic Death", desc: "Melodeath con vocalista femenina (Alissa White-Gluz) y solos clásicos. (voz femenina)", origin: "lista", female: true, p: 3, y: 1995 },
  { name: "The Halo Effect", genre: "Melodic Death", desc: "Melodeath de Gotemburgo clásico y bien hecho, pero es deliberadamente un regreso al sonido dorado: su atractivo es la nostalgia y el linaje ex-In Flames, no una propuesta instrumental propia.", origin: "lista", pick: true, p: 3, y: 2021 },
  { name: "The Haunted", genre: "Melodic Death / Thrash", desc: "Thrash/melodeath sueco agresivo (ex-At the Gates). Filo y groove.", origin: "lista", p: 3, y: 1996 },
  { name: "Insomnium", genre: "Melodic Death", desc: "Melodeath finlandés melancólico con guitarras limpias en arpegio bajo el riff, tempos medios y mucho espacio. Llevan veinticinco años sin sacar un mal disco y encadenan buena racha con Winter's Gate, Heart Like a Grave y Anno 1696, pero la paleta armónica es bastante fija: lo constante es la calidad, no la ambición. Winter's Gate, una sola pieza de cuarenta minutos, es la excepción y no la norma. Entra por Winter's Gate.", origin: "rec", p: 2, y: 1997, c: 2 },
  { name: "Before the Dawn", genre: "Melodic Death", desc: "Melodeath finlandés melódico y oscuro, con limpio/gutural. Sólido.", origin: "lista", p: 3, y: 1999 },
  { name: "Bloodred Hourglass", genre: "Melodic Death", desc: "Melodeath finlandés moderno con ganchos y pegada. Energético.", origin: "lista", p: 3, y: 2005 },
  { name: "Rise to Fall", genre: "Melodic Death", desc: "Melodeath español técnico y sinfónico. Poco conocido.", origin: "lista", p: 3, y: 2006 },
  { name: "Zonaria", genre: "Melodic Death", desc: "Melodeath sueco agresivo con toque sinfónico. Veloz.", origin: "lista", p: 3, y: 2001 },
  { name: "Scar Symmetry", genre: "Melodic Death / Prog", desc: "Melodeath progresivo con limpio/gutural y melodías cósmicas. Técnico y pegadizo. Muy recomendable.", origin: "lista", pick: true, p: 2, y: 2004 },
  { name: "Amon Amarth", genre: "Melodic Death (Viking)", desc: "Melodeath vikingo épico e himnódico. Riffs heroicos. Consistentes y grandiosos.", origin: "lista", pick: true, p: 3, y: 1992 },
  { name: "Heaven Shall Burn", genre: "Melodic Death / Metalcore", desc: "Melodeath-metalcore alemán con mensaje político y pegada masiva.", origin: "lista", p: 3, y: 1996 },
  { name: "Amaranthe", genre: "Melodic / Pop Metal", desc: "Híbrido de melodeath con estructura de pop y electrónica, y su rasgo propio es la formación: tres vocalistas a la vez (femenina limpia, masculina limpia y gutural) que se turnan frases dentro del mismo estribillo, lo que casi nadie hace. Debajo, riffs melodeath y bases de dance. Divisivo a propósito y muy fórmula una vez pasada la sorpresa, por eso queda en nivel de contexto. (voz femenina compartida) Entrada: The Nexus.", origin: "lista", female: true, p: 4, y: 2008 },
  { name: "Dagoba", genre: "Industrial Melodic Death", desc: "Melodeath francés con groove industrial. Moderno y pesado.", origin: "lista", p: 3, y: 1997 },
  { name: "Epicurean", genre: "Melodic Death", desc: "Melodeath estadounidense melódico. Poco conocido.", origin: "lista", p: 3, y: 2001 },

  // ===== METALCORE/DEATHCORE FEMENINO + METAL FEMENINO =====
  { name: "Make Them Suffer", genre: "Metalcore / Symphonic", desc: "Metalcore sinfónico australiano con teclados/voz femenina y guturales. Belleza y brutalidad. (voz femenina compartida)", p: 3, origin: "lista", female: true, y: 2008 },
  { name: "The Agonist", genre: "Melodic Death / Metalcore", desc: "Metalcore melódico con vocalista femenina versátil (limpio operístico + gutural). (voz femenina)", origin: "lista", female: true, p: 3, y: 2004 },
  { name: "Flyleaf", genre: "Alt Metal / Post-Hardcore", desc: "Alt metal con vocalista femenina (Lacey Sturm), emotivo y enérgico. (voz femenina)", p: 3, origin: "lista", female: true, y: 2002 },
  { name: "Red Handed Denial", genre: "Prog Metalcore", desc: "Metalcore progresivo con vocalista femenina y mucha técnica. Moderno y dinámico. (voz femenina)", p: 3, origin: "lista", female: true },
  { name: "Burning Witches", genre: "Heavy / Power Metal", desc: "Heavy/power metal clásico con formación femenina, en la veta Judas Priest. (voz femenina)", origin: "lista", female: true, p: 3, y: 2015 },
  { name: "Huntress", genre: "Heavy / Thrash", desc: "Heavy/thrash con vocalista femenina (Jill Janus). Oscuro y clásico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2009 },
  { name: "Frozen Crown", genre: "Power Metal", desc: "Power metal italiano melódico y veloz con voz femenina. Épico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2017 },
  { name: "Halestorm", genre: "Hard Rock", desc: "Hard rock directo con Lzzy Hale, que canta con un registro muy amplio y un rasgado potente, y toca la guitarra rítmica ella misma. Estructura de canción clásica y producción de radio: eficaz y sin sorpresas instrumentales. Entrada: The Strange Case Of... (voz femenina)", origin: "lista", female: true, p: 3, y: 1997 },

  // ===== INDUSTRIAL / NU / EXPERIMENTAL MODERNO =====
  { name: "Nine Inch Nails", genre: "Industrial / Electronic", desc: "Trent Reznor trata el ruido como material armónico y no como capa de suciedad: los sonidos están afinados y cumplen función de acorde. Y el arco va de la agresión de Broken al ambient de Ghosts y a las bandas sonoras, cambiando de sistema en cada disco. Entrada: The Downward Spiral.", origin: "lista", pick: true, p: 1, y: 1988, c: 1 },
  { name: "Tallah", genre: "Nu Metalcore", desc: "Nu metal moderno caótico y técnico, hiperactivo. Revival nu metal con frescura.", p: 3, origin: "lista", y: 2017 },
  { name: "Dance with the Dead", genre: "Synthwave / Darksynth", desc: "Bajado con el resto del synthwave, y de paso quitada una frase que te atribuía el gusto por adelantado. Synthwave con guitarras metaleras encima, instrumental y cinematográfico, orientado al cine de terror ochentero. Bien hecho dentro de un molde muy fijo. Entra por Loveless Encounter.", origin: "rec", p: 3, y: 2013, c: 2 },
  { name: "Code Orange", genre: "Hardcore / Industrial", desc: "Hardcore con industrial y glitch: cortan la mezcla en seco, meten fallos digitales como si el archivo se corrompiera y cambian de tempo de golpe, con Jami Morgan tocando la batería y cantando a la vez. Cada disco rompe el molde del anterior. Entrada: Forever.", p: 2, origin: "lista", pick: true, y: 2008, c: 1 },

  // ===== DOOM/BLACK/EXTREMO ATMOSFÉRICO =====
  { name: "Immortal", genre: "Black Metal", desc: "Black metal noruego épico e invernal. Atmósfera helada. Clásico del género.", origin: "lista", p: 3, y: 1991 },
  { name: "Cradle of Filth", genre: "Symphonic Black", desc: "Black metal sinfónico teatral y gótico, con voz aguda característica. Dramático y excesivo.", origin: "lista", p: 3, y: 1991 },
  { name: "Skeletonwitch", genre: "Blackened Thrash", desc: "Thrash con black metal y melodía. Veloz y pegadizo dentro de lo extremo.", origin: "lista", p: 3, y: 2003 },

  // ===== SLEEP TOKEN / SLEEP-ADJACENT / ATMOSFÉRICO MODERNO =====
  { name: "Sleep Token", genre: "Alt Metal / Atmospheric", desc: "Pasa de piano y voz susurrada a djent pesadísimo dentro del mismo tema, con la batería de II tocando patrones sincopados por debajo de secciones muy quietas. El contraste es el recurso principal. Sigue en alta afinidad a la espera de que lo escuches. Entrada: Take Me Back to Eden.", origin: "lista", pick: true, p: 2, y: 2016, c: 2 },
  { name: "Avatar", genre: "Avant-garde Metal", desc: "Metal teatral sueco con estética circense oscura. Melódico, pesado y muy visual. Único.", p: 3, origin: "lista", pick: true, y: 2001 },

  // ===== POST-ROCK / INSTRUMENTAL ATMOSFÉRICO =====
  { name: "Caspian", genre: "Post-Rock", desc: "Post-rock instrumental sin voz: crescendos largos construidos por capas de guitarra con delay hasta el estallido, y batería que entra tarde y transforma la pieza. Cinematográfico. Entrada: Waking Season.", origin: "lista", p: 3, y: 2004 },
  { name: "Audrey Fall", genre: "Post-Metal", desc: "De Jelgava, Letonia. Post-metal instrumental sin voz, con temas largos que crecen por densidad en vez de por cambio de riff. Su debut, Mitau, es de 2014. Entrada: Mitau.", origin: "lista", p: 3, y: 2010 },

  // ===== HARD ROCK / STONER / ALTERNATIVO 90s-2000s =====
  { name: "Soundgarden", genre: "Grunge / Alt Metal", desc: "Kim Thayil trabaja con afinaciones alternativas raras (llegó a usar una donde todas las cuerdas van a la misma nota) y escribe en compases impares sin que se noten: Spoonman va en siete, My Wave en cinco, Outshined en siete. Y Matt Cameron toca esos compases con un swing pesado que hace que suenen naturales, no a ejercicio. Encima la voz de Chris Cornell con un rango enorme. Bastante más sofisticado de lo que su etiqueta de grunge sugiere. Entrada: Superunknown o Badmotorfinger.", origin: "lista", pick: true, p: 1, y: 1984 },
  { name: "Alice in Chains", genre: "Grunge / Alt Metal", desc: "Jerry Cantrell y Layne Staley armonizan casi todo el tiempo, no solo en los estribillos, y lo hacen en intervalos que chirrían a propósito en vez de sonar dulces, así que la melodía siempre lleva una segunda voz incómoda encima. Debajo, riffs en afinación grave a medio tiempo con mucho wah y talk-box, y Sean Kinney tocando lento y arrastrado. Esa mezcla de armonía vocal y pesadez lenta no la tiene nadie más del movimiento. Entrada: Dirt.", origin: "lista", pick: true, p: 1, y: 1987 },
  { name: "Queens of the Stone Age", genre: "Stoner / Alt Rock", desc: "Homme afina la guitarra a do y toca riffs cortos que repite sin variar durante todo el tema, lo que él llama robot rock, dejando que el groove hipnotice en lugar de desarrollarse; sobre eso mete armonías vocales dulces que chocan con lo áspero del riff. La formación cambia constantemente y en Songs for the Deaf toca Dave Grohl la batería. Entrada: Rated R o Songs for the Deaf.", origin: "lista", pick: true, p: 2, y: 1996, c: 1 },
  { name: "Deftones", genre: "Alt Metal / Shoegaze", desc: "Alt metal donde el peso y la belleza conviven: guitarras de siete y ocho cuerdas afinadas gravísimo bajo capas de shoegaze, la voz de Chino pasando de susurro a grito, y Abe Cunningham tocando con un swing y un uso del charles que casi nadie en el género tiene. Entrada: White Pony o Koi No Yokan.", origin: "lista", pick: true, p: 1, y: 1988 },
  { name: "Lamb of God", genre: "Groove Metal", desc: "Groove metal moderno demoledor con riffs y batería técnica. Referencia del metal de los 2000.", origin: "lista", p: 3, y: 1994 },

  // ===== HARD ROCK / PUNK / SKA / VARIOS LISTA =====
  { name: "NOFX", genre: "Punk Rock", desc: "Punk californiano veloz y melódico, con Fat Mike escribiendo letras sarcásticas sobre estructuras rápidas y simples. Entrada: Punk in Drublic.", origin: "lista", p: 3, y: 1983 },
  { name: "Billy Talent", genre: "Punk / Alt Rock", desc: "Punk rock canadiense con la guitarra de Ian D'Sa haciendo figuras angulares en vez de acordes rasgueados, y una voz muy aguda y nasal que divide. Por debajo, escritura de canción con estribillo. Entrada: Billy Talent II.", origin: "lista", p: 3, y: 1993 },
  { name: "Meat Loaf", genre: "Rock teatral", desc: "Rock operístico escrito por Jim Steinman: canciones de ocho y diez minutos con estructura de varias partes, piano wagneriano, coros enormes y cambios de tempo teatrales. Grandilocuente a propósito. Entrada: Bat Out of Hell.", origin: "lista", pick: true, p: 2, y: 1977 },
  { name: "Jellyfish", genre: "Power Pop", desc: "Los arreglos son objetivamente exquisitos (armonías vocales a cuatro y cinco voces, metales, mellotron, cambios de tonalidad dentro del estribillo) y Spilt Milk es una maravilla de producción en la línea de Queen, los Beach Boys y 10cc. Pero es la trampa Queen otra vez: armonía sofisticada no es complejidad instrumental, y por debajo son canciones pop de tres minutos con forma clásica. Delicioso, no exigente. Entra por Spilt Milk.", origin: "rec", p: 2, y: 1989, c: 2 },
  { name: "The Beatles", genre: "Rock (clásico)", desc: "McCartney toca el bajo como línea melódica independiente que va contra la voz en vez de seguir la raíz (Something, Rain, Dear Prudence), y Ringo aporta un fraseo raro por ser zurdo tocando un kit de diestro, lo que le hace liderar los redobles con la mano débil y desplazar el acento. Encima, invención de estudio real: bucles de cinta en Tomorrow Never Knows, guitarra grabada al revés, y el medley de la cara B de Abbey Road encadenando fragmentos sin cerrar ninguno. Entrada: Revolver o Abbey Road.", origin: "lista", p: 1, y: 1960, c: 1 },

  // ===== THE DEAR HUNTER / NARRATIVO PROG-INDIE =====
  { name: "The Dear Hunter", genre: "Prog / Indie Rock", desc: "Proyecto narrativo ambicioso (la saga Acts más el Color Spectrum, nueve EPs de un color cada uno): mezcla indie, prog, soul y orquestal, con arreglos de metales y cuerda escritos y motivos que reaparecen entre discos. Entrada: Act III.", p: 2, origin: "lista", pick: true, y: 2005 },

  // ===== INDIE / ALT ROCK / GARAGE (gran bloque de tu lista) =====
  { name: "The Strokes", genre: "Indie Rock / Garage", desc: "Indie rock neoyorquino que definió los 2000. Guitarras nerviosas y cool. Clásico moderno.", p: 3, origin: "lista", y: 1998 },
  { name: "Arctic Monkeys", genre: "Indie Rock", desc: "De indie veloz a lounge sofisticado en Tranquility Base, con Alex Turner cambiando de registro vocal y de instrumentación entera entre discos. Entrada: AM.", p: 3, origin: "lista", pick: true, y: 2002, c: 1 },
  { name: "The Last Shadow Puppets", genre: "Indie / Baroque Pop", desc: "Proyecto de Alex Turner (Arctic Monkeys) con orquestaciones cinematográficas. Elegante y dramático.", origin: "lista", p: 3, y: 2007 },
  { name: "Tame Impala", genre: "Psych Pop", desc: "Psicodelia pop de Kevin Parker: cada disco evoluciona del rock al pop electrónico. Texturas hipnóticas.", p: 2, origin: "lista", pick: true, y: 2007, c: 1 },
  { name: "King Gizzard & the Lizard Wizard", genre: "Psych Rock / Experimental", desc: "Rock psicodélico de riff, tocado con energía y muy poca ornamentación. Lo genuinamente valioso está en discos concretos, sobre todo cuando se afinaron guitarras microtonales para trabajar con intervalos fuera del temperamento occidental, y en Polygondwanaland con sus compases impares. El resto es garage sólido pero sencillo. Entra por Polygondwanaland.", origin: "rec", p: 2, y: 2010, c: 1 },
  { name: "MGMT", genre: "Psych Pop", desc: "De hits psicodélicos pop a experimentación rara. Imprevisibles.", p: 3, origin: "lista", y: 2002, c: 1 },
  { name: "Portugal. The Man", genre: "Psych / Alt Rock", desc: "Rock psicodélico-pop con groove y experimentación. Versátiles.", p: 3, origin: "lista", y: 2004 },
  { name: "Nothing but Thieves", genre: "Alt Rock", desc: "Alt rock con voz aguda potente (ecos de Radiohead/Muse) y buen drama. Recomendable.", p: 3, origin: "lista", y: 2012 },
  { name: "Royal Blood", genre: "Hard Rock / Blues", desc: "Dúo de bajo y batería sin guitarra: Mike Kerr divide la señal del bajo con un octavador y la manda a varios amplificadores a la vez, unos de bajo y otros de guitarra, para cubrir los dos registros y sonar como si hubiera guitarrista, mientras Ben Thatcher toca un groove muy pesado y simple que deja el hueco. Entrada: Royal Blood (2014).", origin: "lista", pick: true, p: 2, y: 2011 },
  { name: "The Black Keys", genre: "Blues Rock / Garage", desc: "Dúo de blues-rock crudo y pegadizo. Groove sucio. Clásico moderno.", p: 3, origin: "lista", y: 2001 },
  { name: "Death from Above 1979", genre: "Dance Punk / Noise", desc: "Dúo de bajo y batería, sin guitarra: Jesse Keeler toca el bajo por amplificadores de guitarra con distorsión y pedales de octava para cubrir todo el rango, y Sebastien Grainger toca la batería y canta a la vez, con un groove bailable dentro de algo que suena a ruido. Es tu combinación de instrumentos favorita reducida al mínimo posible. Entrada: You're a Woman, I'm a Machine.", origin: "lista", p: 2, y: 2001 },
  { name: "The Killers", genre: "Indie / Arena Rock", desc: "Rock alternativo de estadios con sintetizadores y estribillos enormes. Himnos.", p: 3, origin: "lista", y: 2001 },
  { name: "Catfish and the Bottlemen", genre: "Indie Rock", desc: "Indie rock británico directo y enérgico, de estribillos grandes. Guitarrero.", p: 3, origin: "lista", y: 2007 },
  { name: "Kasabian", genre: "Indie / Electronic Rock", desc: "Rock británico con groove electrónico y psicodelia. Bailable y potente.", p: 3, origin: "lista", y: 1997 },
  { name: "Two Door Cinema Club", genre: "Indie Pop", desc: "Indie pop bailable con guitarras brillantes y ritmo. Luminoso.", p: 3, origin: "lista", y: 2007 },
  { name: "Wolf Alice", genre: "Alt Rock / Dream Pop", desc: "Británicos que van del dream pop al grunge en un mismo disco. Versátiles y premiados. (voz femenina)", p: 3, origin: "lista", female: true, pick: true, y: 2010 },
  { name: "Franz Ferdinand", genre: "Indie / Post-Punk Revival", desc: "Post-punk bailable con riffs angulares y un bajo que marca el groove por encima del bombo. Muy eficaz y muy dentro de fórmula. Entrada: Franz Ferdinand.", origin: "lista", p: 3, y: 2002 },
  { name: "Foals", genre: "Math Rock / Indie", desc: "Indie con math rock: las dos guitarras tocan líneas cortas entrelazadas que se desfasan en vez de acordes, sobre el groove de Jack Bevan, y de ahí crecen a lo épico. Entrada: Antidotes o Holy Fire.", origin: "rec", p: 3, y: 2005, via: "Indie" },
  { name: "The 1975", genre: "Pop / Alt", desc: "Pop alternativo camaleónico y autoconsciente: cada disco cambia de paleta entera (synth-pop ochentero, ambient instrumental, country, garage), con George Daniel produciendo y tocando la batería, y arreglos de saxofón y cuerda metidos donde no se esperan. Matty Healy escribe letras que comentan el propio disco mientras suena. Ecléctico de verdad, aunque la escritura por debajo es de canción pop. Entrada: A Brief Inquiry Into Online Relationships.", origin: "lista", p: 3, y: 2002, c: 1 },
  { name: "The Wombats", genre: "Indie Pop", desc: "Indie pop británico ingenioso y bailable, letras con humor. Pegadizo.", p: 3, origin: "lista", y: 2003 },
  { name: "FIDLAR", genre: "Garage Punk", desc: "Garage punk californiano crudo y rápido, grabado sucio a propósito. Divertido y directo, sin ambición instrumental por debajo. Entrada: FIDLAR.", origin: "lista", p: 3, y: 2009 },
  { name: "SWMRS", genre: "Garage Punk", desc: "Garage punk juvenil de California, crudo y directo, con producción deliberadamente barata. Poco que rascar por debajo. Entrada: Drive North.", origin: "lista", p: 3, y: 2004 },
  { name: "The Districts", genre: "Indie Rock", desc: "Indie rock con raíz folk y crescendos emotivos. Honesto.", p: 3, origin: "lista", y: 2009 },
  { name: "Rolling Blackouts Coastal Fever", genre: "Indie / Jangle", desc: "Indie australiano de guitarras entrelazadas y ritmo constante. Luminoso y literario.", p: 3, origin: "lista", y: 2013 },
  { name: "The Growlers", genre: "Surf / Psych Rock", desc: "'Beach goth': surf rock psicodélico y relajado con groove raro. Atmósfera única.", p: 3, origin: "lista", y: 2006 },
  { name: "Black Box Revelation", genre: "Garage / Blues Rock", desc: "Dúo belga de garage-blues crudo. Riffs sucios.", p: 3, origin: "lista", y: 2005 },
  { name: "Sticky Fingers", genre: "Indie / Reggae Rock", desc: "Indie australiano con reggae y psicodelia. Relajado y groovy.", p: 3, origin: "lista", y: 2008 },
  { name: "The Garden", genre: "Experimental Punk", desc: "Dúo de gemelos: punk experimental minimalista y excéntrico ('Vada Vada'). Raro y enérgico.", p: 3, origin: "lista", y: 2011 },
  { name: "Vundabar", genre: "Indie Rock", desc: "Indie con guitarras nerviosas y dinámica tensa-suelta. Melódico y angular.", p: 3, origin: "lista", y: 2013 },
  { name: "Saint Motel", genre: "Indie Pop", desc: "Indie pop cinematográfico con vientos y groove. Elegante y divertido.", p: 3, origin: "lista", y: 2007 },
  { name: "Walk the Moon", genre: "Indie Pop / Synth", desc: "Indie pop enérgico con sintetizadores y estribillos de estadio. Festivo.", p: 3, origin: "lista", y: 2006 },

  // ===== INDIE / ELECTRÓNICO / CHILL / SOUL =====
  { name: "alt-J", genre: "Indie / Art Pop", desc: "Indie experimental con armonías raras, folktrónica y estructuras peculiares. Muy distintivo.", origin: "lista", pick: true, p: 3, y: 2007 },
  { name: "Phantogram", genre: "Electro / Dream Pop", desc: "Dúo de electro-rock atmosférico con voz femenina y beats densos. Oscuro y pegadizo. (voz femenina)", p: 3, origin: "lista", female: true, y: 2007 },
  { name: "Jungle", genre: "Modern Funk / Soul", desc: "Colectivo de funk-soul moderno bailable, con groove y falsetes. Luminoso.", origin: "lista", p: 3, y: 2013 },
  { name: "Local Natives", genre: "Indie Folk / Rock", desc: "Indie con armonías vocales exuberantes y percusión. Cálido y melódico.", origin: "lista", p: 3, y: 2005 },
  { name: "Still Woozy", genre: "Bedroom Pop", desc: "Bedroom pop groovy y juguetón, producción casera cálida. Relajado.", p: 3, origin: "lista", y: 2017 },
  { name: "Slenderbodies", genre: "Indie / R&B", desc: "Indie-R&B etéreo y suave, falsetes y atmósfera. Chill.", p: 3, origin: "lista", y: 2016 },
  { name: "Crooked Colours", genre: "Electronic / Dance", desc: "Electrónica indie australiana bailable y atmosférica, con groove claro y estructura de canción. Bien producida, sin ambición instrumental por debajo. Entrada: Vera.", origin: "lista", p: 3, y: 2013 },
  { name: "Coast Modern", genre: "Indie Pop", desc: "Indie pop soleado y ecléctico, mezcla estilos con actitud relajada.", p: 3, origin: "lista", y: 2015 },

  // ===== ART POP / SINGER-SONGWRITER / TEATRAL =====
  { name: "Radiohead", genre: "Art Rock / Experimental", desc: "Jonny Greenwood mete ondas Martenot y arreglos orquestales escritos por él, y la banda trabaja compases raros sin anunciarlos (15 Step va en cinco, Pyramid Song tiene un pulso deliberadamente ambiguo que nadie sabe contar a la primera). En Kid A y Amnesiac cambiaron la instrumentación entera por electrónica y metales de jazz. Entra por Kid A o In Rainbows.", origin: "rec", p: 1, y: 1985, c: 1 },
  { name: "Depeche Mode", genre: "Synth-Pop / Dark Wave", desc: "Synth-pop oscuro que fue endureciéndose hasta lo industrial y lo bluesero: Martin Gore escribe casi todo y Alan Wilder, mientras estuvo, construía los arreglos a base de samples de percusión metálica grabados por él en vez de cajas de ritmo de catálogo, lo que da ese sonido áspero de Violator y Songs of Faith and Devotion. Voz de barítono de Dave Gahan encima. Entrada: Violator.", origin: "lista", p: 2, y: 1980 },
  { name: "Jeff Buckley", genre: "Singer-Songwriter / Art Rock", desc: "Voz angelical de rango enorme y guitarra etérea. 'Grace' es un disco de culto absoluto. Emotivo y único.", origin: "lista", p: 2, y: 1991 },
  { name: "The Dresden Dolls", genre: "Cabaret Punk", desc: "Punk cabaret de dos personas: Amanda Palmer al piano tocado con violencia percusiva y Brian Viglione a la batería haciendo de banda entera, con dinámicas de casi silencio a golpe seco y un fraseo de cabaret alemán. Sin bajo y sin guitarra. Entrada: The Dresden Dolls (2003). (voz femenina)", origin: "lista", female: true, pick: true, p: 2, y: 2000 },
  { name: "The Hush Sound", genre: "Indie / Piano Pop", desc: "Indie pop con piano y voces dual (masc/fem). Melódico y cálido. (voz femenina compartida)", p: 3, origin: "lista", female: true, y: 2004 },
  { name: "Marianas Trench", genre: "Pop Rock / Theatrical", desc: "Pop rock canadiense teatral con armonías vocales muy densas a varias voces y discos conceptuales montados como suite, con reprises que recuperan melodías de temas anteriores al final del álbum. Muy elaborado para ser pop. Entrada: Masterpiece Theatre.", origin: "lista", pick: true, p: 3, y: 2001 },
  { name: "Sarah and the Safe Word", genre: "Theatrical / Cabaret Rock", desc: "Rock teatral de cabaret con dramatismo y vientos. Excéntrico y enérgico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2016 },

  // ===== EMO / POP PUNK / ALT MODERNO =====
  { name: "My Chemical Romance", genre: "Emo / Alt Rock", desc: "Emo teatral y conceptual: The Black Parade está construido como ópera rock, con banda de marcha, piano, orquestación y personajes, y las canciones encadenan secciones en vez de repetir estribillo. Entrada: The Black Parade.", origin: "lista", pick: true, p: 2, y: 2001 },
  { name: "Paramore", genre: "Pop Punk / Alt", desc: "De pop punk a new wave y pop sofisticado, con un cambio real de sonido en After Laughter: guitarras limpias con delay al estilo Talking Heads y la batería de Zac Farro tocando figuras sincopadas y ligeras en vez de marcar. Hayley Williams canta con un control de registro poco común en el género. Entrada: After Laughter.", origin: "lista", female: true, pick: true, p: 2, y: 2004, c: 1 },
  { name: "Palaye Royale", genre: "Glam / Alt Rock", desc: "Glam rock teatral moderno con estética visual fuerte. Dramático.", origin: "lista", p: 3, y: 2008 },
  { name: "I Don't Know How But They Found Me", genre: "Retro Pop Rock", desc: "Pop rock retro de estética setentera y ochentera montado por Dallon Weekes, que toca bajo y canta a la vez y escribe casi todo: bajo muy melódico y adelante en la mezcla, teclados antiguos y estructuras de canción corta con giros teatrales. Pegadizo y peculiar, sin más ambición que esa. (IDKHOW) Entrada: Razzmatazz.", origin: "lista", p: 3, y: 2016 },
  { name: "The Brobecks", genre: "Indie / Power Pop", desc: "Proyecto previo de Dallon Weekes (IDKHOW): power pop excéntrico y melódico. De culto.", origin: "lista", p: 3, y: 2002 },
  { name: "Set It Off", genre: "Pop Rock / Pop Punk", desc: "Pop punk teatral con arreglos orquestales encima de canciones de estructura convencional. Dramático y pegadizo. Entrada: Cinematics.", origin: "lista", p: 3, y: 2008 },
  { name: "Måneskin", genre: "Glam Rock", desc: "Glam rock italiano enérgico y sensual que revivió el rock mainstream. Actitud.", origin: "lista", p: 3, y: 2016 },
  { name: "Jhariah", genre: "Experimental / Theatrical", desc: "Mezcla emo, teatral, hyperpop y prog con energía caótica: cambios bruscos de estilo dentro del mismo tema, voz procesada y arreglos densos hechos en casa. Joven y muy creativo. Entrada: A Beginner's Guide to Faking Your Death.", p: 3, origin: "lista", pick: true, y: 2019 },

  // ===== NOMBRES POR CONFIRMAR / RAROS =====
  { name: "Ghost Ship Octavius", genre: "Prog / Melodic Metal", desc: "Prog metal melódico (miembros de Nevermore/God Forbid). Atmosférico.", p: 3, origin: "lista", y: 2012 },
  { name: "Hell or Highwater", genre: "Hard Rock", desc: "Hard rock melódico de estructura convencional y producción de radio, montado por el batería de Atreyu. Entrada: Begin Again.", origin: "lista", p: 3, y: 2011 },
  { name: "Andrelamusia", genre: "Deathcore / Symphonic / Djent", desc: "Haifa, Israel, 2016 (se estilizan AndrelamusiA). Deathcore melodico con capas sinfonicas y ritmica djent, con letras basadas en el manga Berserk. Ganaron el Metal Battle israeli y representaron al pais en Wacken. Su unico disco, Pandemonium (2022), esta bien ejecutado, pero se mueve dentro del molde de Shadow of Intent y Periphery: la complejidad es heredada, no propia.", origin: "lista", p: 3, y: 2022, c: 2 },
  { name: "2 Shadows", genre: "Alt Rock / Post-Grunge", desc: "Banda canadiense de rock alternativo, no metalcore como figuraba aqui. Se hicieron virales con Goths in Ungothly Places y publicaron el EP Bring the Cold Inside (2022) antes de girar por Estados Unidos con The Veer Union. Rock alternativo de radio, correcto y sin aristas.", origin: "lista", p: 3, y: 2022, c: 2 },
  { name: "DVL", genre: "Heavy Metal / Metalcore", desc: "Glasgow, Escocia. Metal moderno que alterna limpios y guturales. Dos discos: The Pawn That Took the King y Hush (2023, WormHoleDeath), este ultimo un conceptual de relatos cortos sobre salud mental. Solido y bien producido, pero dentro del molde.", origin: "lista", p: 3, y: 2023, c: 2 },
  { name: "Defecto", genre: "Prog / Power Metal", desc: "Prog/power metal danés melódico y técnico. Buena voz.", p: 3, origin: "lista", y: 2014 },
  { name: "Eastern High", genre: "Alt Rock / Prog", desc: "Rock alternativo danés melódico. Poco conocido. A confirmar.", p: 3, origin: "lista" },
  { name: "Nekrogoblikon", genre: "Melodic Death / Folk", desc: "Melodeath cómico sobre goblins, con teclados y mucho gancho. Divertido y técnico.", origin: "lista", pick: true, p: 3, y: 2006 },
  { name: "Damage Control", genre: "Hard Rock", desc: "Supergrupo britanico de 2007: Spike (The Quireboys) a la voz, Pete Way (UFO) al bajo, Chris Slade (AC/DC) a la bateria y Robin George a la guitarra. Dos discos entre 2007 y 2008. Curriculum enorme y hard rock clasico y directo: el cartel no compensa la falta de ambicion instrumental, asi que se queda donde le corresponde por lo que suena, no por quien lo toca.", origin: "lista", p: 3, y: 2007, c: 2 },
  { name: "CrazyEightyEight", genre: "Post-Hardcore / Metalcore", desc: "El nombre real lleva Y: CrazyEightyEight. Proyecto nacido por internet con Lauren Babic (Red Handed Denial) a la voz junto a Jarrod Alonge y Patty Walters (As It Is) repartiendose guitarras y bajo. Post-hardcore agresivo y melodico, con Babic alternando limpios y guturales de verdad. El cartel es llamativo, pero la escritura es de genero, no instrumentalmente ambiciosa.", origin: "lista", p: 3, y: 2021, c: 2 },
  { name: "Hacride", genre: "Prog / Groove Metal", desc: "Prog/groove metal francés denso y atmosférico. Subestimado.", p: 2, origin: "lista", pick: true, y: 2001 },
  { name: "Klone", genre: "Prog / Atmospheric Metal", desc: "Prog francés atmosférico y melódico, que viró a algo más rock y emotivo. Recomendable.", p: 2, origin: "lista", pick: true, y: 1995, c: 1 },
  { name: "Trepalium", genre: "Groove / Jazz Metal", desc: "Groove metal francés con jazz y swing. Muy peculiar y técnico.", origin: "lista", pick: true, p: 2, y: 2000 },
  { name: "I, Omega", genre: "Progressive Metalcore", desc: "Quinteto de Los Angeles fichado por Bullet Tooth. Metalcore progresivo con un punto de southern metal en los riffs; su disco es Transients. Cambios de compas y riffs pegadizos, pero digerible por diseno: la banda misma se describe asi.", origin: "lista", p: 3, y: 2014, c: 2 },
  { name: "Unparalleled Height", genre: "Progressive Metalcore", desc: "Quinteto autogestionado de Pittsburgh activo desde 2010. Metalcore con inclinación progresiva; su segundo disco es Rise of the Voiceless.", origin: "lista", p: 3, y: 2013, c: 2 },
  { name: "Ember Oceans", genre: "Synth Rock / Indie Pop", desc: "Proyecto de Chicagoland liderado por Freddy Tyler Paul, no metalcore como figuraba aqui: synth-rock colorido de produccion densa y voz deliberadamente teatral. EP Sleepwalk.", origin: "lista", p: 3, y: 2023, c: 2 }
];

// Recomendaciones previas de Claude que NO estaban en la lista original (para no perderlas)
const PRIOR_RECS = [
  // Veta Queen
  { name: "Kate Bush", genre: "Art Pop / Experimental", desc: "Art pop con arreglos poco ortodoxos, usando el Fairlight como instrumento y no como truco, y en la segunda cara de Hounds of Love una suite continua con instrumentación folk irlandesa (uilleann pipes, fiddle) sobre estructuras que no vuelven al estribillo. Sofisticada de arreglo y de producción más que compleja de ejecución, y por tu filtro eso la deja aquí. Entra por Hounds of Love. (voz femenina)", origin: "rec", p: 2, y: 1978, c: 1, female: true },
  { name: "Renaissance", genre: "Symphonic Prog Rock", desc: "Prog sinfónico setentero con Annie Haslam, soprano de cinco octavas de rango, cantando sobre arreglos orquestales escritos y piano de raíz clásica en vez de guitarra: la banda apenas usa distorsión y construye a base de cuerda, coro y contrapunto. Scheherazade es una suite de veinticuatro minutos basada en Rimski-Kórsakov. (voz femenina)", origin: "rec", female: true, p: 3, y: 1969, via: "Queen" },
  { name: "Florence + The Machine", genre: "Art Pop / Baroque", desc: "Art pop de escala coral: arpa como instrumento principal en lugar de guitarra, percusión de tambor grande muy adelante, y capas de voz propias apiladas hasta sonar a coro. Florence Welch canta con una proyección enorme y las canciones crecen por acumulación en vez de por estribillo. Entrada: Lungs o Ceremonials. (voz femenina)", origin: "rec", female: true, p: 3, y: 2007, via: "Queen" },
  { name: "Heart", genre: "Hard Rock", desc: "Las hermanas Wilson: Ann canta con un rango y una potencia enormes y Nancy toca guitarra acústica de digitación abierta, algo poco común en el hard rock de los setenta, así que los discos alternan riffs pesados con pasajes casi folk (Crazy on You lo hace dentro del mismo tema). Entrada: Dreamboat Annie o Little Queen. (voz femenina)", origin: "rec", female: true, p: 2, y: 1973, via: "Queen" },
  { name: "Sparks", genre: "Art Pop / Glam", desc: "Seis décadas reinventándose sin repetirse: glam, synth-pop, ópera, pop de cámara. Lil' Beethoven (2002) abandonó por completo el beat electrónico por repetición y arreglos casi clasicistas, y funcionó. Su disco 26, Mad! (2025), fue el más alto en listas de toda su carrera. Armonía retorcida bajo apariencia camp. Entrada: Kimono My House, luego Lil' Beethoven.", origin: "rec", p: 1, y: 1971, via: "Queen", c: 1 },
  { name: "Annie Lennox / Eurythmics", genre: "Synth Pop / Art", desc: "Synth pop construido por dos personas: Dave Stewart programaba secuencias y cajas de ritmo mientras Annie Lennox cantaba con un registro de contralto muy grave para el pop de la época, alternando frialdad mecánica de la base con interpretación teatral encima. Ese contraste es todo el asunto. Entrada: Sweet Dreams (Are Made of This). (voz femenina)", origin: "rec", female: true, p: 2, y: 1980, via: "Queen" },
  { name: "Bat for Lashes", genre: "Art Pop / Dream", desc: "Art pop atmosférico de Natasha Khan: construye sobre clavicémbalo, arpa, percusión de mano y sintetizador antiguo en vez de banda de rock, con armonías modales y estructuras que no vuelven al estribillo. Onírico y con narrativa de personajes. Entrada: Two Suns. (voz femenina)", origin: "rec", female: true, p: 3, y: 2006, via: "Queen" },
  { name: "Grace Slick / Jefferson Airplane", genre: "Psych Rock", desc: "Voz potente y dominante sobre psicodelia compleja 60s-70s. 'White Rabbit'. (voz femenina)", p: 2, origin: "rec", female: true, y: 1965, via: "Queen" },
  { name: "St. Vincent", genre: "Art Rock / Experimental", desc: "Guitarrista excepcional, arreglos angulares y mucho control del drama. Cada disco reinventa. (voz femenina)", p: 2, origin: "rec", female: true, y: 2006, via: "Queen" },
  // Veta A7X / PTH
  { name: "Coheed and Cambria", genre: "Prog Rock", desc: "Veta A7X: prog con saga conceptual gigante, voz aguda y complejidad con ganchos.", origin: "rec", p: 3, y: 1995, via: "A7X" },
  { name: "Ne Obliviscaris", genre: "Prog / Extreme Metal", desc: "Prog extremo con el violín de Tim Charles como instrumento co-líder, no de adorno, y Dan Presland (que volvió en 2024) en una batería descomunal. Australianos como Be'lakor pero mucho más ambiciosos. Entrada: Exul, luego Citadel.", origin: "rec", p: 1, y: 2003, via: "A7X" , c: 2 },
  { name: "Be'lakor", genre: "Melodic Death / Prog", desc: "Escriben temas de ocho a doce minutos con desarrollo real, donde un tema de guitarra vuelve transformado varios minutos después y las secciones instrumentales largas llevan el peso en vez de rellenar entre estrofas, con piano y guitarra limpia entretejidos dentro del riff. Australianos, y de lo más compositivamente ambicioso del melodeath actual. Entra por Vessels o Stone's Reach.", origin: "heard", p: 1, y: 2004, c: 2 },
  { name: "Omnium Gatherum", genre: "Melodic Death", desc: "Melodeath con teclados atmosféricos y melodías enormes, mucho gancho.", origin: "rec", p: 3, y: 1996, via: "A7X" },
  // Veta PTH técnico
  { name: "The Safety Fire", genre: "Prog Metal", desc: "Veta PTH: prog técnico británico melódico. Dos discos excelentes.", p: 2, origin: "rec", y: 2006, via: "PTH" },
  { name: "Periphery", genre: "Djent / Prog", desc: "Veredicto suyo: le gustan y los ve muy unicos, no ha escuchado otra banda con ese sonido. Le gusta todo desde Periphery II; favoritos los dos Juggernaut, Alpha y Omega. A Pale White Dot y Periphery V le parecieron solo correctos, sin salir de su terreno. La sustancia: contrapunto de tres guitarras con lineas distintas en vez de dobladas, sobre la bateria de Matt Halpern, que frasea contra el riff y no con el.", origin: "rec", pick: true, y: 2005, via: "PTH", p: 1 , c: 2 },
  { name: "Spiritbox", genre: "Metalcore / Djent", desc: "Moderna con voz femenina de rango enorme; metalcore etéreo + brutal. (voz femenina)", p: 2, origin: "rec", female: true, y: 2017, via: "PTH" },
  { name: "Jinjer", genre: "Groove / Prog Metal", desc: "Voz femenina que alterna limpio precioso y gutural brutal; groove técnico. (voz femenina)", p: 2, origin: "rec", female: true, y: 2008, via: "PTH" }
];

// Bandas que Ken YA escuchó y que no estaban en el catálogo. Se precargan como escuchadas.
const HEARD_SEED = [
  { name: "Avenged Sevenfold", genre: "Metalcore / Hard Rock", desc: "Ken lo usa como vara de medir, y la musica lo sostiene: The Rev escribia partes de bateria con forma propia, con dobles bombos en tresillos y fills que reordenan el compas en vez de rellenarlo, y Synyster Gates y Zacky Vengeance trabajan armonias gemelas y solos construidos sobre progresiones de raiz neoclasica. City of Evil abandona el screamo por completo y The Stage estira las estructuras hasta los quince minutos con orquesta. Favoritos suyos: City of Evil, el homonimo, The Stage, Nightmare, Waking the Fallen y Life Is But a Dream; menos Hail to the King. Entrada: City of Evil.", origin: "heard", y: 1999, p: 1, c: 1 },
  { name: "Mastodon", genre: "Prog / Sludge Metal", desc: "La bateria de Brann Dailor es melodica: toca frases con forma propia en vez de marcar, y buena parte de los temas se sostienen sobre ella. Guitarras en armonia a dos voces sobre metrica cambiante, y estructuras que no repiten estribillo. Entrada: Crack the Skye, luego Leviathan.", origin: "heard", pick: true, y: 2000, p: 1 , c: 1 },
  { name: "Between the Buried and Me", genre: "Prog Metal / Tech", desc: "Death técnico, prog, jazz, bluegrass y pasajes acústicos dentro de una misma canción, con cambios de compás constantes, sin repetir estructura y con Blake Richardson a la batería sosteniendo esos saltos. Colors (2007) son sesenta y cinco minutos continuos, sin cortes reales entre temas. Entra por Colors.", origin: "rec", pick: true, y: 2000, p: 1, c: 1 },
  { name: "Dream Theater", genre: "Prog Metal", desc: "Suites de veinte minutos con desarrollo temático de verdad, cambios de compás dentro de la frase y unísonos escritos entre teclado y guitarra que exigen precisión de conjunto. Lo hacen desde Images and Words hasta hoy, con Scenes from a Memory como obra conceptual entera. Entrada: Metropolis Pt. 2.", origin: "heard", y: 1985, p: 1 , c: 2 },
  { name: "Protest the Hero", genre: "Tech Metalcore / Prog", desc: "Una de tus varas de medir, y la música lo sostiene: Luke Hoskin y Tim Millar escriben líneas de guitarra que van por su cuenta en vez de doblarse, con cambios de compás constantes dentro del mismo tema y armonías casi neoclásicas, mientras Rody Walker canta melodías limpias muy agudas por encima de todo ese lío. Canadienses. Entra por Fortress o Kezia.", origin: "rec", p: 1, y: 1999, c: 2 },
  { name: "Meshuggah", genre: "Djent / Extreme Prog", desc: "Riffs en ciclos de longitud impar sobre un charles fijo en 4/4, así que el patrón tarda varios compases en cuadrar otra vez: la polirritmia es la estructura, no un efecto. Y llevan de Destroy Erase Improve a Immutable puliendo esa idea sin repetir disco. Entrada: obZen.", origin: "heard", pick: true, y: 1987, p: 1 , c: 2 },
  { name: "Gojira", genre: "Prog / Groove Metal", desc: "Franceses, y el motor es la batería: Mario Duplantier toca patrones que cambian de subdivisión bajo el mismo riff y usa el bombo como elemento melódico, mientras Joe hace pick slides y armónicos que suenan a ballena. Groove pesadísimo con atmósfera, y cada disco evoluciona. Entrada: From Mars to Sirius o Magma.", origin: "heard", pick: true, y: 1996, p: 1 , c: 2 },
  { name: "Destrage", genre: "Tech / Math Metal", desc: "Italianos: metal técnico hiperactivo que salta de riff mathcore a estribillo melódico y a groove funk en segundos, con la batería cambiando de estilo a la misma velocidad. Caótico y pegadizo a la vez. Entrada: Are You Kidding Me? No.", p: 2, origin: "heard", pick: true, y: 2007 },
  { name: "Killswitch Engage", genre: "Metalcore", desc: "Referencia del metalcore melódico moderno: balance limpio/gutural y solos. Ya escuchado.", p: 3, origin: "heard", y: 1999 },
  { name: "Alter Bridge", genre: "Hard Rock / Alt Metal", desc: "Hard rock con Mark Tremonti escribiendo riffs armonizados a dos guitarras y solos con desarrollo, y Myles Kennedy cantando en un registro muy alto sostenido. Bien tocado y melódico, pero la estructura es de canción con estribillo en casi todo el catálogo. Entrada: Blackbird.", origin: "heard", p: 3, y: 2004 },
  { name: "Bullet for My Valentine", genre: "Metalcore", desc: "Metalcore galés melódico con solos y estribillos. Ya escuchado.", p: 3, origin: "heard", y: 1998 },
  { name: "Ice Nine Kills", genre: "Metalcore / Theatrical", desc: "Metalcore teatral conceptual basado en cine de terror. Cada canción, una película. Ecléctico y narrativo.", p: 2, origin: "heard", pick: true, y: 2006 },
  { name: "Behemoth", genre: "Blackened Death", desc: "Riffs de tremolo rapidos, bateria de Inferno muy tecnica al doble bombo, y a partir de ahi coros, orquestacion y arreglos que si cambian de disco a disco. Entra por The Satanist.", origin: "heard", p: 2, y: 1991, c: 2 },
  { name: "Atreyu", genre: "Metalcore", desc: "Metalcore melódico de los 2000 con solos y estribillos limpios. Ya escuchado.", p: 3, origin: "heard", y: 1998 },
  { name: "Machine Head", genre: "Groove / Thrash Metal", desc: "Groove metal robusto con momentos épicos y técnicos. Veteranos potentes.", origin: "heard", p: 3, y: 1991 },
  { name: "Mutiny Within", genre: "Melodic Death / Prog", desc: "Melodeath progresivo estadounidense con teclados y limpio/gutural. Subestimado.", origin: "heard", p: 3, y: 2002 },
  { name: "Pentakill", genre: "Power / Heavy Metal", desc: "Banda virtual de League of Legends: power metal épico con invitados de lujo. Divertido y bien hecho.", origin: "heard", p: 4, y: 2014 },
  { name: "Metallica", genre: "Thrash / Heavy Metal", desc: "En su gran mayoría no te gusta: la encuentras aburrida muchas veces y lo reciente directamente mediocre. Lo medio salvable son los primeros discos y, de lo moderno, Death Magnetic. Aun en sus mejores momentos se queda por debajo de tu nivel de exigencia instrumental. Se conserva por contexto histórico, no como recomendación. Prefieres Megadeth.", origin: "heard", y: 1981, p: 4 },
  { name: "Megadeth", genre: "Thrash Metal", desc: "Te gusta más que Metallica: hay algo más de técnica y algo más de ambición en la escritura, sobre todo en el trabajo de guitarra a dos voces y en los cambios de Rust in Peace. Sigue sin ser un pilar tuyo, pero queda por encima del resto de los Big Four.", origin: "heard", y: 1983, p: 3 },
  { name: "Pantera", genre: "Groove Metal", desc: "Los reyes del groove metal. Ya escuchado.", origin: "heard", p: 3, y: 1981 },
  { name: "Iron Maiden", genre: "Heavy Metal (clásico)", desc: "El bajo de Steve Harris toca líneas melódicas propias al galope que discuten con la guitarra, y desde 1999 son tres guitarristas armonizando a tres voces. Escriben largo de verdad: Rime of the Ancient Mariner son trece minutos y medio. Tu mapa por etapas: muy buenos hasta Seventh Son, luego un bloque más flojo, y con la vuelta de Bruce en Brave New World una evolución real sobre lo que ya hacían, de donde salen tus favoritos, A Matter of Life and Death y Dance of Death. Su punto más débil para ti es la batería. Entra por A Matter of Life and Death.", origin: "heard", p: 1, y: 1975, c: 2 },
  { name: "Slipknot", genre: "Nu Metal", desc: "Nu metal brutal y teatral de nueve miembros. Ya escuchado.", origin: "heard", p: 3, y: 1995 },
  { name: "In Flames", genre: "Melodic Death", desc: "Tus favoritos son los primeros discos, y aunque de Reroute to Remain en adelante siguen teniendo cosas buenas (te gusta el más reciente), siempre vuelves a los primeros. Esa etapa clásica de The Jester Race, Whoracle y Colony son armonías gemelas de guitarra con giros de folk sueco sobre riffs rápidos y batería contenida. De Reroute en adelante se fueron a estribillos limpios, electrónica y estructura de rock alternativo. La categoría 1 se queda porque el cambio es real, aunque el resultado te convenza menos. Entra por The Jester Race.", origin: "heard", p: 2, y: 1990, c: 1 },
  { name: "Dethklok", genre: "Melodic Death (Metalocalypse)", desc: "Te parece muy bueno, con sustancia de disco a disco y bastante consistente, y no hay ningún álbum que te desagrade. No es una broma tocada de cualquier manera: lo escribe y lo toca Brendon Small con Gene Hoglan a la batería, con riffs de verdad, armonías gemelas y solos con desarrollo, bajo una producción limpia y muy tocada. Nació como banda de una serie pero se sostiene sola. Entra por Dethalbum II.", origin: "heard", p: 2, y: 2006, c: 2 },
  { name: "Guns N' Roses", genre: "Hard Rock", desc: "Hard rock clásico con el fraseo suelto y bluesero de Slash frente a Izzy Stradlin haciendo la rítmica, y la voz nasal y agudísima de Axl. Appetite for Destruction es directo y sin adornos; Use Your Illusion se va a canciones largas con piano y orquesta. Entrada: Appetite for Destruction.", origin: "heard", p: 3, y: 1985 },
  { name: "Rise Against", genre: "Melodic Hardcore / Punk", desc: "Punk-hardcore melódico con mensaje social. Ya escuchado.", p: 3, origin: "heard", y: 1999 },
  { name: "Muse", genre: "Alt Rock / Prog", desc: "Es rock de estadio con gestos de prog, no prog: la crítica lo resume como apropiarse de los recursos del progresivo sin quedarse con la sustancia. Sus cambios de disco a disco son de estilo, no de estructura, y The Resistance es Queen reciclado de forma bastante literal. Bellamy toca bien, pero la escritura es de canción pop amplificada. Se queda en alta afinidad porque es ambicioso de intención, no porque compita con lo que tienes arriba.", origin: "rec", p: 2, y: 1994, c: 2 },
  { name: "Ghost", genre: "Occult Rock / Metal", desc: "Rock melódico de raíz doom con estribillos enormes y armonías de guitarra a dos voces, muy bien escrito, con estructura de canción clásica y producción limpia. Prequelle es su disco con más peso instrumental: Miasma lleva un solo de saxofón y Helvetesfönster es otra pieza sin voz, y es justo el que te había gustado. Entrada: Prequelle o Meliora.", origin: "heard", p: 2, y: 2006, c: 1 },
  { name: "Cage the Elephant", genre: "Alt Rock / Garage", desc: "Rock alternativo de riff directo con estribillos grandes, que va del garage sucio de los primeros discos al pop rock pulido de Social Cues, siempre en formato canción de cuatro minutos. Bien tocado y con energía, pero sin ambición instrumental. Entra por Melophobia.", origin: "heard", p: 3, y: 2006, c: 1 },
  { name: "Glass Animals", genre: "Indie / Psych Pop", desc: "Indie pop psicodélico texturado y groovy. Ya escuchado.", p: 3, origin: "heard", y: 2010 },
  { name: "Siames", genre: "Indie / Alt Rock", desc: "Proyecto argentino atmosférico y narrativo (los videos animados). Oscuro y melódico. Ya escuchado.", p: 3, origin: "heard", y: 2011 },
  { name: "Panic! at the Disco", genre: "Pop Rock / Theatrical", desc: "En general te gustan, pero sobre todo lo primero, y Pretty. Odd. es tu favorito de todo el artista; del último dices que sorprende y que sientes que vuelven a sus raíces. Lo que hay de verdad: A Fever You Can't Sweat Out mete acordeón, electrónica y arreglos de cabaret dentro del pop-punk, y Pretty. Odd. es un disco orquestal de vientos y cuerdas con escritura muy de los Beatles tardíos, grabado con banda entera. De Vices & Virtues en adelante se concentra en Brendon Urie y se vuelve pop más directo. Entra por Pretty. Odd.", origin: "heard", p: 2, y: 2004, c: 1 },
  { name: "BTS", genre: "K-Pop", desc: "Producción de pop de altísimo presupuesto que cambia de registro entre discos (hip-hop, EDM, disco, R&B, balada orquestal), con arreglos vocales repartidos entre siete voces de timbres distintos y coreografía pensada junto a la música. La escritura es de canción pop con equipos de compositores; la ambición está en la producción y en el concepto de álbum, no en la ejecución instrumental. Miembros suyos ya están aparte en el catálogo (RM y Agust D). Entrada: Wings o Map of the Soul: 7.", origin: "heard", y: 2013, p: 2, c: 1 }
];

const NEW_RECS = [
  { name: "RM", genre: "Hip-Hop / Art Pop", desc: "El líder de BTS en solitario, moviéndose entre hip-hop, folk, R&B y city pop con invitados de cada terreno. Funciona más como curaduría de estilos que como escritura propia. Entrada: Indigo.", origin: "rec", pick: true, p: 3, y: 2015, via: "BTS", c: 1 },
  { name: "Agust D (Suga)", genre: "Hip-Hop / Rap", desc: "El lado rap del miembro de BTS en solitario, con bases atmosféricas y temas personales duros. La escritura de rap es correcta, pero sin ambición instrumental por debajo. Entrada: D-Day.", origin: "rec", pick: true, p: 3, y: 2016, via: "BTS" },
  { name: "Hadestown", genre: "Musical / Folk-Jazz", desc: "Folk americano cruzado con jazz de Nueva Orleans, con trombón, banjo, acordeón y contrabajo tocados por una banda visible en escena, y motivos melódicos que vuelven transformados para reflejar que el mito se repite en bucle. Anaïs Mitchell escribe melodías preciosas y la instrumentación es orgánica. Pero es un musical de canciones, no de contrapunto: al lado de Sondheim o Bernstein la escritura es mucho menos densa. ▸ Versión: el Original Broadway Cast Recording de 2019 (con André De Shields y Patrick Page); para el origen más folk e íntimo, el álbum concepto de Anaïs Mitchell de 2010.", origin: "rec", p: 2, y: 2019, c: 2 },
  { name: "Sweeney Todd", genre: "Musical (Sondheim)", desc: "Sondheim construye casi toda la partitura sobre el Dies Irae, el canto gregoriano de difuntos, transformándolo por toda la obra hasta dentro de las canciones cómicas; escribe contrapunto real, con personajes cantando líneas melódicas distintas a la vez que encajan (el dúo de A Little Priest, el cuarteto de Kiss Me), y usa disonancia sin resolver para sostener la tensión. Está más cerca de la ópera que del musical. ▸ Versión: el Original Broadway Cast de 1979 (completo, con Angela Lansbury y Len Cariou); la película de Tim Burton de 2007 recorta varias canciones, no la tomes como entrada.", origin: "rec", p: 1, y: 1979, c: 2 },
  { name: "Jesus Christ Superstar", genre: "Musical / Rock Opera", desc: "Rock opera de Andrew Lloyd Webber: guitarras electricas, dramatismo y voces gritadas. Teatralidad-Queen. ▸ Versión: el álbum concepto original de 1970 con Ian Gillan (Deep Purple) como Jesús, la mas rockera; el Live in Concert de 2018 para una toma moderna.", origin: "rec", pick: true, p: 2, y: 1970, via: "Musicales" },
  { name: "Tommy (The Who)", genre: "Musical / Rock Opera", desc: "Rock opera fundacional de The Who: album de rock hecho musical, narrativa surrealista con riffs. ▸ Versión: el álbum original de The Who de 1969 (el esencial); el soundtrack de la película de 1975 es divertido pero irregular.", origin: "rec", pick: true, p: 3, y: 1969, via: "Musicales" },
  { name: "Hedwig and the Angry Inch", genre: "Musical / Glam Rock", desc: "Glam rock musical (Bowie/Iggy/Velvet). La banda sonora funciona como un disco de rock real. ▸ Versión: el soundtrack de la película de 2001 (John Cameron Mitchell, la mejor en producción) o el Original Cast de 1998 mas crudo.", origin: "rec", pick: true, p: 2, y: 1998, via: "Musicales" },
  { name: "Repo! The Genetic Opera", genre: "Musical / Industrial Rock", desc: "Distopía gótica cantada casi de principio a fin, con partitura que mezcla rock industrial y recitativo de ópera. De culto, teatral y camp oscuro. ▸ Versión: el soundtrack de la película de 2008 (es cine antes que teatro; esa es la grabación a buscar).", origin: "rec", pick: true, p: 3, y: 2008, via: "Musicales" },
  { name: "Hamilton", genre: "Musical / Hip-Hop", desc: "El motor es el rap: la densidad de rima interna y el cambio de flow marcan quién es cada personaje, y los motivos musicales vuelven transformados a lo largo de las dos horas y media. La orquestación es de musical clásico por debajo del hip-hop. ▸ Versión: el Original Broadway Cast Recording de 2015 con Lin-Manuel Miranda (la definitiva); el film de Disney+ es ese mismo elenco filmado.", origin: "rec", pick: true, p: 2, y: 2015, via: "Musicales", c: 1 },
  { name: "American Idiot", genre: "Musical / Punk Rock", desc: "El álbum de Green Day adaptado a musical de punk rock, con la banda en escena y los temas encadenados sin pausa. ▸ Versión: el álbum original de Green Day de 2004 (el núcleo); el Original Broadway Cast de 2010 si quieres la expansión teatral con temas extra.", origin: "rec", pick: true, p: 3, y: 2004, via: "Musicales" },
  { name: "Spring Awakening", genre: "Musical / Alt Rock", desc: "Rock alternativo (Duncan Sheik) con libreto sobre adolescentes del siglo XIX. ▸ Versión: el Original Broadway Cast Recording de 2006 (Lea Michele y Jonathan Groff, la definitiva).", origin: "rec", pick: true, p: 3, y: 2006, via: "Musicales" },
  { name: "Beetlejuice the Musical", genre: "Musical / Comedy Rock", desc: "Ingenioso, oscuro-divertido y muy teatral. ▸ Versión: el Original Broadway Cast Recording de 2019 (Alex Brightman y Sophia Anne Caruso).", origin: "rec", pick: true, p: 3, y: 2018, via: "Musicales" },
  { name: "The Lightning Thief Musical", genre: "Musical / Rock", desc: "Musical de rock solido basado en Percy Jackson. ▸ Versión: el Original Cast Album (Chris McCarrell); elenco pequeño y sonido rock crudo a propósito.", origin: "rec", pick: true, p: 3, y: 2017, via: "Musicales" },
  { name: "Heathers the Musical", genre: "Musical / Pop Rock", desc: "Satirico y oscuro. ▸ Versión: el Original Off-Broadway Cast de 2014 (Barrett Wilbert Weed, la clásica); la versión del West End de Londres tiene canciones añadidas/distintas si quieres comparar.", origin: "rec", pick: true, p: 3, y: 2014, via: "Musicales" },
  { name: "Savatage", genre: "Heavy / Power Metal", desc: "A partir de Streets meten cambios de tempo dentro del tema, piano como instrumento principal en vez de adorno, orquestación y coro, y estructuras de varias partes que no vuelven al estribillo. Criss Oliva tocaba solos melódicos largos con desarrollo, no ráfagas; murió en un accidente en 1993 y el sonido de la banda cambió después. De aquí salió Trans-Siberian Orchestra. Entra por Streets o Dead Winter Dead.", origin: "rec", p: 1, y: 1983, c: 2 },
  { name: "Avantasia", genre: "Power Metal / Rock Opera", desc: "Rock operas melodicas/sinfonicas de Tobias Sammet con muchos vocalistas invitados. Idea coral-operistica tipo Queen. The Scarecrow.", origin: "rec", pick: true, p: 3, y: 2001, via: "Queen pesado" },
  { name: "Queensryche", genre: "Prog Metal", desc: "Operation: Mindcrime, gran rock opera del metal: prog conceptual con voz aguda y teatral (Geoff Tate).", p: 2, origin: "rec", pick: true, y: 1982, via: "Queen pesado" },
  { name: "Therion", genre: "Symphonic Metal", desc: "Symphonic metal con coros operisticos reales y orquesta completa. Opera con guitarras. Vovin, Theli.", origin: "rec", pick: true, p: 2, y: 1987, via: "Queen pesado" },
  { name: "Kamelot", genre: "Symphonic Power Metal", desc: "Symphonic power metal con discos conceptuales y voz dramatica (Roy Khan). Elegante y oscuro. The Black Halo.", origin: "rec", pick: true, p: 3, y: 1991, via: "Queen pesado" },
  { name: "Epica", genre: "Symphonic Metal", desc: "Symphonic metal con Simone Simons (operistica limpia) mas guturales y orquesta/coro enormes. Epico y barroco.", origin: "rec", pick: true, female: true, p: 3, y: 2002, via: "Queen pesado" },
  { name: "Battle Beast", genre: "Power Metal", desc: "Power metal teatral con Noora Louhimo, vibra glam-ochentera. Descaro escenico melodico tipo Queen/Meat Loaf.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "Queen pesado" },
  { name: "Diablo Swing Orchestra", genre: "Avant-garde Metal", desc: "Swing, vals, clásico y voz operística mezclados, con arreglos de cuerda y metales bien trabajados, pero por debajo las canciones tienen forma convencional con estribillo: la sorpresa es de timbre, no de estructura. Mr. Bungle, Unexpect y Estradasphere, que ya tienes, hacen el mismo collage con más riesgo. Entrada: The Butcher's Ballroom.", origin: "rec", p: 2, y: 2003, c: 2 },
  { name: "Sigh", genre: "Avant-garde Metal", desc: "Black metal avant-garde japones con saxo, sintetizadores, clasica y jazz. Imprevisible, todo cabe en una cancion. Imaginary Sonicscape.", p: 2, origin: "rec", pick: true, y: 1989, via: "Queen pesado", c: 3 },
  { name: "Unexpect", genre: "Avant-garde Metal", desc: "Metal avant-garde caotico y teatral con violin, voz femenina operistica y contrabajo. Grandilocuencia circense. In a Flesh Aquarium.", p: 2, origin: "rec", pick: true, female: true, y: 1996, via: "Queen pesado", c: 3 },
  { name: "The Ocean", genre: "Post-Metal / Atmosférico", desc: "En Pelagial la estructura ES el descenso: una pieza continua que empieza clara y ligera y se va volviendo más lenta, grave y disonante conforme baja de capa, con la tonalidad oscureciéndose de verdad. Y en Phanerozoic alternan riffs de compás cambiante con pasajes de piano y cuerda escritos, no de relleno. Robin Staps compone para la obra entera y no por canciones, y lleva haciéndolo disco tras disco. Entra por Pelagial.", origin: "rec", p: 1, y: 2000, c: 2 },
  { name: "Enslaved", genre: "Prog Black Metal", desc: "Treinta años yendo de black y viking a prog sin que ningún disco repita al anterior: voces limpias en armonía contra guturales, teclados haciendo contrapunto y estructuras largas. Below the Lights, RIITIIR y Utgard son tres etapas distintas y las tres funcionan. Entrada: RIITIIR.", origin: "rec", pick: true, p: 1, y: 1991, via: "Gojira/Behemoth", c: 1 },
  { name: "Cult of Luna", genre: "Post-Metal", desc: "Post-metal monolitico y atmosferico: construcciones lentas que estallan, capas densas. Vertikal.", origin: "rec", pick: true, p: 2, y: 1998, via: "Gojira/Behemoth" },
  { name: "Persefone", genre: "Progressive Death Metal", desc: "Death progresivo de Andorra, tecnico y melodico, con teclados y temas espirituales. Spiritual Migration, Aathma.", p: 2, origin: "rec", pick: true, y: 2001, via: "Gojira/Behemoth" },
  { name: "Fallujah", genre: "Atmospheric Death Metal", desc: "Death atmosferico/progresivo con texturas etereas casi shoegaze sobre la brutalidad. The Flesh Prevails.", p: 2, origin: "rec", pick: true, y: 2007, via: "Gojira/Behemoth" },
  { name: "Septicflesh", genre: "Symphonic Death Metal", desc: "Death sinfonico griego con orquesta y coro reales. Masivo, cinematografico y oscuro. Communion, Codex Omega.", p: 2, origin: "rec", pick: true, y: 1990, via: "Gojira/Behemoth" },
  { name: "Fleshgod Apocalypse", genre: "Symphonic Death Metal", desc: "Death tecnico italiano con orquestacion clasica y soprano operistica. 'Death metal barroco'. Labyrinth, King.", p: 3, origin: "rec", pick: true, y: 2007, via: "Gojira/Behemoth" },
  { name: "Zeal & Ardor", genre: "Avant-garde Metal", desc: "Black metal mezclado con spirituals afroamericanos y blues. Idea unica, cada disco explora algo distinto. Stranger Fruit.", p: 2, origin: "rec", pick: true, y: 2013, via: "Gojira/Behemoth", c: 3 },
  { name: "Rotting Christ", genre: "Atmospheric Black Metal", desc: "Veteranos griegos: del black crudo a un sonido ritual y atmosferico con cantos tribales. Theogonia, Rituals.", origin: "rec", pick: true, p: 3, y: 1987, via: "Gojira/Behemoth" },
  { name: "Ihsahn", genre: "Progressive Extreme Metal", desc: "El ex-Emperor en solitario: extremo progresivo y experimental con saxo, prog setentero y electronica. After, Amr.", p: 2, origin: "rec", pick: true, y: 2005, via: "Gojira/Behemoth", c: 1 },
  { name: "Wilderun", genre: "Symphonic Folk Metal", desc: "Death sinfonico/folk progresivo con arreglos orquestales enormes y pasajes acusticos. Veil of Imagination.", origin: "rec", pick: true, p: 2, y: 2012, via: "Gojira/Behemoth" },
  { name: "Venom Prison", genre: "Death Metal / Hardcore", desc: "Larissa Stupar al frente: death con hardcore, brutal y tecnico, letras viscerales. Samsara.", p: 3, origin: "rec", pick: true, female: true, y: 2015, via: "Gojira/Behemoth" },
  { name: "Svalbard", genre: "Blackgaze / Post-Hardcore", desc: "Post-metal/blackgaze con hardcore: atmosferico, emotivo y pesado, voz femenina. When I Die Will I Get Better?", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Gojira/Behemoth" },
  { name: "Infected Rain", genre: "Nu Metal / Alt", desc: "Lena Scissorhands alternando limpio y gutural sobre groove/nu metal moldavo. Conecta con Jinjer.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "Gojira/Behemoth" },
  { name: "Hail the Sun", genre: "Post-Hardcore / Swancore", desc: "Post-hardcore tecnico con vocalista-baterista, ritmos en swing, melodias desquiciadas pero hermosas. Wake.", p: 3, origin: "rec", pick: true, y: 2009, via: "PTH" },
  { name: "A Lot Like Birds", genre: "Post-Hardcore", desc: "Post-hardcore teatral y tecnico, de lo intimo a lo explosivo, narrativa conceptual. No Place.", p: 3, origin: "rec", pick: true, y: 2009, via: "PTH" },
  { name: "Sianvar", genre: "Post-Hardcore / Swancore", desc: "Supergrupo de swancore: tecnico, melodico y frenetico.", p: 3, origin: "rec", pick: true, y: 2013, via: "PTH" },
  { name: "Stolas", genre: "Progressive Post-Hardcore", desc: "Swancore progresivo, tecnico y melodico.", p: 3, origin: "rec", pick: true, y: 2012, via: "PTH" },
  { name: "Eidola", genre: "Progressive Post-Hardcore", desc: "Swancore progresivo y conceptual.", p: 3, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Native Construct", genre: "Progressive Metalcore", desc: "Salió de tres estudiantes de Berklee que escribieron Quiet World (2015) durante la carrera, y se nota en la escritura: armonía de jazz con improvisación real, técnicas de composición clásica y dramaturgia de teatro musical metidas dentro de una estructura de prog metal, con guitarras de rango extendido, voces operísticas y orquestación completa. Las reseñas coinciden en que no te deja respirar entre giro y giro. Aviso honesto: es su único disco y llevan inactivos desde entonces, cada uno con su vida tras la universidad. Entra por Come Hell or High Water.", origin: "rec", p: 1, y: 2011, c: 2 },
  { name: "Last Chance to Reason", genre: "Technical Metalcore", desc: "Metalcore tecnico/progresivo con album conceptual estructurado como videojuego (Level 2).", p: 2, origin: "rec", pick: true, y: 2004, via: "PTH" },
  { name: "Polyphia", genre: "Prog / Instrumental", desc: "Guitarra tecnica melodica al extremo con trap, fusion y pop. Tim Henson. New Levels New Devils.", p: 2, origin: "rec", pick: true, y: 2010, via: "PTH" },
  { name: "Plini", genre: "Prog / Instrumental", desc: "Prog instrumental australiano melodico, atmosferico y luminoso. Handmade Cities.", p: 3, origin: "rec", pick: true, y: 2013, via: "PTH" },
  { name: "Intervals", genre: "Prog / Instrumental", desc: "Prog metal melodico mayormente instrumental, guitarra cantarina y limpia.", p: 3, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Chon", genre: "Jazz Fusion", desc: "Math rock/fusion jazz instrumental, calido y melodico con groove.", origin: "rec", pick: true, p: 2, y: 2008, via: "PTH" },
  { name: "Covet", genre: "Melodic Math Rock", desc: "Math rock liderado por Yvette Young, tapping y afinaciones raras. Brillante y tecnico.", p: 3, origin: "rec", pick: true, female: true, y: 2014, via: "PTH" },
  { name: "Kayo Dot", genre: "Avant-garde / Experimental", desc: "Proyecto de Toby Driver: cada disco otro universo (metal, camara, ambient, art rock). Instrumentales fascinantes. Choirs of the Eye.", p: 2, origin: "rec", pick: true, y: 2003, via: "Dream Theater", c: 1 },
  { name: "maudlin of the Well", genre: "Avant-garde Metal", desc: "Proyecto previo de Toby Driver: metal progresivo avant con saxo y arreglos extranos. Bath/Leaving Your Body Map.", p: 2, origin: "rec", pick: true, y: 1996, via: "Dream Theater", c: 1 },
  { name: "Riverside", genre: "Prog Rock / Metal", desc: "Prog rock/metal polaco atmosferico y melancolico, identidad emotiva refinada. Second Life Syndrome, Wasteland.", p: 2, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Obscura", genre: "Technical Death Metal", desc: "Death técnico donde el bajo fretless lleva contramelodía propia en vez de doblar la guitarra, con armonía neoclásica escrita y cambios de compás constantes. Lo mantienen a lo largo de Cosmogenesis, Omnivium y Diluvium. Entrada: Cosmogenesis.", origin: "rec", pick: true, p: 1, y: 2002, via: "Dream Theater" },
  { name: "Beyond Creation", genre: "Technical Death Metal", desc: "El bajo fretless de Dominic Lapointe hace líneas melódicas propias que compiten con la guitarra en vez de acompañarla, sobre death técnico con cambios de compás continuos. Los tres discos reparten las voces igual. Entrada: The Aura.", origin: "rec", pick: true, p: 1, y: 2005, via: "Dream Theater" },
  { name: "Pagan's Mind", genre: "Prog Power Metal", desc: "Prog/power noruego con concepto sci-fi y virtuosismo, voz limpia potente. Celestial Entrance.", p: 3, origin: "rec", pick: true, y: 1996, via: "Dream Theater" },
  { name: "Communic", genre: "Prog Metal", desc: "Prog metal noruego oscuro y pesado, riff-driven, composiciones largas. Conspiracy in Mind.", p: 3, origin: "rec", pick: true, y: 2003, via: "Dream Theater" },
  { name: "Voyager", genre: "Prog Metal", desc: "Prog metal australiano moderno con toque synth-pop ochentero. Accesible pero con sustancia.", p: 3, origin: "rec", pick: true, y: 1999, via: "Dream Theater" },
  { name: "Cynic", genre: "Prog Metal / Jazz Fusion", desc: "Death metal con acordes de novena y trece, bajo fretless llevando contramelodía y voz con vocoder tratada como un instrumento más. Focus (1993) y Traced in Air (2008) están separados por quince años y los dos sostienen esa escritura. Entrada: Focus.", origin: "rec", pick: true, p: 1, y: 1987, via: "Dream Theater", c: 3 },
  { name: "Thank You Scientist", genre: "Prog Rock / Fusion", desc: "No es prog con adornos, es un ensemble de verdad: violín eléctrico, trompeta y saxo como voces compositivas junto a la guitarra de Tom Monda, con escritura de fusión densa y cambios constantes. Terraformer es el disco más ambicioso. Cambio de formación: Salvatore Marrano se fue en 2023 y desde finales de 2024 canta Daimon Alexandrius, multiinstrumentista que además aporta flauta y sitar. Entra por Stranger Heads Prevail o Terraformer.", origin: "rec", p: 1, y: 2009, c: 2 },
  { name: "Allegaeon", genre: "Technical Melodic Death", desc: "Death tecnico/melodico con solos neoclasicos vertiginosos y tematica cientifica. Proponent for Sentience, Apoptosis.", origin: "rec", pick: true, p: 2, y: 2008, via: "Trivium" },
  { name: "Vektor", genre: "Technical Thrash Metal", desc: "Thrash técnico con riffs encadenados en estructuras largas y una voz aguda y rasposa que divide a la gente. Los tres discos van a más: Black Future ya era denso, Outer Isles lo apretó, y Terminal Redux es un conceptual de más de setenta minutos con coros limpios y pasajes casi de rock progresivo sin soltar la velocidad. Entra por Terminal Redux.", origin: "rec", p: 1, y: 2003, c: 2 },
  { name: "Darkest Hour", genre: "Melodic Death / Metalcore", desc: "Metalcore/melodeath con devocion por At the Gates: guitarras gemelas melodicas sobre agresion. The Mark of the Judas.", origin: "rec", pick: true, p: 3, y: 1995, via: "Trivium" },
  { name: "Unearth", genre: "Metalcore", desc: "Metalcore riff-driven con solos melodicos y pegada thrash.", p: 3, origin: "rec", pick: true, y: 1998, via: "Trivium" },
  { name: "Nervosa", genre: "Thrash / Death Metal", desc: "Thrash/death brasileno agresivo y veloz liderado por mujeres.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "Trivium" },
  { name: "Lutharo", genre: "Melodic Death / Thrash", desc: "Death/thrash melodico canadiense con Krista Shipperbottom, limpio + gutural sobre instrumentales veloces.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Trivium" },
  { name: "Beck", genre: "Alt Rock / Eclectic", desc: "El camaleon del rock alternativo: folk, funk, hip-hop, blues, cada disco distinto. Odelay, Morning Phase.", p: 2, origin: "rec", pick: true, y: 1988, via: "Cage the Elephant", c: 1 },
  { name: "The Flaming Lips", genre: "Psych Rock", desc: "Psych rock experimental de lo luminoso a lo abstracto. Cada disco un experimento. Yoshimi Battles the Pink Robots.", p: 2, origin: "rec", pick: true, y: 1983, via: "Cage the Elephant", c: 1 },
  { name: "Yeah Yeah Yeahs", genre: "Indie / Garage Rock", desc: "Karen O, frontwoman magnetica. De garage-punk a dance-rock a experimental. Fever to Tell.", p: 3, origin: "rec", pick: true, female: true, y: 2000, via: "Cage the Elephant", c: 1 },
  { name: "Osees", genre: "Garage Psych Rock", desc: "Banda hiperprolifica de John Dwyer: riffs freneticos, jams motorik, energia salvaje. Floating Coffin.", p: 2, origin: "rec", pick: true, y: 1997, via: "Cage the Elephant" },
  { name: "White Denim", genre: "Garage / Jam Rock", desc: "Garage rock con fusion jazz, prog y jams tecnicas. Destreza casi progresiva con alma garage. D.", p: 2, origin: "rec", pick: true, y: 2006, via: "Cage the Elephant" },
  { name: "Ty Segall", genre: "Garage Rock / Psych", desc: "Garage prolifico: fuzz, psicodelia, lo-fi y melodia. Melted, Manipulator.", origin: "rec", pick: true, p: 3, y: 2008, via: "Cage the Elephant" },
  { name: "The Kills", genre: "Garage Blues Rock", desc: "Duo de garage-blues crudo y minimalista con Alison Mosshart. Midnight Boom.", origin: "rec", pick: true, female: true, p: 3, y: 2001, via: "Cage the Elephant" },
  { name: "Spoon", genre: "Indie Rock", desc: "Indie rock refinado con groove e identidad pulida. Arreglos ingeniosos. They Want My Soul.", origin: "rec", pick: true, p: 3, y: 1993, via: "Cage the Elephant" },
  { name: "Alabama Shakes", genre: "Blues Rock / Soul", desc: "Brittany Howard canta con un rango y una aspereza enormes, y en Sound & Color la banda abandona el revival de blues rock por arreglos de vibráfono, cuerda y ritmos partidos. Entrada: Sound & Color.", origin: "rec", pick: true, female: true, p: 2, y: 2009, via: "Cage the Elephant" },
  { name: "Brittany Howard", genre: "Soul / Experimental", desc: "Proyecto solista aun mas aventurero y experimental. Jaime.", p: 3, origin: "rec", pick: true, female: true, y: 2019, via: "Cage the Elephant" },
  { name: "Loathe", genre: "Metalcore / Shoegaze", desc: "Guitarras muy graves y capas de shoegaze sobre pasajes ambientales con sintetizador, alternando voz limpia y gritada, con un manejo del tono y de la textura que es de lo mejor del género. Pero eso es lo que dominan, el paisaje sonoro; la escritura por debajo no busca complejidad rítmica ni estructural, sino contraste y ambiente. Se queda en alta afinidad, que ya es mucho. Sacaron A Stranger to You en 2026, metiendo electrónica ambiental. Entra por I Let It In and It Took Everything.", origin: "rec", p: 2, y: 2014, c: 1 },
  { name: "Veil of Maya", genre: "Djent / Prog Metalcore", desc: "De deathcore tecnico a djent progresivo a melodia limpia. Cada disco otra cosa. Matriarch, False Idol.", p: 2, origin: "rec", pick: true, y: 2004, via: "Metalcore", c: 1 },
  { name: "Misery Signals", genre: "Progressive Metalcore", desc: "Metalcore progresivo y atmosferico, muy musical, armonias melodicas. Of Malice and the Magnum Heart, Controller.", p: 2, origin: "rec", pick: true, y: 2002, via: "Metalcore" },
  { name: "Defeater", genre: "Melodic Hardcore", desc: "Hardcore melodico con un concepto narrativo que atraviesa toda su discografia, pero el concepto esta en las letras: musicalmente es hardcore melodico directo, sin complejidad instrumental. Travels.", origin: "rec", pick: true, p: 3, y: 2008, via: "Metalcore" },
  { name: "Counterparts", genre: "Melodic Hardcore / Metalcore", desc: "Metalcore/hardcore melodico y emotivo, con dinamica e intensidad real. The Difference Between Hell and Home.", p: 3, origin: "rec", pick: true, y: 2007, via: "Metalcore" },
  { name: "Employed to Serve", genre: "Metalcore", desc: "Justine Jones al frente: metalcore/extreme britanico pesado, fresco y groovy. Eternal Forward Motion.", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Metalcore" },
  { name: "Conquer Divide", genre: "Metalcore", desc: "Metalcore moderno con dos vocalistas femeninas, melodico y con pegada, pero instrumentalmente sigue la plantilla del genero sin aportar nada raro.", origin: "rec", pick: true, female: true, p: 3, y: 2013, via: "Metalcore" },
  { name: "Zao", genre: "Metallic Hardcore", desc: "Hardcore metalico atmosferico y espiritual.", p: 2, origin: "rec", pick: true, y: 1993, via: "Metalcore" },
  { name: "In Mourning", genre: "Progressive Melodic Death", desc: "Melodeath progresivo sueco con temas de ocho y nueve minutos que se desarrollan en vez de repetir estribillo, y tres guitarras repartiéndose líneas distintas en vez de doblarse. Shrouded Divine, The Weight of Oceans y Afterglow están al mismo nivel. Entrada: The Weight of Oceans.", origin: "rec", pick: true, p: 1, y: 2000, via: "Be'lakor" },
  { name: "Ghost Brigade", genre: "Atmospheric Melodic Death", desc: "Melodeath atmosferico finlandes con sludge y doom, muy emotivo. Until Fear No Longer Defines Us.", origin: "rec", pick: true, p: 2, y: 2005, via: "Be'lakor" },
  { name: "Swallow the Sun", genre: "Death / Doom Metal", desc: "Death/doom atmosferico finlandes, melancolico y hermoso, grandeza triste cinematografica. New Moon.", p: 3, origin: "rec", pick: true, y: 2000, via: "Be'lakor" },
  { name: "Barren Earth", genre: "Progressive Death Metal", desc: "Prog death finlandes con prog setentero, organo y acustico. Aventurero y melodico. Curse of the Red River.", p: 2, origin: "rec", pick: true, y: 2007, via: "Be'lakor" },
  { name: "Amorphis", genre: "Melodic Death / Prog", desc: "Se movieron de death brutal a prog psicodélico con teclados setenteros y voz limpia, y de ahí a un melodeath melódico con modos folclóricos finlandeses metidos en la melodía, no como adorno: las líneas de guitarra siguen escalas del Kalevala y por eso suenan raras dentro del metal. Tomi Joutsen alterna gutural y limpio dentro del mismo tema como recurso estructural. Entra por Tales from the Thousand Lakes, luego Elegy.", origin: "rec", p: 1, y: 1990, c: 1 },
  { name: "Disillusion", genre: "Progressive Death Metal", desc: "Back to Times of Splendor es death progresivo epico, canciones-viaje exquisitas. Han variado mucho su sonido.", p: 2, origin: "rec", pick: true, y: 1994, via: "Be'lakor" },
  { name: "Wintersun", genre: "Symphonic Melodic Death", desc: "Melodeath sinfonico epico con capas monumentales de orquestacion. Grandilocuente. Wintersun, Time I.", origin: "rec", pick: true, p: 2, y: 2004, via: "Be'lakor" },
  { name: "Edge of Sanity", genre: "Progressive Death Metal", desc: "Proyecto de Dan Swano: Crimson es una sola pieza de 40 min de death progresivo. Singular y clasico.", p: 2, origin: "rec", pick: true, y: 1989, via: "Be'lakor", c: 3 },
  { name: "Sojourner", genre: "Atmospheric Folk Metal", desc: "Metal atmosferico/folk con voces femenina y masculina, cinematografico y de viaje epico.", origin: "rec", pick: true, female: true, p: 3, y: 2015, via: "Be'lakor" },
  { name: "Of Montreal", genre: "Baroque Psych Pop", desc: "Pop psicodelico barroco extravagante y flamboyante; cada disco un experimento. Hissing Fauna.", origin: "rec", pick: true, p: 2, y: 1996, via: "Panic!", c: 1 },
  { name: "Janelle Monae", genre: "Art Pop / Funk", desc: "Eclecticismo teatral con albumes conceptuales: R&B, funk, pop, rock. The ArchAndroid.", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Panic!", c: 1 },
  { name: "Rufus Wainwright", genre: "Baroque Chamber Pop", desc: "Chamber pop barroco y orquestal, teatral y operistico, arreglos lujosos. Want One.", origin: "rec", pick: true, p: 2, y: 1998, via: "Panic!" },
  { name: "The Decemberists", genre: "Baroque Indie Folk", desc: "Indie folk barroco y literario, narrativo, con rock opera (The Hazards of Love). The Crane Wife.", origin: "rec", pick: true, p: 2, y: 2000, via: "Panic!" },
  { name: "The Divine Comedy", genre: "Baroque Chamber Pop", desc: "Chamber pop barroco e ingenioso de Neil Hannon, orquestal con humor y clase. Casanova.", origin: "rec", pick: true, p: 3, y: 1989, via: "Panic!" },
  { name: "Mika", genre: "Baroque Pop", desc: "Pop teatral barroco influenciado por Queen: falsete y arreglos exuberantes. Life in Cartoon Motion.", origin: "rec", pick: true, p: 3, y: 2007, via: "Panic!" },
  { name: "Foxy Shazam", genre: "Glam Rock / Theatrical", desc: "Glam rock teatral desquiciado, frontman entre Freddie y Meat Loaf, con vientos y piano. The Church of Rock and Roll.", origin: "rec", pick: true, p: 3, y: 2004, via: "Panic!" },
  { name: "Marina", genre: "Art Pop", desc: "Art pop teatral con albumes conceptuales (Electra Heart). Dramatica y melodica.", origin: "rec", pick: true, female: true, p: 3, y: 2009, via: "Panic!" },
  { name: "Regina Spektor", genre: "Baroque / Anti-Folk", desc: "Anti-folk barroco de piano, excentrico y teatral, estructuras imprevisibles.", origin: "rec", pick: true, female: true, p: 3, y: 2001, via: "Panic!" },
  { name: "The Struts", genre: "Glam Rock", desc: "Revival de glam rock con devocion a Queen: himnos, falsetes, teatralidad anthemic.", origin: "rec", pick: true, p: 3, y: 2012, via: "Panic!" },
  { name: "The Darkness", genre: "Glam Rock", desc: "Glam rock revival Queen-worship con falsete, tongue-in-cheek.", origin: "rec", pick: true, p: 3, y: 2000, via: "Panic!" },
  { name: "Electric Light Orchestra", genre: "Baroque Orchestral Pop", desc: "Pop orquestal barroco beatlesco. Raiz de Pretty. Odd.", origin: "rec", pick: true, p: 2, y: 1970, via: "Panic!" },
  { name: "The Zombies", genre: "Baroque Psych Pop", desc: "Pop barroco psicodelico sesentero (Odessey and Oracle). Raiz de Pretty. Odd.", origin: "rec", pick: true, p: 2, y: 1961, via: "Panic!" },
  { name: "The Mars Volta", genre: "Prog / Psych Rock", desc: "Piezas de diez y quince minutos que cambian de sección sin transición, con Omar Rodríguez-López escribiendo la parte de todos y una sección rítmica tocando salsa y jazz por debajo del rock. De De-Loused a Frances the Mute a Noctourniquet cada disco cambia de sistema. Entrada: De-Loused in the Comatorium.", origin: "rec", pick: true, p: 1, y: 2001, via: "Muse", c: 1 },
  { name: "Biffy Clyro", genre: "Alt Rock", desc: "Alt rock escoces que cambia mucho entre discos, instrumentales ingeniosas y dinamica explosiva. Puzzle.", p: 2, origin: "rec", pick: true, y: 1995, via: "Muse", c: 1 },
  { name: "Karnivool", genre: "Prog Rock / Metal", desc: "Australianos. Grooves sostenidos en métricas desplazadas (la intro de Goliath va en 27/4) con capas de guitarra que entran y salen, y estructuras que no vuelven al estribillo. Sound Awake y Asymmetry mantienen esa exigencia. Entrada: Sound Awake.", origin: "rec", pick: true, p: 1, y: 1997, via: "Muse" , c: 2 },
  { name: "dredg", genre: "Alt / Prog Rock", desc: "Alt/prog rock atmosferico y conceptual, arreglos cuidadisimos. El Cielo.", origin: "rec", pick: true, p: 3, y: 1993, via: "Muse" },
  { name: "Mew", genre: "Prog / Dream Pop", desc: "Prog/dream pop danes con falsete etereo, melodias complejas y produccion lujosa. And the Glass Handed Kites.", p: 3, origin: "rec", pick: true, y: 1995, via: "Muse" },
  { name: "Oceansize", genre: "Prog / Post-Rock", desc: "Prog/post-rock britanico dinamico y denso, construcciones largas y poderosas. Effloresce, Frames.", p: 2, origin: "rec", pick: true, y: 1998, via: "Muse" },
  { name: "Anathema", genre: "Atmospheric Prog Rock", desc: "De doom metal a prog atmosferico emotivo y sinfonico, crescendos enormes, voces masc/fem. Precioso, pero compositivamente simple en su etapa moderna: vive del clima emocional mas que del interes instrumental. Weather Systems.", origin: "rec", pick: true, female: true, p: 2, y: 1990, via: "Muse" },
  { name: "Pure Reason Revolution", genre: "Prog Rock / Electronic", desc: "Prog rock con electronica y armonias masc/fem. Cruza prog con electronica con gusto. The Dark Third.", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Muse" },
  { name: "Evanescence", genre: "Symphonic / Gothic Rock", desc: "Rock sinfonico/gotico dramatico con piano y la voz de Amy Lee. Drama orquestal anthemic. Fallen.", origin: "rec", pick: true, female: true, p: 3, y: 1995, via: "Muse" },
  { name: "Creeper", genre: "Horror Punk / Theatrical", desc: "Horror-punk teatral con discos conceptuales narrados: personajes recurrentes, interludios hablados y saltos de estilo entre punk, glam y balada de piano dentro del mismo álbum. Sanguivore (2023) se fue directamente al rock de vampiros con estructuras largas. Entrada: Eternity in Your Arms.", origin: "rec", pick: true, p: 3, y: 2014, via: "Ice Nine Kills", c: 1 },
  { name: "Crown the Empire", genre: "Theatrical Metalcore", desc: "Metalcore teatral y cinematografico con albumes conceptuales, pero debajo del dramatismo orquestal la escritura es bastante estandar: la teatralidad es envoltorio, no sustancia instrumental. Rise of the Runaways.", origin: "rec", pick: true, p: 3, y: 2010, via: "Ice Nine Kills" },
  { name: "New Years Day", genre: "Gothic Metalcore", desc: "Metalcore gotico-teatral con Ash Costello y estetica de terror. Unbreakable, Malevolence.", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Ice Nine Kills" },
  { name: "Type O Negative", genre: "Gothic / Doom Metal", desc: "Gotico teatral con humor negro, riffs pesados y drama unico (Peter Steele). Bloody Kisses, October Rust.", origin: "rec", pick: true, p: 3, y: 1989, via: "Ice Nine Kills" },
  { name: "In This Moment", genre: "Theatrical Groove Metal", desc: "Metal sinfonico/groove ultra-teatral con Maria Brink, shows de ritual de terror. Blood, Black Widow.", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Ice Nine Kills" },
  { name: "Wednesday 13", genre: "Horror Punk / Metal", desc: "Horror punk/metal con tematica de cine B de terror, teatral y divertido (tambien Murderdolls).", origin: "rec", pick: true, p: 3, y: 2004, via: "Ice Nine Kills" },
  { name: "Mors Principium Est", genre: "Technical Melodic Death", desc: "Melodeath finlandes tecnico y melodico con solos brillantes. Embers of a Dying World.", origin: "rec", pick: true, p: 3, y: 1999, via: "In Flames" },
  { name: "Disarmonia Mundi", genre: "Melodic Death / Electronic", desc: "Melodeath sueco-italiano (con Bjorn Strid en limpio) que integra electronica con gusto, sin EDM puro. Mind Tricks.", origin: "rec", pick: true, p: 3, y: 2000, via: "In Flames" },
  { name: "Cellar Darling", genre: "Folk Rock", desc: "Folk-prog melodico de Anna Murphy (ex-Eluveitie), aventurero instrumentalmente. This Is the Sound.", origin: "rec", pick: true, female: true, p: 2, y: 2016, via: "In Flames" }
];

// ===========================================================================
