const TANDA_3 = [
  // ----- MUSICALES (2ª vuelta + internacionales) -----
  { name: "Natasha, Pierre & the Great Comet of 1812", genre: "Musical / Electropop Opera", desc: "Ópera electropop sobre un fragmento de Guerra y Paz, con folk, clásica rusa, rock, electrónica e indie conviviendo en la misma obra y orquestaciones densas. La electrónica es teatral, no de pista de baile, y la banda toca repartida entre el público. ▸ Versión: el elenco original Off-Broadway de 2013 (con Phillipa Soo, la más completa); el de Broadway de 2016 trae a Josh Groban como Pierre.", origin: "rec", pick: true, p: 1, y: 2012, via: "Musicales", c: 1 },
  { name: "Ride the Cyclone", genre: "Musical / Pastiche", desc: "Musical de culto oscuro donde cada canción es el pastiche de un género distinto (cabaret, synth-pop, balada ucraniana, hip-hop). El eclecticismo es la gracia. [Cat 1] ▸ Versión: la grabación del elenco original de 2016; buena parte de su culto creció desde ahí.", origin: "rec", pick: true, p: 3, y: 2015, via: "Musicales", c: 1 },
  { name: "Caroline, or Change", genre: "Musical (Jeanine Tesori)", desc: "Through-sung que mezcla Motown, blues, klezmer, spirituals y clásica en los 60. Compositivamente riquísimo, protagonista femenina. [Cat 1] ▸ Versión: el Original Broadway Cast de 2004 (Tonya Pinkins); el revival de 2021 con Sharon D. Clarke es igual de aclamado.", origin: "rec", pick: true, female: true, p: 2, y: 2003, via: "Musicales", c: 1 },
  { name: "Into the Woods", genre: "Musical (Sondheim)", desc: "Los personajes tienen motivos propios que se transforman y se cruzan, así que en los números de conjunto suenan varias líneas melódicas distintas a la vez y cada una identifica a quien la canta. El segundo acto desmonta el cuento que el primero construyó, y la música hace lo mismo con sus temas. Sondheim. ▸ Versión: el Original Broadway Cast de 1987 (Bernadette Peters, completo); la película de Disney de 2014 recorta canciones.", origin: "rec", pick: true, p: 2, y: 1987, via: "Musicales" },
  { name: "Sunday in the Park with George", genre: "Musical (Sondheim)", desc: "La escritura imita la técnica del cuadro: notas cortas y repetidas que por separado no son melodía y que forman la textura al superponerse, igual que los puntos de Seurat forman la imagen. Y el segundo acto cambia de época y de lenguaje musical entero. Sondheim. ▸ Versión: el Original Broadway Cast de 1984 (Mandy Patinkin y Bernadette Peters, la definitiva).", origin: "rec", pick: true, p: 1, y: 1984, via: "Musicales" },
  { name: "Assassins", genre: "Musical (Sondheim)", desc: "Sondheim oscuro: pastiche de estilos musicales americanos a lo largo de la historia. ▸ Versión: el elenco del revival de Broadway de 2004 (mas completo, añade 'Something Just Broke'); o el Off-Broadway original de 1990.", origin: "rec", pick: true, p: 2, y: 1990, via: "Musicales" },
  { name: "Adam Guettel", genre: "Musical / Compositor", desc: "De los compositores más sofisticados (nieto de R. Rodgers): armonías lujosas. 'The Light in the Piazza' (orquestal casi clásico), 'Floyd Collins' (folk/bluegrass disonante). ▸ Versión: es un compositor, no un musical: empieza por 'The Light in the Piazza' (Original Broadway Cast de 2005), luego 'Floyd Collins' (elenco original).", origin: "rec", pick: true, p: 2, y: 1996, via: "Musicales" },
  { name: "Jason Robert Brown", genre: "Musical / Compositor", desc: "Escritura intrincada con jazz y pop. 'The Last Five Years' (narrativa no lineal, piano virtuoso), 'Parade'. ▸ Versión: compositor: empieza por 'The Last Five Years' (elenco Off-Broadway original de 2002); para 'Parade', el revival de 2023 con Ben Platt o el original de 1998.", origin: "rec", pick: true, p: 2, y: 1995, via: "Musicales" },
  { name: "Next to Normal", genre: "Musical / Rock", desc: "Rock-musical dramático sobre salud mental: partitura de rock sólida y devastadora, nada de fórmula. ▸ Versión: el Original Broadway Cast Recording de 2009 (Alice Ripley, la definitiva).", origin: "rec", pick: true, p: 3, y: 2008, via: "Musicales" },
  { name: "The Band's Visit", genre: "Musical / Jazz-Árabe", desc: "Atmosférico y sutil: jazz cruzado con música árabe (banda egipcia varada en Israel). Instrumentación única y delicada. ▸ Versión: el Original Broadway Cast Recording de 2018 (Katrina Lenk y Tony Shalhoub).", origin: "rec", pick: true, p: 2, y: 2016, via: "Musicales" },
  { name: "The Rocky Horror Show", genre: "Musical / Glam Rock", desc: "Glam rock teatral camp con devoción al rock and roll de los cincuenta y a la ciencia ficción de serie B, con banda de rock en vivo y números que parodian estilos concretos. ▸ Versión: el soundtrack de la película de 1975 con Tim Curry, la icónica.", origin: "rec", pick: true, p: 3, y: 1973, via: "Musicales" },
  { name: "Little Shop of Horrors", genre: "Musical (Alan Menken)", desc: "Comedia de terror con planta carnívora, escrita por Alan Menken en clave doo-wop, Motown y rock sesentero, con un trío de coristas que hace de coro griego comentando la acción. ▸ Versión: el Original Off-Broadway Cast de 1982 (Ellen Greene); el soundtrack de la película de 1986 (también Ellen Greene) es otra gran opción.", origin: "rec", pick: true, female: true, p: 3, y: 1982, via: "Musicales" },
  { name: "Bat Out of Hell: The Musical", genre: "Musical / Rock Opera", desc: "Recoge las canciones de Jim Steinman (el de Meat Loaf): bombast rock operística. Teatralidad-Queen al máximo. ▸ Versión: el Original Cast de 2018; pero ojo, la fuente son los álbumes 'Bat Out of Hell' de Meat Loaf (ya en la página), superiores al musical.", origin: "rec", pick: true, p: 3, y: 2017, via: "Musicales" },
  { name: "Starmania", genre: "Musical / Ópera Rock (FR)", desc: "Ópera rock francesa clásica y sofisticada, ambiciosa y melódica. ▸ Versión: el álbum concepto original de 1978 (Daniel Balavoine, France Gall, la clásica); el revival de 2022 para una producción moderna.", origin: "rec", pick: true, p: 3, y: 1979, via: "Musicales" },
  { name: "Mozart, l'opéra rock", genre: "Musical / Rock (FR)", desc: "Musical de rock sobre Mozart que cruza lo clásico con el rock y la teatralidad. [Cat 1] ▸ Versión: la grabación del elenco original de 2009 (con L'Assasymphonie de Florent Mothe como gran momento).", origin: "rec", pick: true, p: 3, y: 2009, via: "Musicales", c: 1 },
  { name: "Tanz der Vampire", genre: "Musical / Gótico (DE)", desc: "Musical gótico de vampiros con música de Jim Steinman: bombast teatral, coros enormes y baladas de estructura larga reutilizando material de su repertorio de rock. ▸ Versión: el elenco original de Viena de 1997 (en alemán, la definitiva); evita la adaptación de Broadway de 2002 (Dance of the Vampires), que fracasó.", origin: "rec", pick: true, p: 3, y: 1997, via: "Musicales" },
  { name: "Elisabeth", genre: "Musical / Gótico (AT)", desc: "Musical oscuro y gótico (la Emperatriz Sisi con la Muerte como personaje), dramático y sombrío. ▸ Versión: el elenco original de Viena de 1992 (Pia Douwes y Uwe Kröger, la clásica); el revival vienés de 2005 también es muy querido.", origin: "rec", pick: true, p: 3, y: 1992, via: "Musicales" },

  // ----- QUEEN PESADO (2ª vuelta + internacionales) -----
  { name: "Rhapsody of Fire", genre: "Symphonic Power Metal (IT)", desc: "Symphonic power italiano bombástico: orquesta, coros, narrativa de fantasía y shred neoclásico (Luca Turilli). Ópera épica cinematográfica con guitarras. Symphony of Enchanted Lands.", origin: "rec", pick: true, p: 3, y: 1993, via: "Queen pesado" },
  { name: "Powerwolf", genre: "Power Metal (DE)", desc: "Power teatral con órgano de iglesia, coros enormes y temática licantrópica camp. Coros apilados puro espíritu Queen. Blessed & Possessed.", origin: "rec", pick: true, p: 3, y: 2004, via: "Queen pesado" },
  { name: "Edguy", genre: "Power Metal (DE)", desc: "La banda principal de Tobias Sammet (Avantasia): power melódico y teatral con humor y gancho. Hellfire Club.", origin: "rec", pick: true, p: 3, y: 1992, via: "Queen pesado" },
  { name: "Beast in Black", genre: "Melodic / Power Metal (FI)", desc: "Metal ultra-teatral (ex-Battle Beast) que cruza power con synthwave ochentero y estribillos enormes. Berserker.", origin: "rec", pick: true, p: 3, y: 2015, via: "Queen pesado" },
  { name: "Dimmu Borgir", genre: "Symphonic Black Metal (NO)", desc: "Black sinfónico grandioso y bombástico, con orquesta y coros monumentales. Majestuosidad oscura épica. Death Cult Armageddon.", origin: "rec", pick: true, p: 3, y: 1993, via: "Queen pesado" },
  { name: "Haggard", genre: "Symphonic / Classical Metal (DE)", desc: "Colectivo de hasta 20 músicos: death/doom CON orquesta y coro clásicos reales tocando música casi medieval/barroca. Awaking the Centuries. [Comodín]", origin: "rec", pick: true, p: 2, y: 1991, via: "Queen pesado", c: 3 },
  { name: "Stolen Babies", genre: "Avant-garde Metal", desc: "Metal avant teatral con acordeón y voz femenina versátil (Dominique Persi), estética circense-oscura. Queen-meets-Mr.Bungle con peso.", p: 3, origin: "rec", pick: true, female: true, y: 2002, via: "Queen pesado" },
  { name: "Carach Angren", genre: "Symphonic Black Metal (NL)", desc: "Black sinfónico cinematográfico con narrativas de terror (cada disco una historia de fantasmas). Banda sonora de horror.", origin: "rec", pick: true, p: 2, y: 2003, via: "Queen pesado" },
  { name: "Delain", genre: "Symphonic Metal (NL)", desc: "Symphonic melódico y luminoso con Charlotte Wessels, gran gancho vocal. Veta Within Temptation.", origin: "rec", pick: true, female: true, p: 3, y: 2002, via: "Queen pesado" },
  { name: "Xandria", genre: "Symphonic Metal (DE)", desc: "Symphonic operístico dramático y orquestal con voz femenina. Veta sinfónica teatral.", origin: "rec", pick: true, female: true, p: 3, y: 1997, via: "Queen pesado" },
  { name: "Versailles", genre: "Symphonic Power / Visual Kei (JP)", desc: "Visual kei japonés barroco y teatral, con guitarras gemelas neoclásicas. Queen-meets-Japón.", origin: "rec", pick: true, p: 3, y: 2007, via: "Queen pesado" },
  { name: "Devil Doll", genre: "Avant-garde Rock Opera (SI/IT)", desc: "[Comodín] Cada disco es UNA sola pieza de entre cuarenta y setenta minutos, sin cortes, escrita por Mr. Doctor para banda de rock más orquesta, coro y piano, con la voz pasando de susurro a grito y de narración hablada a canto lírico, en inglés e italiano mezclados. Del primer álbum se prensó una única copia. La estructura es de ópera, no de rock. Entrada: Sacrilegium o Dies Irae.", p: 2, origin: "rec", pick: true, y: 1987, via: "Queen pesado", c: 3 },
  { name: "Tristania", genre: "Symphonic / Gothic Metal (NO)", desc: "Symphonic/gothic con voces femenina limpia y gutural, dramático y orquestal.", origin: "rec", pick: true, female: true, p: 3, y: 1996, via: "Queen pesado" },
  { name: "Twilight Force", genre: "Symphonic Power Metal (SE)", desc: "Symphonic power de fantasía, bombástico y melódico al extremo.", origin: "rec", pick: true, p: 3, y: 2011, via: "Queen pesado" },

  // ----- GOJIRA (2ª vuelta + internacionales) -----
  { name: "Cave In", genre: "Alt / Space / Prog Metal", desc: "Camaleónicos: del metalcore al space rock atmosférico al prog pesado. Imprevisibles. Jupiter, Antenna. [Cat 1]", p: 2, origin: "rec", pick: true, y: 1995, via: "Gojira", c: 1 },
  { name: "Textures", genre: "Prog / Djent (NL)", desc: "Prog/djent groove holandés muy en la veta Gojira: riffing percusivo, atmósferas y técnica con melodía. Dualism.", p: 2, origin: "rec", pick: true, y: 2001, via: "Gojira" },
  { name: "Oceans of Slumber", genre: "Prog / Doom Metal", desc: "Prog/doom atmosférico con Cammie Beverly (voz enorme) y aire de gótico sureño melancólico cinematográfico. The Banished Heart.", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Gojira" },
  { name: "Hypno5e", genre: "Cinematic Post-Metal (FR)", desc: "Prog/post-metal atmosférico y cinematográfico con narración hablada y cambios brutales de dinámica. Casi una película sonora.", origin: "rec", pick: true, p: 2, y: 2003, via: "Gojira" },
  { name: "Astronoid", genre: "Dream Thrash / Blackgaze", desc: "'Dream thrash': velocidad extrema + atmósferas etéreas shoegaze y voces limpias soñadoras. Pesado y bello a la vez.", origin: "rec", pick: true, p: 3, y: 2012, via: "Gojira" },
  { name: "Brutus", genre: "Post-Metal / Post-Hardcore (BE)", desc: "Post-metal atmosférico y dinámico con Stefanie Mannaerts cantando Y tocando la batería. Emotivo y poderoso.", p: 2, origin: "rec", pick: true, female: true, y: 2013, via: "Gojira" },
  { name: "Toundra", genre: "Post-Rock / Post-Metal (ES)", desc: "Post-rock/metal instrumental cinematográfico y pesado, construcciones épicas.", origin: "rec", pick: true, p: 2, y: 2007, via: "Gojira" },
  { name: "Jardín de la Croix", genre: "Math / Post-Rock (ES)", desc: "Math/post-rock instrumental técnico y enérgico, riffs entrelazados complejos.", origin: "rec", pick: true, p: 2, y: 2008, via: "Gojira" },
  { name: "sleepmakeswaves", genre: "Post-Rock / Metal (AU)", desc: "Post-rock/metal instrumental dinámico, de lo etéreo a lo demoledor.", origin: "rec", pick: true, p: 3, y: 2006, via: "Gojira" },

  // ----- BEHEMOTH (2ª vuelta + internacionales / escena polaca) -----
  { name: "Tribulation", genre: "Blackened Death / Gothic (SE)", desc: "De death crudo a blackened death gótico-melódico y teatral, casi rock gótico con guturales. Cada disco se aleja del anterior. The Children of the Night. [Cat 1]", p: 2, origin: "rec", pick: true, y: 2005, via: "Behemoth", c: 1 },
  { name: "Emperor", genre: "Symphonic Black Metal (NO)", desc: "Ihsahn escribe riffs de tremolo que cambian de armonía cada pocos compases en lugar de repetir un patrón, con teclados que doblan y contradicen a la guitarra a la vez, y estructuras que se acumulan sin volver al principio; la batería de Trym va a una densidad que tapa el compás a propósito. Anthems to the Welkin at Dusk está grabado como un muro donde cuesta separar los instrumentos, y eso es intencional. Entra por In the Nightside Eclipse, luego Anthems.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Nile", genre: "Technical Death Metal", desc: "Death técnico con temática e instrumentación del antiguo Egipto: pasajes exóticos, coros rituales y brutalidad vertiginosa. Annihilation of the Wicked.", p: 2, origin: "rec", pick: true, y: 1993, via: "Behemoth" },
  { name: "Mgła", genre: "Atmospheric Black Metal (PL)", desc: "Black atmosférico polaco (compatriotas de Behemoth): cohesivo, melódico-melancólico e hipnótico, elegantísimo. Exercises in Futility.", origin: "rec", pick: true, p: 2, y: 2000, via: "Behemoth" },
  { name: "Dissection", genre: "Melodic Blackened Death (SE)", desc: "Blackened death melódico oscuro y majestuoso, melodías de guitarra preciosas sobre la frialdad. Storm of the Light's Bane.", p: 2, origin: "rec", pick: true, y: 1989, via: "Behemoth" },
  { name: "Watain", genre: "Black Metal (SE)", desc: "Black ortodoxo y ritualista, oscuro y ceremonial, intensidad casi litúrgica. Lawless Darkness.", origin: "rec", pick: true, p: 3, y: 1998, via: "Behemoth" },
  { name: "Immolation", genre: "Dissonant Death Metal", desc: "Death disonante y atmosférico, oscuro y retorcido, riffs que desafían la gravedad. Close to a World Below.", p: 2, origin: "rec", pick: true, y: 1988, via: "Behemoth" },
  { name: "Myrkur", genre: "Atmospheric Black Metal (DK)", desc: "Black atmosférico/folk de Amalie Bruun: alterna lo etéreo-angelical con la crudeza black y arreglos folk nórdicos. M, Mareridt.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Behemoth" },
  { name: "Batushka", genre: "Ritual Black Metal (PL)", desc: "Black con cantos ortodoxos eslavos, estructurado como liturgia. Teatral, hipnótico y ceremonial. Litourgiya. [Comodín]", origin: "rec", pick: true, p: 3, y: 2015, via: "Behemoth", c: 3 },
  { name: "Schammasch", genre: "Avant-garde Black Metal (CH)", desc: "Black avant ritual: en 'Triangle' hizo un triple que va del black extremo a lo ambiental y meditativo. Vasto y atmosférico.", origin: "rec", pick: true, p: 2, y: 2009, via: "Behemoth" },
  { name: "Chelsea Wolfe", genre: "Doom / Gothic Rock", desc: "Doom/gótico/folk atmosférico y oscuro con voz hipnótica. Para el lado etéreo y siniestro. Abyss, Hiss Spun.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "Behemoth" },
  { name: "Hate", genre: "Blackened Death Metal (PL)", desc: "Blackened death majestuoso polaco muy en la línea de Behemoth.", origin: "rec", pick: true, p: 3, y: 1990, via: "Behemoth" },
  { name: "Vader", genre: "Death Metal (PL)", desc: "Death metal clásico polaco, veloz y contundente.", origin: "rec", pick: true, p: 3, y: 1983, via: "Behemoth" },
  { name: "Azarath", genre: "Blackened Death Metal (PL)", desc: "Blackened death del propio baterista de Behemoth (Inferno): conexión directa, brutal y veloz.", origin: "rec", pick: true, p: 3, y: 1998, via: "Behemoth" },
  { name: "Blut Aus Nord", genre: "Experimental Black Metal (FR)", desc: "La trilogía 777 reparte eso en tres discos deliberadamente distintos, uno metálico, uno industrial y disonante, y uno atmosférico, y The Desanctification mete cajas de ritmo tartamudas y voz limpia. Francés, prácticamente una sola persona. Entra por The Work Which Transforms God.", origin: "rec", p: 1, y: 1995, c: 1 },
  { name: "The Great Old Ones", genre: "Atmospheric Black Metal (FR)", desc: "Black atmosférico y cinematográfico con narrativa lovecraftiana. Envolvente y oscuro.", origin: "rec", pick: true, p: 2, y: 2009, via: "Behemoth" },
  { name: "Cult of Fire", genre: "Ritual Black Metal (CZ)", desc: "Black ritual con temática hindú y letras en sánscrito, atmosférico y exótico.", origin: "rec", pick: true, p: 2, y: 2011, via: "Behemoth" },
  { name: "Furia", genre: "Avant-garde Black Metal (PL)", desc: "Black avant con letras en polaco, poético y peculiar. De la escena de Behemoth. [Cat 1]", origin: "rec", pick: true, p: 2, y: 2003, via: "Behemoth", c: 1 },

  // ----- PROTEST THE HERO (3ª vuelta + internacionales) -----
  { name: "Tera Melos", genre: "Math Rock / Experimental", desc: "Math rock experimental y juguetón, técnico y caótico pero melódico, cambia de textura constantemente. Patagonian Rats. [Cat 1]", origin: "rec", pick: true, p: 2, y: 2004, via: "PTH", c: 1 },
  { name: "The Number Twelve Looks Like You", genre: "Mathcore", desc: "Mathcore caótico y ecléctico que salta del jazz a la brutalidad a lo melódico en segundos. Nuclear. Sad. Nuclear. [Cat 1]", origin: "rec", pick: true, p: 3, y: 2003, via: "PTH", c: 1 },
  { name: "After the Burial", genre: "Djent / Prog Metalcore", desc: "Djent/prog metalcore técnico con riffs intrincados y groove pesado. Rareform.", p: 2, origin: "rec", pick: true, y: 2004, via: "PTH" },
  { name: "Tricot", genre: "Math Rock (JP)", desc: "Math rock japonés con voz femenina: ritmos intrincados, guitarras entrelazadas y melodías brillantes, energía luminosa. 3, A N D.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "PTH" },
  { name: "Vexed", genre: "Prog Metalcore (UK)", desc: "Prog metalcore moderno con Megan Targett: djenty, técnico y agresivo con pasajes melódicos. Culling Culture.", p: 2, origin: "rec", pick: true, female: true, y: 2019, via: "PTH" },
  { name: "Sithu Aye", genre: "Prog / Instrumental (UK)", desc: "Prog/djent instrumental brillante y tappy, luminoso y melódico.", origin: "rec", pick: true, p: 3, y: 2011, via: "PTH" },
  { name: "Standards", genre: "Math Rock / Instrumental", desc: "Dúo instrumental de Los Ángeles, formado en 2017: Marcos Mena hace todo el trabajo armónico con tapping a dos manos sobre batería, sin bajo, y las piezas duran dos minutos y no se repiten. Todos sus discos llevan título de fruta. Entrada: Fruit Town.", origin: "rec", pick: true, p: 3, y: 2017, via: "PTH" },
  { name: "Tigran Hamasyan", genre: "Jazz / Prog (AM)", desc: "Pianista armenio: jazz, prog, folk armenio y groove casi metalero, complejidad rítmica brutal. Estira tu definición de 'instrumental interesante'. Mockroot. [Comodín]", p: 2, origin: "rec", pick: true, y: 2006, via: "PTH", c: 3 },
  { name: "Paledusk", genre: "Prog Metalcore (JP)", desc: "Prog metalcore caótico y ecléctico que salta de género en segundos, frenético y divertido. [Cat 1]", p: 2, origin: "rec", pick: true, y: 2015, via: "PTH", c: 1 },
  { name: "Elephant Gym", genre: "Math Rock (TW)", desc: "Taiwaneses, instrumentales. El bajo de KT Chang no marca la raíz: lleva la melodía principal con acordes y armónicos mientras la guitarra hace figuras cortas por encima, sobre métricas que cambian sin que suene forzado. Entrada: Underwater.", origin: "rec", pick: true, female: true, p: 2, y: 2012, via: "PTH" },
  { name: "toe", genre: "Math Rock (JP)", desc: "Math rock instrumental jazzy y melódico, intrincado pero cálido.", origin: "rec", pick: true, p: 2, y: 2000, via: "PTH" },
  { name: "David Maxim Micić", genre: "Prog / Djent (RS)", desc: "Prog/djent instrumental virtuoso y cinematográfico (Bilo, Ego), festín de guitarra y composición.", p: 2, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Disperse", genre: "Prog / Fusion (PL)", desc: "Prog/fusión técnico-melódico, atmosférico y luminoso.", p: 2, origin: "rec", pick: true, y: 2007, via: "PTH" },
  { name: "mouse on the keys", genre: "Math / Jazz (JP)", desc: "Math/jazz instrumental de piano, intenso y elegante.", origin: "rec", pick: true, p: 2, y: 2006, via: "PTH" },

  // ----- DREAM THEATER (2ª vuelta + internacionales) -----
  { name: "Madder Mortem", genre: "Prog / Doom (NO)", desc: "Prog/doom ecléctico y poderoso con Agnete Kjølsrud (voz descomunal). Saltan de lo pesado a lo atmosférico a casi folk. Deadlands, Mercury. [Cat 1]", p: 2, origin: "rec", pick: true, female: true, y: 1997, via: "Dream Theater", c: 1 },
  { name: "Subterranean Masquerade", genre: "Oriental Prog Metal (IL)", desc: "Prog 'oriental' que mezcla death, prog, folk de Oriente Medio, jazz y voces limpias/guturales. Eclecticismo total. Vagabond. [Cat 1]", p: 2, origin: "rec", pick: true, y: 1997, via: "Dream Theater", c: 1 },
  { name: "Evergrey", genre: "Prog / Power Metal (SE)", desc: "Prog/power oscuro y melancólico, identidad emocional fortísima y gran guitarra. Para el lado sentido de DT. The Inner Circle.", p: 3, origin: "rec", pick: true, y: 1995, via: "Dream Theater" },
  { name: "Angra", genre: "Prog / Power Metal (BR)", desc: "Prog/power técnico-melódico con elementos de música brasileña. Virtuosismo con sabor propio. Holy Land, Temple of Shadows.", p: 3, origin: "rec", pick: true, y: 1991, via: "Dream Theater" },
  { name: "Galneryus", genre: "Power / Prog Metal (JP)", desc: "Power/prog japonés ultra-virtuoso, shred neoclásico vertiginoso (Syu) y teclados estilo Symphony X. Festín instrumental. Resurrection.", p: 3, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Kingcrow", genre: "Prog Metal (IT)", desc: "Prog atmosférico y melódico, melancólico y de texturas cuidadísimas. Subestimadísimos. Eidos, The Persistence.", p: 3, origin: "rec", pick: true, y: 1996, via: "Dream Theater" },
  { name: "Iamthemorning", genre: "Chamber Prog (RU)", desc: "Prog de cámara delicado: piano, cuerdas y la voz cristalina de Marjana Semkina. Exquisito sin ser pesado. Lighthouse.", p: 3, origin: "rec", pick: true, female: true, y: 2010, via: "Dream Theater" },
  { name: "Anubis Gate", genre: "Prog Metal (DK)", desc: "Prog metal melódico y atmosférico, sólido y luminoso.", p: 3, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Adagio", genre: "Neoclassical Prog Metal (FR)", desc: "Prog metal neoclásico, virtuoso y oscuro.", p: 3, origin: "rec", pick: true, y: 2000, via: "Dream Theater" },
  { name: "Andromeda", genre: "Technical Prog Metal (SE)", desc: "Prog metal técnico y veloz, instrumentalmente exigente.", p: 2, origin: "rec", pick: true, y: 1999, via: "Dream Theater" },
  { name: "Liquid Tension Experiment", genre: "Prog / Instrumental", desc: "Prog metal instrumental sin formato canción, con teclado y guitarra intercambiándose el papel principal y el Chapman Stick de Levin dando un bajo con ataque distinto al normal. El problema es la mitad improvisada: buena parte del material sale de jams de estudio, y ahí es virtuosismo por el virtuosismo. Lo que aguanta es lo escrito de verdad, como Acid Rain o Universal Mind. Queda por encima de Planet X porque hay más composición real y menos exhibición, pero no compite con lo de arriba. Y sale de comodín porque tiene pares evidentes: Planet X, The Aristocrats. Entra por el primero (1998).", origin: "rec", p: 2, y: 1997, c: 2 },
  { name: "Goblin", genre: "Prog Rock / Soundtrack (IT)", desc: "Prog italiano instrumental hecho para cine de terror: patrones cortos de teclado y bajo repetidos en métricas irregulares que crean tensión por acumulación en vez de por melodía. Entrada: Profondo Rosso.", origin: "rec", pick: true, p: 2, y: 1972, via: "Dream Theater" },

  // ----- TRIVIUM (2ª vuelta + internacionales) -----
  { name: "Carcass", genre: "Melodic Death (UK)", desc: "De goregrind ilegible a Heartwork, con guitarras gemelas armonizadas y solos escritos como melodía y no como exhibición. Necroticism ya encadenaba riffs en estructuras largas, y Surgical Steel (2013) volvió con esa escritura intacta treinta años después. Entrada: Heartwork.", origin: "rec", pick: true, p: 1, y: 1985, via: "Trivium", c: 1 },
  { name: "Testament", genre: "Thrash Metal", desc: "Alex Skolnick viene del jazz y eso se nota en sus solos, que son melódicos y con desarrollo en vez de ráfagas, y ese es el mejor argumento que tienen. Pero por debajo es thrash de la Bay Area muy bien hecho y bastante ortodoxo, con riffs de palm mute, estructuras de estrofa y estribillo y poca sorpresa rítmica. Excelente dentro del molde. Entra por The New Order o The Legacy.", origin: "rec", p: 2, y: 1983, c: 2 },
  { name: "Annihilator", genre: "Technical Thrash (CA)", desc: "Thrash técnico alrededor de Jeff Waters (guitarrista virtuoso): riffs intrincadísimos y solos vertiginosos. Alice in Hell.", origin: "rec", pick: true, p: 2, y: 1984, via: "Trivium" },
  { name: "Coroner", genre: "Progressive Thrash (CH)", desc: "Thrash progresivo y técnico, casi jazzístico en complejidad rítmica/armónica. De lo más sofisticado del thrash. Mental Vortex.", p: 2, origin: "rec", pick: true, y: 1985, via: "Trivium" },
  { name: "Kalmah", genre: "Melodic Death (FI)", desc: "Melodeath 'de pantano' con shred neoclásico y teclados entrelazados. Veloz y técnico, veta Children of Bodom con identidad propia. The Black Waltz.", origin: "rec", pick: true, p: 3, y: 1998, via: "Trivium" },
  { name: "Aephanemer", genre: "Symphonic Melodic Death (FR)", desc: "Melodeath sinfónico con Marion Bascoul: melodías preciosas, orquestación y guturales potentes. Prokopton.", origin: "rec", pick: true, female: true, p: 2, y: 2014, via: "Trivium" },
  { name: "God Forbid", genre: "Melodic Metalcore / Thrash", desc: "Metalcore/thrash melódico con guitarras gemelas y groove, veta Ascendancy/In Waves, infravalorados. IV: Constitution of Treason.", p: 3, origin: "rec", pick: true, y: 1996, via: "Trivium" },
  { name: "Mekong Delta", genre: "Technical / Prog Thrash (DE)", desc: "Thrash técnico/progresivo que adapta piezas clásicas (Mussorgsky) y mete compases imposibles. Singular y cerebral.", p: 2, origin: "rec", pick: true, y: 1985, via: "Trivium" },
  { name: "Watchtower", genre: "Progressive Thrash", desc: "El bajo de Doug Keyser no acompaña: lleva líneas independientes mientras la batería cambia de compás dentro de la frase, sobre thrash tocado con lógica de jazz. Solo tienen dos discos y los dos hacen lo mismo. Entrada: Control and Resistance.", origin: "rec", pick: true, p: 1, y: 1982, via: "Trivium", c: 3 },
  { name: "Crystal Viper", genre: "Heavy / Power Metal (PL)", desc: "Heavy/power clásico con Marta Gabriel, melódico y épico.", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Trivium" },
  { name: "Walls of Jericho", genre: "Metalcore / Hardcore", desc: "Metalcore/hardcore agresivo con Candace Kucsulain, crudo y con pegada.", origin: "rec", pick: true, female: true, p: 3, y: 1998, via: "Trivium" },

  // ----- AVENGED SEVENFOLD (repaso de la rama madre) -----
  { name: "Buckethead", genre: "Avant / Instrumental Guitar", desc: "Guitarrista enmascarado hiperprolífico que salta del metal al ambient al funk a lo avant sin parar. Festín de guitarra y reinvención perpetua. Colma, Electric Tears. [Cat 1]", p: 2, origin: "rec", pick: true, y: 1991, via: "A7X", c: 1 },
  { name: "Marty Friedman", genre: "Instrumental Guitar (US/JP)", desc: "El ex-Megadeth en solitario: virtuoso con fraseo exótico (escalas japonesas/árabes) y discos instrumentales eclécticos. Tokyo Jukebox, Inferno.", origin: "rec", pick: true, p: 2, y: 1988, via: "A7X" },
  { name: "Lovebites", genre: "Power / Melodic Metal (JP)", desc: "Banda femenina: power/melodic con guitarras gemelas neoclásicas vertiginosas, muy en la onda de los solos de City of Evil. Electric Pentagram.", origin: "rec", pick: true, female: true, p: 3, y: 2016, via: "A7X" },
  { name: "The Warning", genre: "Hard Rock / Alt Metal (MX)", desc: "Trío de hermanas de Monterrey: Daniela a la guitarra y voz, Alejandra al bajo y Paulina a la batería, que además canta principal en varios temas mientras toca. Hard rock técnico con riffs ajustados, cambios de tempo dentro de la canción y armonías vocales a tres. Empezaron subiendo versiones a internet siendo niñas y acabaron girando con bandas grandes. Entrada: Error o Keep Me Fed.", origin: "rec", pick: true, female: true, p: 2, y: 2013, via: "A7X" },
  { name: "Band-Maid", genre: "Hard Rock (JP)", desc: "Hard rock japonés técnico y ajustadísimo: riffs intrincados con paradas al milímetro, dos guitarras repartiéndose líneas distintas y una batería que sostiene cambios constantes. Entrada: World Domination.", origin: "rec", pick: true, female: true, p: 2, y: 2013, via: "A7X" },
  { name: "Black Label Society", genre: "Blues / Heavy Metal", desc: "Zakk Wylde, virtuoso del blues-metal: riffs pesados y solos con feeling. The Blessed Hellride.", origin: "rec", pick: true, p: 3, y: 1998, via: "A7X" },
  { name: "Steve Vai", genre: "Instrumental Guitar", desc: "Virtuoso teatral e instrumental que hace 'cantar' a la guitarra, melódico y experimental. La cumbre del instrumento. Passion and Warfare.", origin: "rec", pick: true, p: 2, y: 1984, via: "A7X" },
  { name: "Nemophila", genre: "Melodic Death / Metal (JP)", desc: "Banda femenina: metal/melodeath con voz que alterna limpio potente y gutural, guitarras técnicas y energía. Seize the Fate.", origin: "rec", pick: true, female: true, p: 3, y: 2019, via: "A7X" },

  // ----- CAGE THE ELEPHANT (2ª vuelta + internacionales) -----
  { name: "Café Tacvba", genre: "Alt Rock (MX)", desc: "Re (1994) es un doble donde cruzan huapango, son jarocho, norteño, ska, punk y fusión jazz, y las capas se transforman dentro de la misma canción: El Aparato arranca como huapango, entra un sintetizador y termina en cuerdas y cantos panafricanos. Ellos mismos citan a Ministry y a Bach como inspiración. Rolling Stone lo nombró el mejor disco de rock latino de la historia. Entrada: Re.", origin: "rec", pick: true, p: 1, y: 1989, via: "Cage the Elephant", c: 1 },
  { name: "Pond", genre: "Psych Rock (AU)", desc: "Psych rock ecléctico y prolífico (hermano de Tame Impala), colorido y experimental. The Weather. [Cat 1]", p: 3, origin: "rec", pick: true, y: 2008, via: "Cage the Elephant", c: 1 },
  { name: "Unknown Mortal Orchestra", genre: "Psych / Funk (NZ/US)", desc: "Psych/funk lo-fi con Ruban Nielson (gran guitarrista): melodías retorcidas, groove y atmósferas cálidas. Multi-Love, II.", origin: "rec", pick: true, p: 3, y: 2010, via: "Cage the Elephant" },
  { name: "The Black Angels", genre: "Psych Rock", desc: "Psych rock oscuro y dronéante, hipnótico y atmosférico. Para el lado moody tipo 'Always Something'. Passover.", origin: "rec", pick: true, p: 3, y: 2004, via: "Cage the Elephant" },
  { name: "Warpaint", genre: "Atmospheric Indie Rock", desc: "Banda femenina: atmosférico e hipnótico con guitarras entrelazadas, bajo protagonista y ritmos intrincados. Sutil y moody. The Fool.", p: 3, origin: "rec", pick: true, female: true, y: 2004, via: "Cage the Elephant" },
  { name: "Blues Pills", genre: "Blues / Psych Rock (SE)", desc: "Blues/psych retro con Elin Larsson (voz poderosa) y guitarra con feeling. Cálido y orgánico. Lady in Gold.", origin: "rec", pick: true, female: true, p: 3, y: 2011, via: "Cage the Elephant" },
  { name: "Fontaines D.C.", genre: "Post-Punk (IE)", desc: "Post-punk irlandés que fue de lo crudo y recitado a lo texturado y ambicioso disco a disco, con guitarras cada vez más tratadas y arreglos más amplios; en Romance ya hay sintetizadores y cuerda. Entrada: Skinty Fia.", origin: "rec", pick: true, p: 2, y: 2014, via: "Cage the Elephant" },
  { name: "Hinds", genre: "Garage Rock (ES)", desc: "Banda femenina: garage rock crudo, melódico y desenfadado, armonías vocales y energía juvenil. I Don't Run.", origin: "rec", pick: true, female: true, p: 3, y: 2011, via: "Cage the Elephant" },

  // ----- METALCORE (2ª vuelta + internacionales) -----
  { name: "The Chariot", genre: "Chaotic Metalcore", desc: "Metalcore grabado casi en directo y a propósito sin cuadricular, con cortes bruscos a silencio, feedback usado como parte del tema y estructuras que no repiten el estribillo ni una vez. Josh Scogin grita por encima de riffs que se desmontan a mitad. Es lo contrario de la fórmula y por eso está donde está, aunque el precio es que hay más energía que desarrollo. Entra por Long Live.", origin: "rec", p: 2, y: 2003, c: 1 },
  { name: "Poison the Well", genre: "Metalcore", desc: "Pionero que experimentó mucho entre discos metiendo melodía, atmósfera y rarezas. Inquietos y eclécticos. The Opposite of December. [Cat 1]", p: 2, origin: "rec", pick: true, y: 1997, via: "Metalcore", c: 1 },
  { name: "Converge", genre: "Metalcore / Mathcore", desc: "Kurt Ballou escribe riffs disonantes que cambian de figura cada pocos segundos y nunca vuelven al mismo sitio, y Ben Koller toca la batería como una voz más, cambiando de patrón bajo el mismo riff y metiendo redobles que rompen el compás en vez de marcarlo. Jane Doe alterna esa violencia con pasajes largos y lentos dentro del mismo disco. Ballou además graba a media escena desde su propio estudio. Entra por Jane Doe.", origin: "rec", p: 1, y: 1990, c: 2 },
  { name: "Botch", genre: "Mathcore", desc: "Riffs angulares en métricas que no se repiten y canciones que acaban en un sitio distinto del que empezaron, sin volver nunca a la primera sección. American Nervoso y We Are the Romans funcionan igual. Entrada: We Are the Romans.", origin: "rec", pick: true, p: 1, y: 1993, via: "Metalcore" },
  { name: "Novelists", genre: "Prog Metalcore (FR)", desc: "Prog metalcore melódico y técnico, pulido y emotivo. De los más sólidos de Europa. Noir, C'est La Vie.", p: 2, origin: "rec", pick: true, y: 2013, via: "Metalcore" },
  { name: "Pupil Slicer", genre: "Mathcore / Grind (UK)", desc: "Mathcore/grind caótico y técnico con Kate Davies, con giro progresivo en el segundo disco. Fresco y complejo. Mirrors, Blossom.", p: 2, origin: "rec", pick: true, female: true, y: 2019, via: "Metalcore" },
  { name: "Frontierer", genre: "Dissonant Mathcore", desc: "Mathcore disonante y glitchy: capas de guitarra recortadas digitalmente, samples de ruido metidos como percusión y riffs que cambian de figura cada compás, todo mezclado como una pared saturada. Abrasivo de principio a fin. Entrada: Unloved.", origin: "rec", pick: true, p: 2, y: 2012, via: "Metalcore" },
  { name: "Vildhjarta", genre: "Thall / Djent (SE)", desc: "Pioneros del 'thall', variante oscura y pesadísima del djent, atmósferas claustrofóbicas y riffs rarísimos. Måsstaden under vatten.", p: 2, origin: "rec", pick: true, y: 2005, via: "Metalcore" },
  { name: "Dream State", genre: "Melodic Post-Hardcore (UK)", desc: "Post-hardcore/metalcore melódico con CJ Gilpin, emotivo y dinámico, pero dentro de la fórmula del género: la voz es lo distintivo, no la escritura instrumental.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Metalcore" },

  // ----- BE'LAKOR / MELODEATH ATMOSFÉRICO (2ª vuelta + internacionales) -----
  { name: "Katatonia", genre: "Atmospheric Prog Metal (SE)", desc: "La reinvención es real (empezaron en doom-death y acabaron en rock atmosférico melancólico) y por eso conserva la categoría 1, pero el tier va por otro eje: instrumentalmente es contención deliberada, no complejidad ni rareza estructural. Al lado de Gentle Giant, Cynic o Watchtower desentona. Novedad: Anders Nyström, cofundador y guitarrista durante casi 35 años, se fue en marzo de 2025 diciendo que los caminos con Jonas Renkse se habían separado demasiado; Renkse sigue con formación nueva.", origin: "rec", p: 2, y: 1991, c: 1 },
  { name: "Borknagar", genre: "Prog Folk / Viking Metal (NO)", desc: "Prog folk/viking atmosférico muy evolutivo, mezcla black, prog y melodía con voces limpias/guturales. Aventurero y cósmico. Empiricism. [Cat 1]", p: 2, origin: "rec", pick: true, y: 1995, via: "Be'lakor", c: 1 },
  { name: "An Abstract Illusion", genre: "Prog Death (SE)", desc: "Death progresivo atmosférico y sinfónico con canciones larguísimas que son viajes completos. La cualidad 'aventura' de Be'lakor aún más ambiciosa. Woe.", p: 2, origin: "rec", pick: true, y: 2013, via: "Be'lakor" },
  { name: "Eternal Storm", genre: "Prog Melodic Death (ES)", desc: "Melodeath progresivo y atmosférico casi calcado al espíritu de Be'lakor: melodías hermosas y composiciones que evolucionan. Come the Tide.", origin: "rec", pick: true, p: 2, y: 2008, via: "Be'lakor" },
  { name: "October Tide", genre: "Melodic Death/Doom (SE)", desc: "Melodic death/doom melancólico y atmosférico (ligados a Katatonia), bellísimo y triste. Rain Without End.", origin: "rec", pick: true, p: 2, y: 1995, via: "Be'lakor" },
  { name: "Moonsorrow", genre: "Pagan / Folk Metal (FI)", desc: "Pagan/folk con canciones épicas larguísimas (10-30 min) que son odiseas atmosféricas. Kivenkantaja.", origin: "rec", pick: true, p: 2, y: 1995, via: "Be'lakor" },
  { name: "Draconian", genre: "Gothic Doom Metal (SE)", desc: "Gothic doom/death atmosférico y melancólico con voces femenina limpia y gutural masculina. Lento y hermoso. Sovran.", origin: "rec", pick: true, female: true, p: 3, y: 1994, via: "Be'lakor" },
  { name: "Trees of Eternity", genre: "Gothic Doom (SE/FI)", desc: "Doom/gothic atmosférico con la voz etérea de Aleah Stanbridge (un solo álbum póstumo precioso). Melancólico y singular. Hour of the Nightingale.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Be'lakor" },
  { name: "Fractal Universe", genre: "Prog Death (FR)", desc: "Death progresivo con saxofón y jazz integrados, ambicioso y técnico. The Impassable Horizon.", p: 2, origin: "rec", pick: true, y: 2014, via: "Be'lakor" },

  // ----- PANIC! AT THE DISCO (2ª vuelta + internacionales) -----
  { name: "David Bowie", genre: "Art Rock / Glam (UK)", desc: "En Low la cara B son piezas casi instrumentales con los sintetizadores tratados como textura y sin estructura de canción; en Heroes la guitarra de Robert Fripp está grabada con retroalimentación controlada según la distancia al amplificador; y Blackstar lo grabó con el cuarteto de jazz de Donny McCaslin, con el saxo llevando líneas principales en compases irregulares. Ziggy y Aladdin Sane tienen a Mick Ronson escribiendo los arreglos de cuerda. Cinco décadas cambiando de sistema. Entra por Low o Blackstar.", origin: "rec", p: 1, y: 1967, c: 1 },
  { name: "Roxy Music", genre: "Art / Glam Rock (UK)", desc: "Art-glam sofisticado y elegante (Ferry + Eno): teatral, experimental y melódico. For Your Pleasure, Avalon. [Cat 1]", origin: "rec", pick: true, p: 2, y: 1971, via: "Panic!", c: 1 },
  { name: "Scott Walker", genre: "Baroque / Avant Pop", desc: "De crooner barroco orquestal a la vanguardia más oscura: una de las evoluciones más radicales del pop. Scott 4, The Drift. [Cat 1]", p: 2, origin: "rec", pick: true, y: 1967, via: "Panic!", c: 1 },
  { name: "10cc", genre: "Art Pop (UK)", desc: "Art pop barroco e ingenioso de los 70, instrumentalmente inventivo y juguetón. Queen-adjacent. The Original Soundtrack.", origin: "rec", pick: true, p: 2, y: 1972, via: "Panic!" },
  { name: "Sufjan Stevens", genre: "Baroque Chamber Pop", desc: "Folk de cámara con orquestaciones ornamentadas (vientos, cuerdas, coros), conceptual y delicado. Para el lado barroco de Pretty.Odd. Illinois.", origin: "rec", pick: true, p: 2, y: 2000, via: "Panic!" },
  { name: "Father John Misty", genre: "Baroque Singer-Songwriter", desc: "Singer-songwriter barroco-orquestal, teatral, ingenioso y mordaz, arreglos lujosos. I Love You, Honeybear.", origin: "rec", pick: true, p: 3, y: 2012, via: "Panic!" },
  { name: "Andrew Bird", genre: "Baroque Chamber Pop", desc: "Chamber pop barroco con violín, silbidos y arreglos intrincados; sofisticado y peculiar. Armchair Apocrypha.", origin: "rec", pick: true, p: 2, y: 1996, via: "Panic!" },
  { name: "Tori Amos", genre: "Baroque Piano Pop", desc: "El piano lleva la armonía completa sin banda debajo en buena parte de su obra, con compases que cambian dentro de la frase y una voz que salta de registro contra ese piano en vez de apoyarse en él. Little Earthquakes, Boys for Pele y From the Choirgirl Hotel son tres planteamientos distintos del mismo instrumento. Entrada: Boys for Pele.", origin: "rec", pick: true, female: true, p: 2, y: 1990, via: "Panic!" },
  { name: "Babasónicos", genre: "Alt Rock (AR)", desc: "Rock alternativo ecléctico y sofisticado, sensual y experimental, producción rica. Joya del rock en español que se reinventa. Jessico, Infame.", p: 2, origin: "rec", pick: true, y: 1991, via: "Panic!" },
  { name: "Fiona Apple", genre: "Art / Baroque Pop", desc: "Pop de piano barroco-jazzístico, intrincado, ecléctico y experimental, estructuras imprevisibles. 'Fetch the Bolt Cutters' es una obra maestra de la rareza. [Comodín]", origin: "rec", pick: true, female: true, p: 2, y: 1996, via: "Panic!", c: 3 },
  { name: "The Tiger Lillies", genre: "Dark Cabaret (UK)", desc: "Dark cabaret de tres personas: acordeón, contrabajo y percusión mínima bajo el falsete grotesco de Martyn Jacques, con temática siniestra y fraseo de cabaret de Weimar. Sin guitarra y sin batería de rock. Entrada: Shockheaded Peter.", origin: "rec", pick: true, p: 3, y: 1989, via: "Panic!" },
  { name: "Dir En Grey", genre: "Visual Kei / Experimental (JP)", desc: "Visual kei que cruza metal, art rock, balada y experimentación con dramatismo y cambios de registro. Teatral e intenso. Uroboros.", p: 3, origin: "rec", pick: true, y: 1997, via: "Panic!" },

  // ----- MUSE (2ª vuelta + internacionales) -----
  { name: "Twelve Foot Ninja", genre: "Eclectic Prog Metal (AU)", desc: "Eclecticismo desbocado: prog metal que salta a funk, latin, reggae, jazz y djent dentro de una canción, con técnica y humor. Silent Machine. Veta 'Supermassive'. [Cat 1]", p: 3, origin: "rec", pick: true, y: 2008, via: "Muse", c: 1 },
  { name: "Archive", genre: "Electronic / Prog Rock (UK)", desc: "Rock electrónico y prog de escala cinematográfica: temas largos que crecen por capas y arreglos orquestales reales, con la voz rotando entre varios cantantes de disco a disco. Entrada: Controlling Crowds.", origin: "rec", pick: true, p: 2, y: 1994, via: "Muse" },
  { name: "Zoé", genre: "Psych Alt Rock (MX)", desc: "Rock alternativo psicodélico y espacial, atmosférico y sofisticado, texturas envolventes. Vibra cósmica de Muse con conexión latina. Reptilectric.", p: 3, origin: "rec", pick: true, y: 1997, via: "Muse" },
  { name: "Elbow", genre: "Orchestral Alt Rock (UK)", desc: "Alt rock orquestal, sofisticado y emotivo, arreglos cuidadísimos y crescendos majestuosos. Para el lado Resistance. The Seldom Seen Kid.", p: 3, origin: "rec", pick: true, y: 1997, via: "Muse" },
  { name: "Placebo", genre: "Alt Rock (UK)", desc: "Alt rock dramático y andrógino, energía y melancolía, riffs y atmósfera. Para el lado más oscuro-rockero. Without You I'm Nothing.", p: 3, origin: "rec", pick: true, y: 1994, via: "Muse" },
  { name: "Amplifier", genre: "Space / Prog Rock (UK)", desc: "Space/prog rock denso y riffero, hipnótico y pesado. Para el lado Origin of Symmetry. The Octopus.", origin: "rec", pick: true, p: 3, y: 1999, via: "Muse" },
  { name: "VUUR", genre: "Prog Metal (NL)", desc: "Prog metal con Anneke van Giersbergen (voz enorme): pesado, melódico y dramático. Cities.", p: 3, origin: "rec", pick: true, female: true, y: 2016, via: "Muse" },
  { name: "65daysofstatic", genre: "Post-Rock / Electronic (UK)", desc: "Post-rock con electrónica integrada, math rock e intensidad, construcciones que estallan. Electrónica al servicio de la música. The Fall of Math.", origin: "rec", pick: true, p: 2, y: 2001, via: "Muse" },
  { name: "Stream of Passion", genre: "Prog Metal (MX/NL)", desc: "Prog metal melódico y atmosférico con Marcela Bovio (mexicana de formación clásica). Dramático y elegante. The Flame Within.", p: 3, origin: "rec", pick: true, female: true, y: 2005, via: "Muse" },

  // ----- ICE NINE KILLS (2ª vuelta + internacionales) -----
  { name: "Bilmuri", genre: "Eclectic Metalcore", desc: "Metalcore cruzado con country, saxo, pop y electrónica, pero por debajo del disfraz la escritura es de canción con estribillo: bien hecha y muy divertida, sin ambición instrumental. Entrada: Goners.", origin: "rec", p: 3, y: 2016, c: 2 },
  { name: "Lord of the Lost", genre: "Gothic Industrial Metal (DE)", desc: "Saltan entre gotico, industrial, sinfonico, glam y pop oscuro, pero ese salto es de estetica y de vestuario, no de estructura: la escritura por debajo sigue siendo la misma cancion de rock con gancho. La critica de Blood and Glitter lo dijo sin rodeos, que era una version abreviada de Scorpions y Rammstein sin originalidad propia. Quedaron ultimos en Eurovision 2023. Teatralidad alta, ambicion instrumental baja.", origin: "rec", p: 3, y: 2007, c: 2 },
  { name: "King Diamond", genre: "Theatrical Heavy Metal (DK)", desc: "Andy LaRocque escribe guitarras armonizadas con giros neoclásicos y las canciones encadenan varias partes sin repetirlas. Pero el peso de la banda está en la narración y la puesta en escena más que en la escritura instrumental, y Mercyful Fate hace lo mismo instrumentalmente y mejor. Entra por Abigail.", origin: "rec", p: 2, y: 1985, c: 2 },
  { name: "Lorna Shore", genre: "Symphonic Deathcore", desc: "Deathcore sinfónico de escala cinematográfica: orquestación con coro y cuerda escrita como capa protagonista, no de fondo, sobre blast beats constantes, y Will Ramos alternando gutural profundo, agudo desgarrado y ese trino gutural que lo hizo famoso. Grandilocuente hasta el exceso, y a propósito. Entrada: Pain Remains.", origin: "rec", pick: true, p: 2, y: 2009, via: "Ice Nine Kills" },
  { name: "Deathstars", genre: "Industrial Gothic Metal (SE)", desc: "Metal industrial gótico teatral, oscuro y con groove, estética de glam siniestro. Termination Bliss.", origin: "rec", pick: true, p: 3, y: 2000, via: "Ice Nine Kills" },
  { name: "Once Human", genre: "Melodic Death / Metalcore", desc: "Melodeath/metalcore con Lauren Hart, agresivo y melódico con voz versátil (limpio + gutural). Scar Weaver.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Ice Nine Kills" },
  { name: "Mercyful Fate", genre: "Theatrical Heavy Metal (DK)", desc: "Hank Shermann y Michael Denner escriben temas de siete y ocho minutos encadenando cuatro o cinco secciones distintas que no vuelven, con guitarras armonizadas en intervalos incómodos y cambios de tempo dentro de la frase, cuando en 1984 el resto del heavy hacía estrofa y estribillo. Entra por Don't Break the Oath.", origin: "rec", p: 1, y: 1981, c: 2 },
  { name: "Fearless Vampire Killers", genre: "Horror Glam Punk (UK)", desc: "Glam punk/rock de terror con concepto narrativo (vampiros, una saga), teatral y melódico. Espíritu conceptual-horror de INK.", origin: "rec", pick: true, p: 3, y: 2008, via: "Ice Nine Kills" },
  { name: "Lordi", genre: "Hard Rock / Horror (FI)", desc: "Hard rock de monstruos con disfraces y teatralidad de terror serie B. Pegadizo y camp (ganaron Eurovisión).", origin: "rec", pick: true, p: 3, y: 1992, via: "Ice Nine Kills" },

  // ----- IN FLAMES (2ª vuelta + internacionales) -----
  { name: "Myrath", genre: "Oriental Prog Metal (TN)", desc: "Prog 'oriental' tunecino que integra instrumentación y escalas de Oriente Medio con melodeath/power melódico. Exótico y ambicioso, como nada en el género. Shehili. [Cat 1]", p: 3, origin: "rec", pick: true, y: 2006, via: "In Flames", c: 1 },
  { name: "Orbit Culture", genre: "Melodic Death / Groove (SE)", desc: "La banda más fresca de la veta In Flames moderna: melódico pesado y atmosférico que cruza melodeath con el groove de Gojira. El 'In Flames moderno bien hecho'. Nija.", origin: "rec", pick: true, p: 2, y: 2013, via: "In Flames" },
  { name: "Wolfheart", genre: "Melodic Death (FI)", desc: "Melodeath atmosférico 'winter metal' de Tuomas Saukkonen: épico, frío y con melodías preciosas. Wolves of Karelia.", origin: "rec", pick: true, p: 3, y: 2013, via: "In Flames" },
  { name: "Dimension Zero", genre: "Melodic Death (SE)", desc: "Proyecto de Jesper Strömblad (cerebro melódico del In Flames clásico): melodeath agresivo y veloz, puro Gotemburgo. Para el lado Jester Race/Colony. Silent Night Fever.", origin: "rec", pick: true, p: 3, y: 1995, via: "In Flames" },
  { name: "Norther", genre: "Melodic Death (FI)", desc: "Melodeath con teclados y shred neoclásico, melódico y enérgico, veta Children of Bodom. Mirror of Madness.", origin: "rec", pick: true, p: 3, y: 1996, via: "In Flames" },
  { name: "Frantic Amber", genre: "Melodic Death (SE)", desc: "Melodeath de Gotemburgo liderado por mujeres (Elizabeth Andrews), agresivo y melódico con buenas guitarras. Bellatrix.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "In Flames" },
  { name: "Mercenary", genre: "Melodic Death / Power (DK)", desc: "Melodeath cruzado con power, muchísima melodía vocal limpia y guitarras épicas. The Hours That Remain.", origin: "rec", pick: true, p: 3, y: 1991, via: "In Flames" },

  // ----- SIAMES (cierre del repaso + barrido latino/atmosférico) -----
  { name: "Usted Señálemelo", genre: "Alt Rock (AR)", desc: "Compatriotas de Siames: trío de alt/prog ecléctico y técnico, atmosférico y experimental, que cambia mucho entre discos. De lo más interesante del rock argentino actual. [Cat 1]", p: 2, origin: "rec", pick: true, y: 2012, via: "Siames", c: 1 },
  { name: "Beach House", genre: "Dream Pop", desc: "Dream pop atmosférico y lujoso con Victoria Legrand: capas de teclados, guitarras envolventes y melancolía cinematográfica. Teen Dream, Bloom.", p: 3, origin: "rec", pick: true, female: true, y: 2004, via: "Siames" },
  { name: "Hello Seahorse!", genre: "Alt Rock (MX)", desc: "Alt rock atmosférico y ecléctico con Lo Blondo, melódico y con texturas interesantes. Conexión latina. Bestia.", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Siames" },
  { name: "DIIV", genre: "Dream Pop / Shoegaze", desc: "Dream pop/shoegaze con guitarras entrelazadas e hipnóticas, atmosférico y melancólico. Oshin, Deceiver.", p: 3, origin: "rec", pick: true, y: 2011, via: "Siames" },
  { name: "Bándalos Chinos", genre: "Indie Pop/Rock (AR)", desc: "Indie pop/rock sofisticado y groovy, producción cuidada y melodías brillantes. Otra joya argentina. Bach.", origin: "rec", pick: true, p: 3, y: 2009, via: "Siames" },
  { name: "Rhye", genre: "Atmospheric Soul / Indie", desc: "Soul atmosférico y sensual, sofisticado y minimalista pero con arreglos elegantes. Para el lado nocturno. Woman, Blood.", origin: "rec", pick: true, p: 3, y: 2012, via: "Siames" },
  { name: "Wild Beasts", genre: "Art Rock (UK)", desc: "Art rock con falsete distintivo, guitarras angulares e intrincadas y atmósfera sensual-oscura. Smother, Two Dancers.", origin: "rec", pick: true, p: 2, y: 2004, via: "Siames" },
  { name: "Mitski", genre: "Indie Rock", desc: "Indie rock intrincado, imprevisible y devastador, de lo íntimo a lo explosivo con arreglos creativos. Be the Cowboy, Puberty 2.", p: 3, origin: "rec", pick: true, female: true, y: 2012, via: "Siames" },
  { name: "Diamante Eléctrico", genre: "Alt / Blues Rock (CO)", desc: "Colombianos: alt y blues rock con groove, riffs sucios y atmósfera, con la voz rasgada de Juan Galeano y una producción que deja mucho aire. Ganadores de varios Latin Grammy. Entrada: Buitres.", origin: "rec", pick: true, female: true, p: 2, y: 2012, via: "Siames" }
];

// ===========================================================================
// === TANDA 4 (junio 2026) — Iron Maiden + Dethklok + Death metal (anti-CC)
// + 1ª vuelta de Siames que faltaba. Campos nuevos: p (prioridad 1-4),
// y (año formación/estreno), via (rama de origen de la recomendación).
// ===========================================================================
const TANDA_4 = [
  // ----- IRON MAIDEN (bajo líder / épico-narrativo / prog) -----
  { name: "Thin Lizzy", genre: "Hard Rock (IE)", y: 1969, p: 1, via: "Iron Maiden", desc: "Phil Lynott canta y toca el bajo a la vez, con líneas melódicas que se mueven contra la voz en vez de sostenerla, y las dos guitarras tocan armonizadas en terceras como una sola voz doble. Jailbreak, Johnny the Fox y Black Rose sostienen esa escritura. Entrada: Jailbreak.", origin: "rec", pick: true },
  { name: "Voivod", genre: "Prog / Avant Metal (CA)", y: 1982, p: 1, via: "Iron Maiden", desc: "[Comodín] Cada era es otro planeta (thrash → prog espacial → art metal) Y sonido absolutamente singular: acordes disonantes y bajo protagonista. Dimension Hatröss, Nothingface.", origin: "rec", pick: true, c: 3 },
  { name: "Atheist", genre: "Tech Death / Jazz Fusion", y: 1987, p: 1, via: "Iron Maiden", desc: "[Comodín] Genuinamente singular: death técnico + fusión jazz con el bajo fretless como co-líder (líneas de Roger Patterson, grabadas por Tony Choy). Unquestionable Presence.", origin: "rec", pick: true, c: 3 },
  { name: "Primus", genre: "Funk Metal / Experimental", y: 1984, p: 1, via: "Iron Maiden", desc: "[Comodín] Les Claypool toca el bajo como instrumento líder, con slap, tapping y armónicos llevando el tema entero mientras la guitarra hace de textura y la batería va contra el bajo en vez de con él. Frizzle Fry, Sailing the Seas of Cheese y Pork Soda sostienen ese reparto invertido. Entrada: Sailing the Seas of Cheese.", origin: "rec", pick: true, c: 3 },
  { name: "Diamond Head", genre: "NWOBHM (UK)", y: 1976, p: 2, via: "Iron Maiden", desc: "NWOBHM ambicioso y riff-driven (Metallica les debe media carrera), con más experimentación de la que cuentan. Lightning to the Nations.", origin: "rec", pick: true },
  { name: "Satan", genre: "NWOBHM (UK)", y: 1980, p: 2, via: "Iron Maiden", desc: "NWOBHM técnico y melódico con gemelas intrincadas, sofisticado e infravalorado; de regreso con discos excelentes. Court in the Act, Cruel Magic.", origin: "rec", pick: true },
  { name: "Cirith Ungol", genre: "Epic Heavy / Doom", y: 1972, p: 3, via: "Iron Maiden", desc: "Epic heavy/doom de culto con identidad inconfundible (voz rasgada singular); regresaron con discos aclamados. King of the Dead, Forever Black.", origin: "rec", pick: true },
  { name: "Slough Feg", genre: "Celtic Heavy Metal", y: 1990, p: 2, via: "Iron Maiden", desc: "'Maiden con Di'Anno + folk celta y Thin Lizzy': melódico, único y con galope. Forefather del NWOTHM. Traveller, Hardworlder.", origin: "rec", pick: true },
  { name: "Atlantean Kodex", genre: "Epic Heavy Metal (DE)", y: 2005, p: 2, via: "Iron Maiden", desc: "Epic metal monumental y atmosférico, narrativo y grandioso — himnos de civilizaciones. The White Goddess; nuevo disco anunciado (The Course of Empire).", origin: "rec", pick: true },
  { name: "Visigoth", genre: "Epic Heavy Metal", y: 2010, p: 2, via: "Iron Maiden", desc: "Estandarte del epic metal moderno: melódico, épico y con pegada. Conqueror's Oath.", origin: "rec", pick: true },
  { name: "Eternal Champion", genre: "Epic Heavy Metal", y: 2012, p: 2, via: "Iron Maiden", desc: "El otro estandarte moderno del epic metal (espada y brujería). Ravening Iron; EP nuevo 2026 y tercer disco en camino.", origin: "rec", pick: true },
  { name: "Nevermore", genre: "Prog / Power Metal", y: 1992, p: 2, via: "Iron Maiden", desc: "Prog/power oscuro y sofisticado con Warrel Dane (voz dramática única) y Jeff Loomis a la guitarra. Dead Heart in a Dead World.", origin: "rec", pick: true },
  { name: "Crimson Glory", genre: "Prog Metal", y: 1982, p: 2, via: "Iron Maiden", desc: "Prog metal melódico con voz altísima y aires Maiden. Transcendence.", origin: "rec", pick: true },
  { name: "Khemmis", genre: "Doom / Heavy Metal", y: 2012, p: 3, via: "Iron Maiden", desc: "Doom/heavy melódico con guitarras gemelas preciosas y emotividad. Hunted, Deceiver.", origin: "rec", pick: true },
  { name: "Unto Others", genre: "Gothic Heavy Metal", y: 2017, p: 2, via: "Iron Maiden", desc: "Heavy melódico con tinte gótico que evoluciona disco a disco (ex-Idle Hands). Strength.", origin: "rec", pick: true },
  { name: "Sadus", genre: "Technical Thrash", y: 1984, p: 2, via: "Iron Maiden", desc: "Thrash con el bajo fretless de Steve DiGiorgio al frente, melódico y vertiginoso. Swallowed in Black.", origin: "rec", pick: true },
  { name: "Smoulder", genre: "Epic Doom Metal (CA)", y: 2013, p: 3, via: "Iron Maiden", desc: "Epic doom/heavy de espada-y-brujería con Sarah Ann al frente, atmosférico y grandilocuente. Violent Creed of Vengeance.", origin: "rec", pick: true, female: true },
  { name: "In Solitude", genre: "Heavy / Gothic Metal (SE)", y: 2002, p: 2, via: "Iron Maiden", desc: "De culto a Mercyful Fate a un heavy oscuro con post-punk gótico (Sister). Evolución real y atmósfera propia.", origin: "rec", pick: true, c: 1 },

  // ----- DETHKLOK (melodeath técnico-melódico / batería monstruosa) -----
  { name: "Brendon Small's Galaktikon", genre: "Melodic Death / Prog", y: 2012, p: 2, via: "Dethklok", desc: "El mismo cerebro (Brendon Small) + Gene Hoglan, como ópera espacial: más melódico y progresivo, sin la caricatura. 'Dethklok desatado'. Galaktikon I y II.", origin: "rec", pick: true },
  { name: "The Black Dahlia Murder", genre: "Melodic Death", y: 2001, p: 2, via: "Dethklok", desc: "Melodeath enérgico, brutal pero melódico y con riffs memorables. Siguen fuertes tras la muerte de Trevor Strnad. Nocturnal, Servitude (2024).", origin: "rec", pick: true },
  { name: "Inferi", genre: "Technical Melodic Death", y: 2006, p: 2, via: "Dethklok", desc: "Casi un alma gemela de Dethklok: tech death melódico, épico, teatral y pegadizo, con shred neoclásico. Revenant.", origin: "rec", pick: true },
  { name: "Arsis", genre: "Technical Melodic Death", y: 2000, p: 2, via: "Dethklok", desc: "Death melódico y técnico con leads neoclásicos vertiginosos, y la escritura de guitarra de James Malone en el debut es densa y melódica a la vez. Pero la carrera no lo sostiene: A Celebration of Guilt (2004) tuvo elogio casi unánime y lo que vino después se recibió bastante peor, con Starve for the Devil descrito como más simple que lo anterior. Entra por A Celebration of Guilt.", origin: "rec", pick: true },
  { name: "Aenimus", genre: "Prog / Tech Death", y: 2009, p: 2, via: "Dethklok", desc: "Prog/tech death sinfónico y conceptual, melódico y muy técnico. Dreamcatcher.", origin: "rec", pick: true },
  { name: "Equipoise", genre: "Neoclassical Tech Death", y: 2016, p: 2, via: "Dethklok", desc: "Supergrupo de tech death neoclásico/flamenco (Phil Tougas): shred melódico exquisito. Demiurgus.", origin: "rec", pick: true },
  { name: "Gloryhammer", genre: "Symphonic Power Metal", y: 2010, p: 3, via: "Dethklok", desc: "Power metal cómico-épico de fantasía (magos, batallas cósmicas) pero técnicamente impecable. El paralelo 'comedia + música en serio'. Return to the Kingdom of Fife (2023).", origin: "rec", pick: true },
  { name: "Powerglove", genre: "Instrumental / VGM Metal", y: 2005, p: 3, via: "Dethklok", desc: "Metal instrumental de música de videojuegos, técnico y juguetón.", origin: "rec", pick: true },
  { name: "Aether Realm", genre: "Melodic Death / Folk", y: 2011, p: 2, via: "Dethklok", desc: "Melodeath/folk con rango real (de lo épico-serio a lo cómico) e identidad propia: el cruce Cat1/Cat2 de verdad. Tarot.", origin: "rec", pick: true },

  // ----- DEATH METAL (el anti-Cannibal Corpse: claridad, sustancia, evolución) -----
  { name: "Blood Incantation", genre: "Progressive Death Metal", y: 2011, p: 1, via: "Death metal", desc: "Piezas de veinte minutos construidas por secciones que no vuelven, con la produccion abierta a proposito para que se distinga cada capa. Absolute Elsewhere (2024) integra sintetizador analogico como instrumento estructural y no como ambientacion. Entrada: Hidden History of the Human Race.", origin: "rec", pick: true, c: 1 },
  { name: "Bolt Thrower", genre: "Death Metal (UK)", desc: "Riffs a medio tiempo muy graves sobre doble bombo sencillo, melodías de guitarra cortas y efectivas, y un peso enorme sostenido sin cambiar de marcha. Hacían una sola cosa a propósito y la hacían muy bien, pero de complejidad instrumental hay poca. Entra por Those Once Loyal.", origin: "rec", p: 3, y: 1986, c: 2 },
  { name: "Pestilence", genre: "Death / Jazz Fusion (NL)", y: 1986, p: 2, via: "Death metal", desc: "Evolucionaron de thrash-death a death con fusión jazz: en Spheres meten sintetizador de guitarra y bajo fretless, con armonía que se sale del género por completo. Reinvención total en cuatro discos. Entrada: Spheres o Testimony of the Ancients.", origin: "rec", pick: true, c: 1 },
  { name: "Entombed", genre: "Death / Death'n'Roll (SE)", y: 1987, p: 2, via: "Death metal", desc: "Inventaron el sonido 'buzzsaw' sueco y luego pivotearon al death'n'roll (Wolverine Blues): cambio de género real. Left Hand Path.", origin: "rec", pick: true, c: 1 },
  { name: "Tomb Mold", genre: "Progressive Death (CA)", y: 2016, p: 2, via: "Death metal", desc: "De OSDM a death progresivo, atmosférico y jazzy sin perder la aventura. The Enduring Spirit (2023).", origin: "rec", pick: true, c: 1 },
  { name: "Horrendous", genre: "Progressive Death Metal", y: 2009, p: 2, via: "Death metal", desc: "Death moderno con melodía, progresión y composición excelente, todo limpísimo; cada disco crece. Ontological Mysterium (2023).", origin: "rec", pick: true },
  { name: "Sweven (Morbus Chron)", genre: "Progressive Death (SE)", y: 2007, p: 2, via: "Death metal", desc: "De OSDM a death progresivo/psicodélico atmosférico y bello. Sweven (Morbus Chron) y su continuación como Sweven.", origin: "rec", pick: true, c: 1 },
  { name: "Autopsy", genre: "Death / Doom Metal", y: 1987, p: 2, via: "Death metal", desc: "Death/doom sucio pero con muchísimo carácter y composición rara-memorable (Chris Reifert, baterista-vocalista). Mental Funeral.", origin: "rec", pick: true },
  { name: "Asphyx", genre: "Death / Doom (NL)", y: 1987, p: 2, via: "Death metal", desc: "Death/doom demoledor pero con riffs memorables y la voz inconfundible de Martin van Drunen. Pesadez CON identidad. The Rack.", origin: "rec", pick: true },
  { name: "Defeated Sanity", genre: "Brutal Tech Death (DE)", y: 1994, p: 3, via: "Death metal", desc: "Brutal death PERO con jazz/fusión y musicalidad real que sí puedes apreciar (batería técnica espectacular). Tu 'brutal con sustancia'.", origin: "rec", pick: true },
  { name: "Artificial Brain", genre: "Dissonant Tech Death", y: 2011, p: 2, via: "Death metal", desc: "Death técnico disonante, atmosférico y cósmico, con craft claro. Labyrinth Constellation.", origin: "rec", pick: true },
  { name: "Demilich", genre: "Avant Death Metal (FI)", y: 1990, p: 2, via: "Death metal", desc: "[Comodín] Genuinamente singular: death de otro planeta (voz gutural imposible, riffing no convencional). Nespithe — nada suena como esto.", origin: "rec", pick: true, c: 3 },
  { name: "StarGazer", genre: "Avant Death / Black (AU)", y: 1997, p: 3, via: "Death metal", desc: "Death/black avant australiano donde el bajo lleva la voz principal con fraseo jazzístico y sonido limpio, no distorsionado, sobre estructuras que no se repiten y batería de aire progresivo. Entrada: A Great Work of Ages.", origin: "rec", pick: true, c: 3 },

  // ----- SIAMES 1ª vuelta (atmosférico/moody, electrónica bien integrada) -----
  { name: "M83", genre: "Electronic / Shoegaze (FR)", y: 2001, p: 2, via: "Siames", desc: "Rock atmosférico/shoegaze que mutó a lo anthemic-electrónico cinematográfico. Electrónica al servicio de la emoción, nunca EDM gratuito. Hurry Up, We're Dreaming.", origin: "rec", pick: true, c: 1 },
  { name: "The Neighbourhood", genre: "Alt Rock / Moody", y: 2011, p: 2, via: "Siames", desc: "Lo más cercano a la vibra Siames: alt rock oscuro, moody y atmosférico con toques de R&B y electrónica. I Love You., Wiped Out!", origin: "rec", pick: true },
  { name: "Half Moon Run", genre: "Indie Rock (CA)", y: 2010, p: 2, via: "Siames", desc: "Indie atmosférico con arreglos intrincados, armonías vocales y detalle rítmico-instrumental. Dark Eyes.", origin: "rec", pick: true },
  { name: "Daughter", genre: "Indie / Atmospheric (UK)", y: 2010, p: 2, via: "Siames", desc: "Indie atmosférico y emotivo, guitarras texturadas que construyen y voz frágil cinematográfica. If You Leave.", origin: "rec", pick: true, female: true },
  { name: "London Grammar", genre: "Atmospheric Pop (UK)", y: 2012, p: 2, via: "Siames", desc: "Producción minimalista de verdad: dejan huecos enormes entre los elementos, con guitarra tratada, sintetizador de una sola nota sostenida y percusión mínima, para que la voz de contralto de Hannah Reid ocupe todo el espacio. Es atmósfera y contención, no complejidad. Entrada: If You Wait.", origin: "rec", pick: true, female: true },
  { name: "Men I Trust", genre: "Dream Pop / Indie (CA)", y: 2014, p: 2, via: "Siames", desc: "Dream pop con acordes jazzy, bajo groovy y atmósfera nocturna. Instrumentalmente más interesante de lo que parece. Oncle Jazz.", origin: "rec", pick: true, female: true },
  { name: "Crumb", genre: "Psych Indie / Jazz", y: 2016, p: 3, via: "Siames", desc: "Indie psicodélico con jazz y atmósfera densa y onírica, instrumentales hipnóticas y raras. Jinx.", origin: "rec", pick: true, female: true },
  { name: "The Marías", genre: "Dream Pop / Psych Soul", y: 2016, p: 2, via: "Siames", desc: "Dream pop/psych soul atmosférico y sensual, bilingüe (EN/ES), cinematográfico y de arreglos exquisitos. Cinema, Submarine.", origin: "rec", pick: true, female: true },
  { name: "Khruangbin", genre: "Psych Funk / Instrumental", y: 2010, p: 3, via: "Siames", desc: "Trío psych-funk atmosférico, groovy y global (influencias tailandesas, dub, soul), casi todo instrumental. Con Todo el Mundo.", origin: "rec", pick: true },
  { name: "Sir Sly", genre: "Alt / Electronic Rock", y: 2012, p: 3, via: "Siames", desc: "Alt rock electrónico oscuro y melancólico, con la voz muy procesada y bases de sintetizador amplias. Formato canción de radio. Entrada: Don't You Worry, Honey.", origin: "rec", pick: true },
  { name: "Joywave", genre: "Indie Electronic Rock", y: 2010, p: 3, via: "Siames", desc: "Indie electrónico/alt rock atmosférico y un poco sarcástico, con buena producción y texturas. Content.", origin: "rec", pick: true },
  { name: "Metronomy", genre: "Indie Electronic (UK)", y: 1999, p: 3, via: "Siames", desc: "Indie electrónico ecléctico que se reinventa entre discos, con groove raro y producción ingeniosa. The English Riviera.", origin: "rec", pick: true, c: 1 },
  { name: "El Mató a un Policía Motorizado", genre: "Indie / Noise Pop (AR)", y: 2003, p: 3, via: "Siames", desc: "Indie/noise pop argentino, atmosférico y melódico. Conexión latina con Siames. La Síntesis O'Konor.", origin: "rec", pick: true }
];

// ===========================================================================
// === REPASO 2026 — auditoría de huecos (10 tandas) =========================
// Ancestros que faltaban, géneros coloreados sin sus fundadores, y el sesgo
// anti-Cannibal Corpse corregido. Categoría verificada con test estricto de
// comodín: (A) Cat1 Y Cat2 a la vez, o (B) la música misma no tiene par.
// ===========================================================================
const REPASO_2026 = [
  // ----- RAÍCES PERDIDAS / ART ROCK -----
  { name: "Björk", genre: "Art Pop / Experimental", y: 1993, p: 1, c: 1, female: true, via: "Art rock", desc: "Cada disco monta un sistema instrumental distinto y compone dentro de él: Homogenic son cuerdas contra beats rotos, Vespertine microbeats y arpa, Utopia un banco de flautas. Y la voz va escrita como línea melódica compleja, no como recitado encima. Entrada: Homogenic.", origin: "rec", pick: true },
  { name: "Talking Heads", genre: "Art Rock / Post-Punk", y: 1975, p: 1, c: 1, via: "Art rock", desc: "De post-punk esquelético a orquesta polirrítmica en cuatro años. Remain in Light está construido al revés de lo normal: cada músico toca una sola figura corta que se repite sin variar, y la pieza surge de superponerlas hasta que se desfasan entre sí, con Chris Frantz y Tina Weymouth sosteniendo un groove afrobeat inalterable mientras Adrian Belew mete guitarra tratada por encima. Byrne canta como si declamara. Entrada: Remain in Light.", origin: "rec", pick: true },
  { name: "Peter Gabriel", genre: "Art Rock / Prog", y: 1977, p: 2, c: 1, via: "Art rock", desc: "Tienes Genesis pero no su solista, que es donde se puso raro. En el III le prohibio los platillos a Phil Collins y de ahi nacio el gated drum; el IV es Fairlight y polirritmia africana. Entrada: III (Melt).", origin: "rec", pick: true },
  { name: "Tom Waits", genre: "Experimental / Art Rock", y: 1973, p: 2, c: 1, via: "Art rock", desc: "De crooner de jazz a percusion de chatarreria: grabo con sillas, frenos de tren y objetos metalicos, con la guitarra de Marc Ribot. ADN con Scott Walker y Dresden Dolls. Entrada: Rain Dogs.", origin: "rec", pick: true },
  { name: "Deep Purple", genre: "Hard Rock (clásico)", y: 1968, p: 1, via: "Raíces perdidas", desc: "Jon Lord toca el órgano Hammond a través de amplificadores Marshall y con distorsión, así que compite con la guitarra en volumen y timbre en lugar de acompañar, y él y Blackmore se turnan solos largos improvisados en directo como si fuera un duelo de jazz. Ian Paice a la batería toca con mano izquierda rapidísima y swing, no a golpe recto. Entrada: Machine Head, y Made in Japan para los duelos.", origin: "rec", pick: true },
  { name: "Portishead", genre: "Trip-Hop / Experimental", y: 1991, p: 2, c: 1, female: true, via: "Art rock", desc: "Hicieron trip-hop, desaparecieron once anos y volvieron con Third: krautrock motorik y sintetizadores abrasivos. Beth Gibbons como voz dominante sobre algo mucho mas hostil. Entrada: Third.", origin: "rec", pick: true },
  { name: "Brian Eno", genre: "Ambient / Art Rock", desc: "En los discos de canción como Another Green World alterna piezas cortas de rock angular con miniaturas instrumentales tratadas hasta que el instrumento original no se reconoce, y en los ambientales monta bucles de cinta de duraciones distintas que se desfasan entre sí, de modo que la combinación tarda horas en repetirse y la pieza nunca suena igual dos veces. Esa idea del desfase sostiene toda su obra, de Here Come the Warm Jets a Music for Airports a los discos generativos recientes. Entra por Another Green World o Music for Airports.", origin: "rec", p: 1, y: 1971, c: 1 },
  { name: "Massive Attack", genre: "Trip-Hop / Electronic", y: 1988, p: 2, via: "Art rock", desc: "Mezzanine: el bajo dub como cimiento de todo, claustrofobico y oscuro. Prometieron material nuevo para 2026, fisico y digital pero fuera de Spotify. Entrada: Mezzanine.", origin: "rec", pick: true },
  { name: "Arca", genre: "Experimental / Electronic", y: 2012, p: 2, c: 1, female: true, via: "Art rock", desc: "Cada disco es otro sistema: la serie KiCk fragmenta reggaeton, opera y club deconstruido sin metrica estable. Electronica que si pasa tu filtro. Entrada: KiCk i.", origin: "rec", pick: true },
  { name: "SOPHIE", genre: "Experimental / Electronic", y: 2013, p: 2, c: 1, female: true, via: "Art rock", desc: "Invento un lenguaje entero de diseno sonoro: en vez de samples, sintetizaba texturas fisicas (metal golpeado, plastico, burbujas) desde cero. Murio en 2021. Entrada: Oil of Every Pearl's Un-Insides.", origin: "rec", pick: true },
  { name: "Captain Beefheart", genre: "Avant-garde / Experimental", y: 1964, p: 1, c: 3, via: "Art rock", desc: "[Comodín] Trout Mask Replica: cada instrumento toca en un compas y una tonalidad distintos a la vez, ensayado ocho meses hasta poder ejecutarlo. Es el ancestro directo de Mr. Bungle, Cardiacs y Zappa, que ya tienes. Entrada: Trout Mask Replica.", origin: "rec", pick: true },
  { name: "Dead Can Dance", genre: "Art Pop / Ethereal / Gothic", desc: "[Comodín] Piezas lentas y modales sobre instrumentación medieval, bizantina y del norte de África, construidas por repetición y drone, con la voz flotando encima. Muy bello y muy hipnótico, pero armónicamente estático y sin apenas desarrollo ni cambios de estructura. Es atmósfera, no complejidad, así que por tu filtro se queda en más adelante. Mantiene el comodín porque el mundo sonoro no tiene par. Entra por Within the Realm of a Dying Sun.", origin: "rec", p: 3, y: 1981, c: 3 },
  { name: "The Residents", genre: "Avant-garde / Experimental", desc: "[Comodín] Deconstruyen la canción popular americana dejándola deliberadamente tosca y desafinada, con electrónica primitiva, melodías de canción infantil retorcidas y voces procesadas hasta lo desagradable. Es incómodo a propósito y estructuralmente simple, por eso se queda abajo pese a que no exista nada igual. El anonimato de más de cincuenta años es una anécdota, no una razón de tier. Entra por Eskimo.", origin: "rec", p: 3, y: 1969, c: 3 },

  // ----- CANTERBURY / RIO / ZEUHL -----
  { name: "Soft Machine", genre: "Prog Rock / Jazz Fusion", y: 1966, p: 1, c: 1, via: "Canterbury/RIO", desc: "Mutacion brutal en cuatro anos: de pop psicodelico a suites de jazz-rock (Third son cuatro caras, una sola pieza cada una) a fusion instrumental pura. Robert Wyatt era el baterista Y el cantante. Sacaron Thirteen en marzo de 2026. Entrada: Third.", origin: "rec", pick: true },
  { name: "Gong", genre: "Prog Rock / Psychedelic", y: 1967, p: 2, c: 1, via: "Canterbury/RIO", desc: "De la trilogia Radio Gnome (space-whimsy psicodelico) a Pierre Moerlen's Gong, que era otra banda: fusion liderada por vibrafono y percusion. Pocas discografias se parten tan en dos. Entrada: Angel's Egg, luego Gazeuse!", origin: "rec", pick: true },
  { name: "Robert Wyatt", genre: "Art Rock / Prog", y: 1970, p: 2, c: 1, via: "Canterbury/RIO", desc: "El baterista de Soft Machine quedo paraplejico en 1973 y se reinvento como compositor singular. Rock Bottom es fragil, extrano y hermoso, con Fred Frith y trompeta free. Entrada: Rock Bottom.", origin: "rec", pick: true },
  { name: "Hatfield and the North", genre: "Prog Rock (Canterbury)", y: 1972, p: 2, via: "Canterbury/RIO", desc: "El corazon calido del Canterbury: Pip Pyle (bateria), Richard Sinclair (bajo y voz), Dave Stewart (teclados). Complejidad con humor, y las Northettes usadas como textura instrumental. Entrada: The Rotters' Club.", origin: "rec", pick: true },
  { name: "National Health", genre: "Prog Rock (Canterbury)", y: 1975, p: 2, via: "Canterbury/RIO", desc: "El mismo Dave Stewart en modo compositor de camara: casi todo instrumental, escritura densa y sin concesiones. Es el Canterbury mas cercano al prog metal antes de que existiera. Entrada: Of Queues and Cures.", origin: "rec", pick: true },
  { name: "Henry Cow", genre: "Avant-garde / Experimental", y: 1968, p: 1, via: "Canterbury/RIO", desc: "Avant-prog cruzado con música de cámara y free jazz: partes escritas nota a nota que se abren de golpe a improvisación colectiva, con la guitarra preparada de Fred Frith y compases que no se asientan nunca. Sus discos de estudio funcionan todos igual. Entrada: In Praise of Learning.", origin: "rec", pick: true , c: 2 },
  { name: "Univers Zero", genre: "Avant-garde / Chamber Rock", y: 1974, p: 1, via: "Canterbury/RIO", desc: "Musica de camara del infierno: fagot, armonio, violin y bateria tocando algo que suena a requiem gotico. Lo fundo y lo lidera un baterista (Daniel Denis), de ahi que el pulso mande sobre todo. Entrada: Heresie.", origin: "rec", pick: true , c: 2 },
  { name: "Present", genre: "Avant-garde / Chamber Rock", y: 1979, p: 2, via: "Canterbury/RIO", desc: "La banda del guitarrista que dejo Univers Zero: mas agresiva, repetitiva e hipnotica. Practicamente math rock en 1980. Entrada: Triskaidekaphobie.", origin: "rec", pick: true },
  { name: "Banco del Mutuo Soccorso", genre: "Prog Rock (IT)", y: 1969, p: 1, via: "Canterbury/RIO", desc: "Dos teclistas a la vez repartiéndose líneas distintas en lugar de doblarse, con Francesco Di Giacomo cantando en registro casi operístico por encima de estructuras que encadenan secciones sin repetirlas. Los tres primeros discos, Banco, Darwin! e Io Sono Nato Libero, mantienen esa densidad. Entrada: Darwin!", origin: "rec", pick: true },
  { name: "Koenjihyakkei", genre: "Avant-garde / Zeuhl (JP)", desc: "[Comodín] Es Magma tocado al doble de velocidad, con temas que cambian de compás cada pocos segundos, líneas de bajo y teclado al unísono en intervalos incómodos, voces femeninas operísticas encima y Yoshida a una batería que no baja el ritmo en veinte minutos. Es de lo más exigente de escuchar de todo el catálogo. The Quietus concluyó que acabó eclipsando a su propia inspiración, que ya tienes arriba. Entra por Angherr Shisspa.", origin: "rec", p: 1, y: 1991, c: 3 },
  { name: "Ruins", genre: "Avant-garde / Zeuhl (JP)", y: 1985, p: 1, c: 3, via: "Canterbury/RIO", desc: "[Comodín] El mismo Yoshida, pero aqui es un duo de solo bajo y bateria tocando zeuhl-punk en idioma inventado. Tus dos instrumentos favoritos sosteniendo una banda entera sin guitarra ni teclados. Entrada: Hyderomastgroningem.", origin: "rec", pick: true },
  { name: "Area", genre: "Avant Prog / Jazz Rock (IT)", desc: "[Comodín] Jazz-rock italiano de los setenta, y de lo más difícil de seguir que hay en el catálogo: modos griegos y balcánicos sobre compases impares que cambian dentro del mismo tema, con secciones de free jazz abiertas donde la banda se suelta y vuelve a encajar. Muy denso y muy político. Encima de eso, Demetrio Stratos usaba la voz como un instrumento más, no como línea melódica: la ciencia le estudió en laboratorio la diplofonía, la triplofonía y hasta cuadrofonía, y llegaba a 7.000 Hz. Murió en 1979. El comodín es por esa voz; el tier es por lo que toca la banda. Entra por Arbeit Macht Frei.", origin: "rec", p: 1, y: 1972, c: 3 },

  // ----- FUSIÓN JAZZ -----
  { name: "Mahavishnu Orchestra", genre: "Jazz Fusion", y: 1971, p: 1, via: "Fusión jazz", desc: "Billy Cobham toca compases imposibles con potencia de rock y no de jazz, y Jan Hammer al teclado y Jerry Goodman al violín se turnan solos con John McLaughlin a velocidad absurda, todo sobre armonía modal india. Los dos discos de la primera formación y Visions of the Emerald Beyond mantienen esa densidad sin repetirse. Entrada: The Inner Mounting Flame.", origin: "rec", pick: true },
  { name: "Weather Report", genre: "Jazz Fusion", y: 1970, p: 1, via: "Fusión jazz", desc: "Jaco Pastorius convirtió el bajo fretless en voz cantante principal, con armónicos y acordes, mientras Zawinul usaba los sintetizadores como sección de vientos. Y el grupo cambió de formato varias veces, de la abstracción de los primeros discos a la escritura densa de Heavy Weather. Entrada: Heavy Weather.", origin: "rec", pick: true },
  { name: "Return to Forever", genre: "Jazz Fusion", y: 1972, p: 1, via: "Fusión jazz", desc: "Stanley Clarke usa el bajo como voz solista con la agilidad de un saxo, y las piezas están escritas con temas que vuelven transformados entre los solos, no como cabeza-solo-cabeza. Romantic Warrior y Where Have I Known You Before mantienen esa escritura. Entrada: Romantic Warrior.", origin: "rec", pick: true },
  { name: "Brand X", genre: "Jazz Fusion", y: 1975, p: 2, via: "Fusión jazz", desc: "El dato que descoloca: Phil Collins tocando fusion de verdad, con Percy Jones al bajo fretless, uno de los grandes ignorados del instrumento (lineas melodicas retorcidas, muy Jaco pero mas raro). Entrada: Moroccan Roll.", origin: "rec", pick: true },
  { name: "Snarky Puppy", genre: "Jazz Fusion / Funk", y: 2004, p: 2, via: "Fusión jazz", desc: "Big band de fusion grabada en vivo en estudio, dirigida por el bajista Michael League. Complejo pero respirable. Entrada: We Like It Here, empezando por Lingus.", origin: "rec", pick: true },
  { name: "Hiatus Kaiyote", genre: "Jazz Funk / Soul", y: 2011, p: 2, female: true, via: "Fusión jazz", desc: "Nai Palm: future soul con desplazamiento ritmico salvaje y armonia retorcida bajo melodias preciosas. ADN directo con Thundercat, que ya tienes. Entrada: Choose Your Weapon.", origin: "rec", pick: true },
  { name: "Jaga Jazzist", genre: "Jazz Fusion / Electronic (NO)", y: 1994, p: 2, via: "Fusión jazz", desc: "Nu-jazz noruego: big band mas post-rock mas electronica bien integrada, justo tu condicion. Capas y capas de arreglo. Entrada: A Livingroom Hush.", origin: "rec", pick: true },
  { name: "DOMi & JD Beck", genre: "Jazz Fusion", y: 2018, p: 2, female: true, via: "Fusión jazz", desc: "Duo de teclados y bateria; JD Beck es un fenomeno generacional del instrumento. Su WHO ASKED? (julio 2026) lo compusieron en Sibelius citando a Stravinsky, Reich, Ravel, Debussy y Bjork, con sinfonietta clasica. Entrada: NOT TiGHT.", origin: "rec", pick: true },
  { name: "Egberto Gismonti", genre: "Jazz / Fusion (BR)", y: 1969, p: 2, c: 1, via: "Fusión jazz", desc: "Brasileno que cruza clasica de conservatorio, jazz y musica indigena amazonica, tocando guitarras de 10 y 12 cuerdas hechas a medida ademas de piano de concierto. Entrada: Danca das Cabecas.", origin: "rec", pick: true },

  // ----- INDUSTRIAL / POST-ROCK -----
  { name: "Talk Talk", genre: "Art Rock / Post-Rock", y: 1981, p: 1, c: 1, via: "Post-rock", desc: "La reinvencion definitiva: de hits de synth-pop a inventar el post-rock. Grabaron Spirit of Eden un ano entero a oscuras con musicos de jazz improvisando, y luego EDITARON ese material hasta volverlo composicion. Entrada: Spirit of Eden.", origin: "rec", pick: true },
  { name: "Swans", genre: "Experimental / Post-Punk", y: 1982, p: 1, c: 1, via: "Industrial", desc: "La sustancia es la construccion por acumulacion: piezas de veinte minutos donde una celula de bajo y bateria se repite hasta que el cambio de un solo elemento reordena la pieza entera, con percusion metalica y guitarras en afinaciones abiertas. Cuarenta anos mutando del no-wave al folk gotico y de ahi a esos discos largos. Birthing (2025) cerro esa era y el directo final sale en octubre de 2026. Entrada: To Be Kind.", origin: "rec", pick: true },
  { name: "Ministry", genre: "Industrial Metal", desc: "Al Jourgensen empezo haciendo synth-pop (un disco del que reniega publicamente), paso por EBM y termino inventando el metal industrial de guitarras. Se acaba: el decimoseptimo disco, Hate To Go (Take Out or Delivery), sale el 30 de octubre de 2026 y es el ultimo; la gira de despedida europea arranca en abril de 2027 con Die Krupps de invitados. Jourgensen: estoy en paz con que se acabo. Entra por The Land of Rape and Honey o Psalm 69.", origin: "rec", p: 2, y: 1981, c: 1 },
  { name: "Godflesh", genre: "Industrial Metal", desc: "Metal industrial con caja de ritmos en lugar de baterista como decisión estética, riffs lentísimos repetidos sin variación y un bajo enorme que lleva la armonía mientras la guitarra hace de bloque. Se está cerrando: Decay, su décimo disco y penúltimo, salió el 25 de septiembre de 2026 en Relapse, y el último se graba a finales de 2026. Ya no habrá directos de Godflesh (Broadrick pasó por cirugía abdominal), aunque Jesu y JK Flesh siguen. Entra por Streetcleaner.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Skinny Puppy", genre: "Industrial / Electronic", desc: "El pulso nunca es del todo mecánico ni del todo humano: cEvin Key toca en directo una percusión armada con batería acústica, bidones y módulos electrónicos, y la superpone a las secuencias. Y usa el sampler como collage narrativo, no como adorno: las voces y los ruidos cuentan algo en vez de rellenar. Cuarenta y un años sosteniendo esa escritura, hasta la gira de despedida de diciembre de 2023. Entra por Too Dark Park o Last Rights.", origin: "rec", p: 1, y: 1982, c: 2 },
  { name: "Einstürzende Neubauten", genre: "Industrial / Experimental", desc: "[Comodín] Percusión de metal golpeado, muelles y tubos, que da timbres que ninguna batería puede dar, y sobre eso la voz hablada de Blixa Bargeld en alemán. Pero por debajo de esos timbres las piezas son dispersas y repetitivas, con silencios largos y poco desarrollo; los discos recientes son incluso tranquilos y con forma de canción. Es arte sonoro más que complejidad compuesta, así que por tu filtro se queda en más adelante. El comodín sí lo mantiene: por singularidad no tiene par. Novedad: Rampen (apm) de abril de 2024 está armado con improvisaciones de su gira de 2022 y lo financiaron sus oyentes; Josefine Lukschy entró al bajo en 2026. Entra por Halber Mensch.", origin: "rec", p: 3, y: 1980, c: 3 },
  { name: "Author & Punisher", genre: "Industrial Doom", origin: "rec", y: 2004, p: 2, c: 2, via: "Industrial", desc: "Doom industrial de una sola persona: tempo lentísimo y aplastante con la percusión rígida como una máquina, sin swing ninguno, y la voz procesada hasta volverse otra capa de la masa. La dinámica va a tirones en vez de fluir, y eso es lo que lo separa del drone. Entrada: Beastland." },
  { name: "Coil", genre: "Industrial / Experimental", desc: "[Comodín] Time Machines son cuatro drones de tonos de sintetizador oscilando en ciclo, una hora entera pensada para alterar la percepción del tiempo de quien escucha. En Musick to Play in the Dark aparecen el Optigan, cajas de ritmo antiguas y síntesis granular muy manipulada de Drew McDowall, y las piezas se sostienen sobre timbre y duración en vez de sobre melodía. Industrial esotérico y ritual, difícil pero de una pieza. Entrada: Musick to Play in the Dark.", origin: "rec", p: 2, y: 1982, c: 3 },
  { name: "Slint", genre: "Post-Rock / Math Rock", y: 1986, p: 2, via: "Post-rock", desc: "Spiderland: inventaron el post-rock y el math rock americano con dinamicas de silencio a violencia y voz hablada. Historicamente fundacional, pero austero y minimo: su gracia esta en la tension, no en la complejidad instrumental. Entrada: Spiderland.", origin: "rec", pick: true },
  { name: "This Heat", genre: "Post-Punk / Experimental", desc: "Piezas que arrancan como post-punk y se desmontan en bucles de cinta, drones de órgano y percusión sola, sin volver nunca al punto de partida, con Charles Hayward tocando la batería como voz principal y no como base. Grabaron manipulando la cinta como instrumento, así que la estructura del tema y el montaje son la misma cosa. Áspero e incómodo, y de 1979. Entra por Deceit.", origin: "rec", p: 1, y: 1976, c: 1 },
  { name: "Tortoise", genre: "Post-Rock / Jazz", y: 1990, p: 2, via: "Post-rock", desc: "Post-rock cruzado con jazz, dub y krautrock: dos bateristas simultaneos, vibrafono, marimba y John McEntire. De lo mas complejo y menos obvio del genero. Entrada: Millions Now Living Will Never Die.", origin: "rec", pick: true },
  { name: "Sigur Rós", genre: "Post-Rock (IS)", desc: "Post-rock lentísimo de crescendo, con guitarra frotada generando un colchón sostenido, falsete muy agudo encima y cuerdas y metales entrando en las cimas. Es de una belleza enorme, pero armónicamente estático y de estructura simple: siempre la misma curva de crecer y estallar. Entra por Ágætis byrjun.", origin: "rec", p: 3, y: 1994, c: 2 },
  { name: "Mogwai", genre: "Post-Rock (UK)", y: 1995, p: 1, via: "Post-rock", desc: "Treinta años y once discos moviéndose de verdad: de la dinámica silencio-a-muro de Young Team a los discos con electrónica y voz procesada, a las bandas sonoras. La constante es que las piezas se construyen por presión acumulada y no por estribillo, casi siempre sin voz. The Bad Fire salió en enero de 2025. Entrada: Young Team.", origin: "rec", pick: true },
  { name: "Mono", genre: "Post-Rock (JP)", y: 1999, p: 2, via: "Post-rock", desc: "Pasaron del post-rock de dinamica suave/muro a composicion orquestal real con secciones de cuerda escritas. Grabaron Snowdrop en septiembre de 2025 en Electrical Audio. Entrada: Hymn to the Immortal Wind.", origin: "rec", pick: true },
  { name: "A Silver Mt. Zion", genre: "Post-Rock / Chamber", y: 1999, p: 2, via: "Post-rock", desc: "La rama de Godspeed You! Black Emperor, que ya tienes, pero con voz humana quebrada, cuerdas y una crudeza emocional que GY!BE nunca permite. Entrada: Horses in the Sky.", origin: "rec", pick: true },
  { name: "Don Caballero", genre: "Math Rock / Instrumental", desc: "Instrumental sin voz, y aquí la batería de Damon Che es el motor compositivo: toca patrones que cambian de métrica bajo riffs de guitarra repetidos, con redobles largos que funcionan como frase melódica, de modo que la tensión viene de la percusión y no de la armonía. Las guitarras trabajan en bucles entrelazados que se desfasan entre sí. Y lo sostienen de For Respect a What Burns Never Returns a American Don, tres discos con la misma lógica y distinto grado de densidad. Entra por What Burns Never Returns.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Fantômas", genre: "Avant-garde Metal", y: 1998, p: 1, c: 3, via: "Art rock", desc: "[Comodín] Patton mas Dave Lombardo (Slayer), Buzz Osborne (Melvins) y Trevor Dunn. Cada disco es otro concepto radical: el debut son vinetas de comic hechas partitura con la voz como instrumento sin letra; Delirium Cordia es una sola pieza de 74 minutos. Entrada: Fantomas (1999).", origin: "rec", pick: true },

  // ----- BLACKGAZE / ATMOSFÉRICO -----
  { name: "Alcest", genre: "Blackgaze / Shoegaze (FR)", desc: "Capas de guitarra con chorus y delay formando un colchón brillante, voz limpia y suave de Neige casi susurrada, y solo a ratos tremolo y blast beats por debajo. Es de las cosas más bellas del metal, pero es paisaje y contraste, no complejidad ni desarrollo estructural. Gira con Mastodon en otoño de 2026. Entra por Écailles de Lune.", origin: "rec", p: 2, y: 2000, c: 2 },
  { name: "Deafheaven", genre: "Blackgaze / Post-Metal", y: 2010, p: 2, c: 1, via: "Blackgaze", desc: "Sunbather, y ademas evolucionan de verdad: Infinite Granite elimino los gritos por completo y en Lonely People with Power (2025) volvieron al peso. ADN con Svalbard y Astronoid. Entrada: Sunbather.", origin: "rec", pick: true },
  { name: "Agalloch", genre: "Atmospheric Black / Folk", y: 1995, p: 1, via: "Blackgaze", desc: "Cinco discos y ninguno flojo, con un arco claro: de la crudeza de Pale Folklore a la construcción larga de The Mantle y Ashes Against the Grain, donde acústicas y eléctricas se alternan dentro del mismo tema y las piezas se desarrollan por dinámica y no metiendo un riff nuevo cada vez. Entrada: The Mantle.", origin: "rec", pick: true },

  // ----- LATINOAMÉRICA -----
  { name: "Luis Alberto Spinetta", genre: "Prog / Art Rock (AR)", y: 1967, p: 1, c: 1, via: "Latinoamérica", desc: "Cada proyecto fue otro planeta: Almendra (psicodelia), Pescado Rabioso (Artaud, pesado), Invisible (jazz-prog oscuro), Spinetta Jade (fusion pura). Armonias de jazz sobre poesia real. Entrada: Artaud.", origin: "rec", pick: true },
  { name: "Charly García", genre: "Prog / Art Rock (AR)", y: 1972, p: 2, c: 1, via: "Latinoamérica", desc: "Sui Generis, luego La Maquina de Hacer Pajaros (prog puro), luego Seru Giran (jazz-rock con Pedro Aznar al bajo, que despues tocaria con Pat Metheny) y despues solista new wave. Entrada: Seru Giran.", origin: "rec", pick: true },
  { name: "Os Mutantes", genre: "Psych Rock / Tropicália (BR)", desc: "Psicodelia brasileña de 1968 que mete bossa nova, orquestación, distorsión y collage de cinta dentro de la misma canción, con armonías vocales a tres voces y cambios de tono bruscos que rompen la canción a mitad y la recomponen en otro estilo. Absurdo a propósito y radical para su año. Su hermano ingeniero les construía efectos que no se vendían, pero eso es cómo lo consiguieron, no por qué está aquí. Entra por Os Mutantes (1968).", origin: "rec", p: 2, y: 1966, c: 1 },
  { name: "Meridian Brothers", genre: "Experimental / Cumbia (CO)", y: 1998, p: 2, c: 1, via: "Latinoamérica", desc: "Eblis Alvarez desarma la cumbia, la salsa y el vallenato y los rearma con electronica lo-fi y absurdismo total. Colombiano y reconocido internacionalmente. Entrada: Guaracha UFO.", origin: "rec", pick: true },
  { name: "Divididos", genre: "Hard Rock / Folk (AR)", y: 1988, p: 2, via: "Latinoamérica", desc: "Power trio argentino: riff pesadisimo con folklore andino integrado de verdad, no de adorno. Sacaron disco nuevo en noviembre de 2025, el primero en 15 anos. Entrada: La Era de la Boludez.", origin: "rec", pick: true },
  { name: "Los Jaivas", genre: "Prog Rock / Folk (CL)", y: 1963, p: 1, via: "Latinoamérica", desc: "Prog andino: charango, zampona y trutruca dentro de estructuras progresivas. Alturas de Machu Picchu (1981) musicaliza el poema de Neruda. Gira de 45 aniversario en 2026-2027. Entrada: Alturas de Machu Picchu.", origin: "rec", pick: true },
  { name: "Fulano", genre: "Jazz Rock / Avant (CL)", y: 1984, p: 2, via: "Latinoamérica", desc: "Jazz-rock avant chileno, instrumental, disonante y politico: practicamente el RIO latinoamericano. Seis discos que los tienen como pilares del jazz-rock del continente. Entrada: Fulano (1987).", origin: "rec", pick: true },
  { name: "Congreso", genre: "Jazz Fusion / Folk (CL)", y: 1969, p: 2, via: "Latinoamérica", desc: "Fusion chilena desde 1969, liderada por un baterista (Sergio Tilo Gonzalez), por eso el pulso manda sobre todo. Jazz, prog y folclor latinoamericano en la misma frase. Entrada: Viaje por la Cresta del Mundo.", origin: "rec", pick: true },
  { name: "Milton Nascimento", genre: "Jazz / MPB (BR)", y: 1967, p: 2, via: "Latinoamérica", desc: "Clube da Esquina: armonia brasilena de una complejidad que desarma y una de las voces mas impresionantes que ha existido. Entrada: Clube da Esquina.", origin: "rec", pick: true },
  { name: "Aterciopelados", genre: "Alt Rock (CO)", y: 1990, p: 2, female: true, via: "Latinoamérica", desc: "Andrea Echeverri. El alt rock colombiano con identidad propia y evolucion real hacia lo electronico y lo folk. Entrada: El Dorado.", origin: "rec", pick: true },
  { name: "Kraken", genre: "Heavy / Prog Metal (CO)", y: 1984, p: 2, via: "Latinoamérica", desc: "El metal colombiano fundacional: Elkin Ramirez cantaba con registro casi operistico sobre heavy/prog con letras poeticas, muy tu vena Queen pesado. Murio en 2017 y la banda sigue con Roxana Restrepo. Entrada: Kraken II.", origin: "rec", pick: true },
  { name: "Triana", genre: "Prog Rock / Flamenco (ES)", y: 1974, p: 2, via: "Latinoamérica", desc: "Prog andaluz: flamenco de verdad (cante jondo, compas) dentro de estructuras de rock progresivo. Fusion real, no decorado turistico. Entrada: El Patio.", origin: "rec", pick: true },
  { name: "Hermeto Pascoal", genre: "Avant-garde Jazz (BR)", desc: "[Comodín] Su concepción armónica propia se estudia académicamente frente a Schoenberg, George Russell y Brubeck, y escribía con un sistema de notación doble para poder anotar armonías y ritmos que la notación normal no recoge, saltándose las armaduras de clave para dejar sitio a la improvisación. El Calendário do Som son 366 piezas, una por cada día del año incluido el bisiesto, escritas en doce meses. Encima de eso, sí, sacaba sonido de teteras, sartenes y del agua de un lago. Murió el 13 de septiembre de 2025 a los 89. Entra por Slaves Mass.", origin: "rec", p: 1, y: 1964, c: 3 },
  { name: "Los Pirañas", genre: "Psych / Instrumental (CO)", y: 2010, p: 2, via: "Latinoamérica", desc: "Trio instrumental colombiano: Eblis Alvarez, Mario Galeano (Frente Cumbiero) y Pedro Ojeda (Romperayo). Guitarra surf-psicodelica retorcida sobre ritmos caribenos y champeta. Entrada: Una Oportunidad mas de triunfar en la vida (2025).", origin: "rec", pick: true },
  { name: "Los Saicos", genre: "Garage / Punk (PE)", y: 1964, p: 3, via: "Latinoamérica", desc: "Peru, 1965: proto-punk una decada antes del punk. Demolicion es un grito distorsionado que no tenia derecho a existir en esa fecha. Su valor es historico mas que compositivo. Entrada: las grabaciones recopiladas.", origin: "rec", pick: true },
  { name: "Santa Sabina", genre: "Gothic / Prog Rock (MX)", y: 1989, p: 2, female: true, via: "Latinoamérica", desc: "Rock gótico-progresivo mexicano con Rita Guerrero, cantante de formación clásica: teatralidad oscura, arreglos con cuerda y estructuras largas, cantado en español. Entrada: Symbolvm.", origin: "rec", pick: true },
  { name: "Caifanes", genre: "Alt Rock (MX)", y: 1987, p: 2, via: "Latinoamérica", desc: "Rock oscuro mexicano con percusion prehispanica integrada de verdad, y la voz de Saul Hernandez. Atmosfera inconfundible. Entrada: El Silencio.", origin: "rec", pick: true },
  { name: "Uchpa", genre: "Hard Rock / Blues (PE)", y: 1993, p: 2, via: "Latinoamérica", desc: "Hard rock y blues cantado integramente en quechua, fusionado con huayno, jarawi y pumpin. El nombre significa cenizas, por lo que quedo tras el conflicto armado peruano; su lider Fredy Ortiz fue policia en esa guerra. Entrada: Qauka Kausay.", origin: "rec", pick: true },
  { name: "Secos & Molhados", genre: "Glam Rock / MPB (BR)", y: 1971, p: 2, via: "Latinoamérica", desc: "Glam teatral de 1973 con maquillaje facial completo y la voz de Ney Matogrosso, un contratenor de registro agudisimo, sobre poesia brasilena musicalizada. Vendieron mas que los Beatles en Brasil ese ano. Entrada: su homonimo de 1973.", origin: "rec", pick: true },

  // ----- ASIA -----
  { name: "Sheena Ringo", genre: "Art Pop / Jazz (JP)", desc: "Escribe y arregla ella los discos, y esos arreglos son de verdad (big band de jazz con sección de metales escrita, orquesta de pop de era Showa, electrónica), con armonía que se sale del pop japonés estándar y una voz que fuerza el timbre a propósito. Matiz: Tokyo Jihen no es su banda de acompañamiento sino un grupo donde los demás también componen. Entra por Kalk Samen Kuri no Hana.", origin: "rec", p: 2, y: 1998, c: 1, female: true },
  { name: "Boredoms", genre: "Noise / Experimental (JP)", y: 1986, p: 2, c: 1, via: "Asia", desc: "Yamantaka Eye llevo la banda del ruido impenetrable a Vision Creation Newsun, trance tribal-psicodelico por repeticion. Y monto 77 Boadrum: 77 bateristas en espiral tocando a la vez. Entrada: Vision Creation Newsun.", origin: "rec", pick: true },
  { name: "Susumu Hirasawa", genre: "Prog / Electronic (JP)", desc: "[Comodín] Suena a prog electrónico hiperactivo: secuencias muy rápidas y capas de coros procesados de su propia voz apiladas hasta formar un muro, todo sobre escalas del sudeste asiático que le dan giros melódicos que no salen del repertorio occidental. Es denso y agotador en el buen sentido, con muy poco aire. Compuso para Satoshi Kon (Paprika) y para Berserk. unZIP (oct 2025) es su primer Kaku P-MODEL en siete años. Entra por Siren.", origin: "rec", p: 2, y: 1979, c: 3 },
  { name: "Yellow Magic Orchestra", genre: "Synth Pop / Electronic (JP)", y: 1978, p: 2, c: 1, via: "Asia", desc: "Sakamoto, Hosono y Takahashi inventaron el technopop trabajando con un secuenciador Roland MC-8 en una época en que había que programar cada nota como datos numéricos, y Takahashi tocaba la batería encima con una precisión mecánica deliberada para casar con la máquina. Armonía de Sakamoto tomada de la clásica y del exotica. Terminaron sampleados por medio hip-hop y por toda la electrónica de Detroit. Entrada: Solid State Survivor.", origin: "rec", pick: true },
  { name: "Ling Tosite Sigure", genre: "Math Rock / Post-Hardcore (JP)", y: 2002, p: 1, female: true, via: "Asia", desc: "Trio de math post-hardcore: TK a la guitarra y falsete desgarrado, 345 al bajo y grito, y Pierre Nakano en una bateria que es de lo mas impresionante del rock moderno, con precision de metronomo dentro del caos. Entrada: just A moment.", origin: "rec", pick: true },
  { name: "Ningen Isu", genre: "Doom / Heavy Metal (JP)", y: 1987, p: 2, via: "Asia", desc: "Devocion a Black Sabbath desde 1987, pero con kimonos, estetica yokai y letras de literatura japonesa (Edogawa Ranpo). Mahoroba (nov 2025) es su disco numero 24. Entrada: Mahoroba.", origin: "rec", pick: true },
  { name: "Silica Gel", genre: "Art Rock / Psych (KR)", y: 2013, p: 2, via: "Asia", desc: "Art rock psicodelico coreano; ganaron Musician of the Year 2024 en los Korean Music Awards. Su tercer disco Ballad of You salio en agosto de 2026. Entrada: Power Andre 99.", origin: "rec", pick: true },
  { name: "Omnipotent Youth Society", genre: "Post-Rock / Folk Rock (CN)", y: 1996, p: 2, via: "Asia", desc: "Post-rock/folk-rock con arreglos de vientos y una densidad compositiva rarisima para el rock chino. Inside the Cable Temple vendio 200.000 copias en medio dia. Doce anos entre discos porque graban hasta quedar conformes. Entrada: el homonimo de 2010.", origin: "rec", pick: true },
  { name: "Chthonic", genre: "Symphonic Black Metal (TW)", y: 1995, p: 2, via: "Asia", desc: "Black metal sinfonico con erhu integrado de verdad y tematica de historia taiwanesa; su vocalista Freddy Lim llego a ser legislador nacional. Entrada: Takasago Army.", origin: "rec", pick: true },
  { name: "Fishmans", genre: "Dub / Psych Pop (JP)", y: 1987, p: 2, via: "Asia", desc: "Dub y psicodelia japonesa: Long Season es una sola pieza de 35 minutos que se despliega sin repetirse. Shinji Sato murio a los 33 y la banda quedo congelada como objeto de culto. Entrada: Long Season.", origin: "rec", pick: true },
  { name: "Senyawa", genre: "Experimental / Folk (ID)", desc: "[Comodín] Dos personas, nada más. Rully Shabara pasa de canto gutural a grito con técnicas vocales extendidas, y Wukir Suryadi hace de base con un instrumento de bambú, piel animal y cuerdas de acero que él mismo construye y que pasa por distorsión. El resultado es ritual, crudo e intensísimo de timbre, pero las piezas son de estructura mínima: una idea que se repite y crece. Impacta más de lo que desarrolla, así que se queda en más adelante. Entra por Alkisah.", origin: "rec", p: 2, y: 2010, c: 3 },
  { name: "Jambinai", genre: "Post-Metal / Folk (KR)", y: 2009, p: 1, via: "Asia", desc: "El geomungo, el haegeum y el piri llevan las líneas principales, no adornan, y eso lo sostienen en toda su discografía: pasan de casi silencio a muros de distorsión manteniendo los instrumentos coreanos al frente, con piezas que crecen por acumulación de capas en vez de volver a un estribillo. Coreanos. Entrada: A Hermitage.", origin: "rec", pick: true },
  { name: "Envy", genre: "Screamo / Post-Rock (JP)", y: 1992, p: 2, via: "Asia", desc: "Screamo cruzado con post-rock: crescendos enormes con spoken word en japones encima. Entrada: A Dead Sinking Story.", origin: "rec", pick: true },
  { name: "Melt-Banana", genre: "Noise / Punk (JP)", y: 1992, p: 2, female: true, via: "Asia", desc: "Noise punk a hipervelocidad: canciones de 30 segundos ejecutadas con precision de reloj suizo, con la voz de Yasuko Onuki usada como instrumento agudo. Entrada: Fetch.", origin: "rec", pick: true },
  { name: "Ichiko Aoba", genre: "Folk / Chamber (JP)", y: 2010, p: 2, female: true, via: "Asia", desc: "Folk de camara de delicadeza extrema pero compositivamente denso: Windswept Adan es un ciclo entero sobre una isla imaginaria. Luminescent Creatures (feb 2025) lo hizo con el pianista Taro Umebayashi dirigiendo un ensamble. Entrada: Windswept Adan.", origin: "rec", pick: true },
  { name: "Acid Mothers Temple", genre: "Psych Rock / Drone (JP)", y: 1995, p: 3, via: "Asia", desc: "Colectivo psicodelico hiperprolifico: drones cosmicos, guitarra de Kawabata Makoto y jams de 20 minutos que se desarman. Entrada: La Novia.", origin: "rec", pick: true },
  { name: "Second Hand Rose", genre: "Folk Rock / Teatral (CN)", y: 1999, p: 3, via: "Asia", desc: "Rock con errenzhuan, la opera folclorica del noreste chino, y un frontman travestido con estetica de teatro popular. Fusion real, no cosmetica. Entrada: su homonimo.", origin: "rec", pick: true },

  // ----- DOOM / GÓTICO -----
  { name: "Ulver", genre: "Experimental / Electronic (NO)", desc: "Conserva la categoría 1 porque la reinvención es de verdad la más extrema de la música pesada (black metal noruego, folk acústico, electrónica, trip-hop, cámara, ambient y synth-pop ochentero), pero eso justifica la categoría, no el tier: reinventarse mucho no es lo mismo que ser complejo. Cómo suenan ahora: sintetizadores cálidos y producción impecable sobre estructuras de canción bastante directas, con la voz de Kristoffer Rygg al frente. Es hermoso y muy bien hecho, no exigente. Neverland (dic 2025) es completamente electrónico. Entra por Bergtatt, luego Perdition City.", origin: "rec", p: 2, y: 1993, c: 1 },
  { name: "Paradise Lost", genre: "Gothic / Death Doom (UK)", desc: "Death/doom a medio tiempo con melodías de guitarra muy cantables y armonías gemelas por encima, y voz que alterna limpio grave y gutural. Es melódico y pesado, pero no busca complejidad rítmica ni estructural. La categoría 1 se queda porque la reinvención sí es real, y de las gordas: inventaron el gothic metal con Gothic (1991), se fueron al synth-pop y el darkwave con Host perdiendo media base de fans, y volvieron al death/doom sin pedir perdón. Ascension salió en 2025. Entra por Gothic.", origin: "rec", p: 2, y: 1988, c: 1 },
  { name: "My Dying Bride", genre: "Death Doom (UK)", desc: "Doom lentísimo con el violín como voz principal y no de adorno, largos desarrollos de diez minutos y la voz desgarrada de Aaron Stainthorpe alternando lamento y gutural. Es de una tristeza enorme y muy bien ejecutado, pero estructuralmente es repetición y crecimiento, no complejidad. A Mortal Binding sale en septiembre de 2026. Entra por Turn Loose the Swans.", origin: "rec", p: 2, y: 1990, c: 2 },
  { name: "Candlemass", genre: "Epic Doom Metal (SE)", desc: "Riffs de Leif Edling lentísimos y enormes, repetidos con muy poca variación para que pesen, con la voz operística de Messiah Marcolin encima como contraste. El efecto depende de la repetición y del volumen, no del desarrollo: es doom épico de manual porque ellos escribieron el manual. Entra por Nightfall.", origin: "rec", p: 2, y: 1984, c: 2 },
  { name: "Theatre of Tragedy", genre: "Gothic / Doom Metal (NO)", y: 1993, p: 3, c: 1, female: true, via: "Doom/Gótico", desc: "Pioneros del dueto bella y bestia (voz femenina limpia contra gutural), que es el molde que usan Draconian y Tristania, ambos ya tuyos. Y despues se fueron a electropop industrial completo con Musique. Entrada: Velvet Darkness They Fear.", origin: "rec", pick: true },
  { name: "Tiamat", genre: "Gothic / Psych Metal (SE)", y: 1987, p: 2, c: 1, via: "Doom/Gótico", desc: "De death metal sueco a rock gotico-psicodelico atmosferico y espacial. Wildhoney es el punto de giro. Entrada: Wildhoney.", origin: "rec", pick: true },
  { name: "Sleep", genre: "Stoner / Doom Metal", y: 1990, p: 2, via: "Doom/Gótico", desc: "Dopesmoker es una sola pieza de 63 minutos; la disquera se lo rechazo por eso y tardo anos en salir. Al Cisneros y Matt Pike se separaron y montaron Om (bajo y bateria, casi ritual) y High on Fire. Entrada: Dopesmoker.", origin: "rec", pick: true },
  { name: "Electric Wizard", genre: "Stoner / Doom Metal (UK)", y: 1993, p: 3, via: "Doom/Gótico", desc: "Dopethrone: la afinacion mas grave y el sonido mas sucio y saturado del doom. No es complejo, es interesante: una identidad sonora que no se confunde con nada. Entrada: Dopethrone.", origin: "rec", pick: true },
  { name: "Saint Vitus", genre: "Doom Metal", y: 1978, p: 3, via: "Doom/Gótico", desc: "Uno de los dos pilares americanos del doom tradicional de los 80, con Wino al frente y una crudeza deliberada. Entrada: Born Too Late.", origin: "rec", pick: true },
  { name: "Trouble", genre: "Psychedelic Doom Metal", y: 1979, p: 3, via: "Doom/Gótico", desc: "El otro pilar americano del doom de los 80, mas melodico y psicodelico que Saint Vitus. Entrada: Psalm 9.", origin: "rec", pick: true },
  { name: "SubRosa", genre: "Doom Metal / Chamber", y: 2005, p: 2, female: true, via: "Doom/Gótico", desc: "Doom con dos violines electricos como instrumentos principales, no de adorno: disonantes, chirriantes, tejiendo las melodias. Textura propia, liderado por mujeres. Entrada: More Constant Than the Gods.", origin: "rec", pick: true },
  { name: "Messa", genre: "Doom Metal / Jazz (IT)", y: 2014, p: 2, female: true, via: "Doom/Gótico", desc: "Doom italiano actual con saxofon, jazz y escalas de Oriente Medio, con la voz de Sara Bianchin encima. De lo mas instrumentalmente inquieto del genero hoy. Entrada: Close.", origin: "rec", pick: true },
  { name: "Warning", genre: "Doom Metal (UK)", y: 1994, p: 2, via: "Doom/Gótico", desc: "Watching from a Distance es de los discos mas devastadores que se han grabado en doom. Patrick Walker convierte la repeticion en duelo. Entrada: Watching from a Distance.", origin: "rec", pick: true },
  { name: "40 Watt Sun", genre: "Doom / Slowcore (UK)", y: 2009, p: 2, via: "Doom/Gótico", desc: "El mismo Patrick Walker despojando el doom hasta casi lo acustico, con canciones larguisimas y desnudas. Entrada: The Inside Room.", origin: "rec", pick: true },
  { name: "Bell Witch", genre: "Funeral Doom Metal", y: 2010, p: 1, c: 3, via: "Doom/Gótico", desc: "[Comodín] Duo de solo bajo y bateria, sin guitarra: Dylan Desmond con un bajo de seis cuerdas cubriendo todo el rango y Jesse Shreibman en bateria y organo de pedal. Mirror Reaper es una sola pieza de 84 minutos, tributo a su baterista fallecido. Entrada: Mirror Reaper.", origin: "rec", pick: true },
  { name: "Ahab", genre: "Funeral Doom Metal (DE)", y: 2004, p: 2, via: "Doom/Gótico", desc: "Funeral doom nautico: discos conceptuales completos basados en Moby-Dick, y luego en Poe y Verne. Lento, inmenso y literario. Entrada: The Call of the Wretched Sea.", origin: "rec", pick: true },
  { name: "Skepticism", genre: "Funeral Doom Metal (FI)", y: 1991, p: 2, via: "Doom/Gótico", desc: "Funeral doom finlandes con organo de iglesia como instrumento principal, a velocidad de procesion. Se presentan vestidos de luto riguroso y fundaron el genero. Entrada: Stormcrowfleet.", origin: "rec", pick: true },
  { name: "Virgin Black", genre: "Gothic Doom Metal (AU)", y: 1995, p: 2, via: "Doom/Gótico", desc: "Gothic doom australiano con orquesta y coro reales: su trilogia Requiem esta compuesta con estructura de misa de requiem de verdad. Teatral y operistico al extremo. Entrada: Requiem - Mezzo Forte.", origin: "rec", pick: true },
  { name: "Esoteric", genre: "Funeral Doom Metal (UK)", y: 1992, p: 2, via: "Doom/Gótico", desc: "Funeral doom psicodelico britanico: piezas de 20 a 30 minutos con capas de guitarra procesada que se deshacen. Denso texturalmente, no solo lento. Entrada: The Maniacal Vale.", origin: "rec", pick: true },

  // ----- HIP-HOP / JAZZ MODERNO -----
  { name: "Outkast", genre: "Hip-Hop / Funk", y: 1992, p: 1, c: 1, via: "Hip-hop/Jazz", desc: "Del rap sureño al funk psicodélico con instrumentación en vivo, y cada disco cambia de sistema: ATLiens es espacial y mínimo, Aquemini mete banda tocando, Stankonia acelera hasta rozar el drum and bass, y Speakerboxxx/The Love Below es un doble donde cada mitad es un disco solista distinto. André 3000 abandonó el rap y hoy saca discos de flauta. Entrada: Aquemini.", origin: "rec", pick: true },
  { name: "Flying Lotus", genre: "Experimental Hip-Hop / Jazz", y: 2006, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "Sobrino-nieto de Alice Coltrane. Del beat-tape al jazz-fusion con banda real (You're Dead!, con Herbie Hancock). Y es quien produjo y lanzo a Thundercat, que ya tienes: el ADN es directisimo. Entrada: Cosmogramma.", origin: "rec", pick: true },
  { name: "Madlib", genre: "Hip-Hop / Jazz", y: 1993, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "El productor camaleon absoluto; y como Yesterdays New Quintet se invento un quinteto de jazz falso donde toca el mismo todos los instrumentos y le puso nombre a cada musico ficticio. Entrada: Shades of Blue.", origin: "rec", pick: true },
  { name: "Shabaka Hutchings", genre: "Jazz / Experimental (UK)", y: 2011, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "Lidero Sons of Kemet (tuba, saxo y dos bateristas simultaneos) y The Comet Is Coming, y despues dejo el saxofon por la flauta para grabar camara meditativa. Reinventarse abandonando tu instrumento es otro nivel. Entrada: Your Queen Is a Reptile.", origin: "rec", pick: true },
  { name: "MF DOOM", genre: "Hip-Hop / Rap", y: 1988, p: 1, via: "Hip-hop/Jazz", desc: "Rimas internas densísimas con esquemas que cruzan el final del verso en vez de cerrarlo, sobre producción de collage: diálogos de dibujos animados de los sesenta y bucles de jazz oscuro. Y no es un disco suelto: Operation Doomsday, MM..FOOD y Madvillainy con Madlib sostienen lo mismo, además de lo que sacó como Viktor Vaughn y King Geedorah, cada uno con otra voz y otra producción. Murió en 2020. Entrada: Madvillainy.", origin: "rec", pick: true },
  { name: "The Roots", genre: "Hip-Hop / Jazz Rap", desc: "Hip-hop tocado por una banda en vivo en lugar de programado, y ahí está la diferencia: Questlove toca el groove ligeramente detrás del pulso, dejando que respire en vez de cuadrarlo, y el bajo y los teclados responden a la voz como en un grupo de jazz. Y evolucionaron de verdad: undun es un disco conceptual narrado en orden cronológico inverso que cierra con un cuarteto de cuerdas. Entra por Things Fall Apart o undun.", origin: "rec", p: 1, y: 1987, c: 2 },
  { name: "A Tribe Called Quest", genre: "Jazz Rap / Hip-Hop", y: 1985, p: 2, via: "Hip-hop/Jazz", desc: "Pioneros del sampleo de jazz, pero el dato clave: en The Low End Theory metieron a Ron Carter tocando contrabajo de verdad (el bajista de Miles Davis) en un disco de rap de 1991. Entrada: The Low End Theory.", origin: "rec", pick: true },
  { name: "Kamasi Washington", genre: "Jazz / Spiritual Jazz", desc: "Jazz espiritual modal con arreglos amplios de coro y cuerda encima, tempos que respiran y solos largos sobre armonía bastante estable. Es majestuoso y emocionante, pero armónicamente es más sencillo que casi todo lo que tienes arriba en esta sección. Entra por The Epic.", origin: "rec", p: 2, y: 2004, c: 2 },
  { name: "BADBADNOTGOOD", genre: "Jazz / Hip-Hop", y: 2010, p: 2, via: "Hip-hop/Jazz", desc: "Trio de jazz salido del mundo del hip-hop; Talk Memory tiene arreglos orquestales del brasileno Arthur Verocai. Han grabado con Ghostface Killah y Tyler. Entrada: IV, luego Talk Memory.", origin: "rec", pick: true },
  { name: "Makaya McCraven", genre: "Jazz / Experimental", y: 2012, p: 2, via: "Hip-hop/Jazz", desc: "Baterista-productor: graba sesiones de improvisacion de jazz en vivo y luego las corta y reensambla como si fueran beats. Se llama a si mismo beat scientist: es composicion por edicion, con la bateria al mando. Entrada: Universal Beings.", origin: "rec", pick: true },
  { name: "billy woods", genre: "Experimental Hip-Hop", y: 2002, p: 2, via: "Hip-hop/Jazz", desc: "La escritura mas densa y abstracta del rap actual sobre produccion disonante y hostil. GOLLIWOG (2025) fue llamado por Pitchfork una obra maestra de horrorcore. Con ELUCID forma Armand Hammer. Entrada: Maps.", origin: "rec", pick: true },
  { name: "Little Simz", genre: "Hip-Hop / Jazz Rap (UK)", y: 2010, p: 2, female: true, via: "Hip-hop/Jazz", desc: "Albumes narrativos con arreglos orquestales reales (cuerdas y coros). Lotus (junio 2025) trae jazz, punk y funk, con Yussef Dayes de invitado a la bateria. Entrada: Sometimes I Might Be Introvert.", origin: "rec", pick: true },
  { name: "J Dilla", genre: "Hip-Hop / Instrumental", desc: "[Comodín] Programaba la batería deliberadamente desalineada, sin cuantizar, dejando el bombo y la caja caídos unos milisegundos fuera de la rejilla, de modo que el groove cojea y respira como si lo tocara una persona cansada. Eso cambió cómo se toca el instrumento: hoy los bateristas estudian el Dilla time como técnica y una generación entera de soul y hip-hop se construyó sobre esa idea. Donuts son 31 piezas de loops que armó en una cama de hospital con un sampler portátil, y salió tres días antes de que muriera. Entra por Donuts.", origin: "rec", p: 1, y: 1995, c: 3 },
  { name: "Irreversible Entanglements", genre: "Free Jazz / Experimental", y: 2015, p: 2, female: true, via: "Hip-hop/Jazz", desc: "Free jazz improvisado mas poesia hablada de Moor Mother, politico e incendiario. Entrada: Who Sent You?", origin: "rec", pick: true },
  { name: "Standing on the Corner", genre: "Experimental / Jazz", y: 2016, p: 3, via: "Hip-hop/Jazz", desc: "Colectivo experimental de Nueva York: collage de jazz, soul, ruido, gospel y grabaciones de campo, sin formato de cancion. Entrada: Red Burns.", origin: "rec", pick: true },
  { name: "Ezra Collective", genre: "Jazz / Afrobeat (UK)", y: 2012, p: 2, via: "Hip-hop/Jazz", desc: "Jazz londinense con afrobeat, liderado por el baterista Femi Koleoso; ganaron el Mercury Prize. Here Because of Hope (sept 2026) esta concebido como tres movimientos geograficos. Entrada: Where I'm Meant to Be.", origin: "rec", pick: true },
  { name: "Saul Williams", genre: "Industrial Hip-Hop / Poesía", y: 1998, p: 2, via: "Hip-hop/Jazz", desc: "Poeta que hace hip-hop industrial, y el dato que cierra el circulo: Trent Reznor le produjo un disco entero. NIN esta en tu ①, asi que el ADN es directo. Entrada: The Inevitable Rise and Liberation of NiggyTardust!", origin: "rec", pick: true },

  // ----- THRASH TÉCNICO / DEATH CLÁSICO -----
  { name: "Napalm Death", genre: "Grindcore / Industrial", desc: "Grindcore, o sea velocidad y brevedad extremas sobre riffs deliberadamente simples, sin desarrollo. Lo que sí vale es que no se quedaron quietos en cuarenta años: metieron industrial, pasajes de ruido y disonancia real a partir de Fear Emptiness Despair, y el blast beat que inventó Mick Harris cuenta porque cambia cómo suena todo lo que vino después. Sacaron disco a medias con los Melvins, Savage Imperial Death March, en abril de 2026. Entrada: Utopia Banished.", origin: "rec", p: 2, y: 1981, c: 1 },
  { name: "Kreator", genre: "Thrash Metal (DE)", desc: "Thrash rápido con melodías de guitarra épicas encima del riff y voz rasposa de Mille Petrozza, muy bien ejecutado y bastante directo de estructura. Krushers of the World salió en enero de 2026. Entra por Coma of Souls.", origin: "rec", p: 2, y: 1982, c: 1 },
  { name: "Hypocrisy", genre: "Melodic Death Metal (SE)", y: 1990, p: 2, c: 1, via: "Thrash/Death", desc: "Peter Tagtgren llevo la banda del death brutal a un death melodico atmosferico y casi espacial (tematica de abducciones), y en paralelo monto Pain, puro industrial-metal. Dos identidades a la vez. Entrada: Abducted.", origin: "rec", pick: true },
  { name: "Dark Angel", genre: "Technical Thrash Metal", desc: "Aquí la batería ES la escritura: Hoglan compone las partes como si fueran riffs, con patrones que cambian de figura bajo el mismo riff de guitarra y subdivisiones que desplazan el acento, y por eso los temas duran ocho minutos sin repetirse. Darkness Descends, Leave Scars y Time Does Not Heal funcionan igual. Volvieron el 5 de septiembre de 2025 con Extinction Level Event, su primer disco desde 1991, dedicado a Jim Durkin, que murió en 2023 y firma varios temas de forma póstuma. Entra por Darkness Descends.", origin: "rec", p: 1, y: 1981, c: 2 },
  { name: "Obituary", genre: "Death Metal", desc: "Death metal a medio tiempo, muy afinado hacia abajo, con riffs sencillos que se quedan en el bolsillo del ritmo y la voz agónica de John Tardy, que en varios discos improvisa sin letra escrita. La crítica los agrupa con Bolt Thrower como el AC/DC del death metal: una sola cosa, hecha muy bien, más centrada en el ambiente que en la ejecución. Es buen death metal, pero no es lo que tú buscas. Entra por Cause of Death.", origin: "rec", p: 3, y: 1984, c: 2 },
  { name: "Suffocation", genre: "Brutal Technical Death", desc: "El brutal death que sí está construido. Terrance Hobbs escribe riffs que se desarrollan y se recolocan en lugar de amontonarse, con cambios de tempo dentro del tema y secciones que vuelven transformadas, y la batería sostiene esa arquitectura en lugar de solo golpear. De aquí sale el breakdown del death metal. Es la prueba de que brutal no tiene que significar informe. Entra por Effigy of the Forgotten o Pierced from Within.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Cryptopsy", genre: "Technical Death Metal (CA)", desc: "Death tecnico canadiense donde la bateria de Flo Mounier es el eje: alterna blast beats con figuras sincopadas que cambian bajo el mismo riff, mete redobles de mano izquierda a velocidades que casi nadie replica, y varia la subdivision dentro del compas en vez de sostenerla. Encima, riffs disonantes que no repiten y la voz gutural de Lord Worm en la primera etapa. Entrada: None So Vile.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Cryptic Shift", genre: "Technical Death / Thrash (UK)", y: 2015, p: 2, via: "Thrash/Death", desc: "Hallazgo de 2026: tech-death/thrash con fusion jazz, cinco temas en 82 minutos, uno de 30:46, con guitarras a lo Allan Holdsworth. La critica lo llamo el disco de death metal a vencer en 2026. Entrada: Overspace & Supertime.", origin: "rec", pick: true },
  { name: "Destruction", genre: "Technical Thrash Metal (DE)", y: 1982, p: 2, via: "Thrash/Death", desc: "El mas tecnico del trio aleman: Schmier canta y toca el bajo a la vez, con lineas que se van por su cuenta en vez de seguir la guitarra. Birth of Malice salio en marzo de 2025. Entrada: Eternal Devastation.", origin: "rec", pick: true },
  { name: "Sodom", genre: "Thrash Metal (DE)", y: 1981, p: 2, via: "Thrash/Death", desc: "El mas crudo, directo y punk del trio aleman. Sacaron The Arsonist en junio de 2025 y entraron en hiato indefinido justo despues. Entrada: Agent Orange.", origin: "rec", pick: true },
  { name: "Overkill", genre: "Thrash Metal", y: 1980, p: 2, via: "Thrash/Death", desc: "Mas de 40 anos sin bajar el nivel, y D.D. Verni lleva el bajo tan al frente que muchas veces el ES el riff principal. Bobby Blitz sigue cantando agudisimo. Entrada: Horrorscope.", origin: "rec", pick: true },
  { name: "Toxik", genre: "Technical Thrash Metal", y: 1985, p: 2, via: "Thrash/Death", desc: "Thrash tecnico casi imposible: Josh Christian tocaba en 1987 cosas que no tenian sentido para la epoca, con arreglos que rozan el prog. Entrada: Think This.", origin: "rec", pick: true },
  { name: "Forbidden", genre: "Technical Thrash Metal", y: 1985, p: 2, via: "Thrash/Death", desc: "Twisted into Form: thrash con armonias vocales reales, arreglos que respiran y Paul Bostaph (luego Slayer) en una bateria muy por encima de la media del genero. Entrada: Twisted into Form.", origin: "rec", pick: true },
  { name: "Bloodbath", genre: "Death Metal (SE)", y: 1998, p: 2, via: "Thrash/Death", desc: "Supergrupo sueco fundado por miembros de Katatonia (Nystrom y Renkse) con Mikael Akerfeldt de Opeth cantando al inicio y hoy con Nick Holmes de Paradise Lost. Death old-school hecho por gente que normalmente compone prog. Entrada: Resurrection Through Carnage.", origin: "rec", pick: true },
  { name: "Martyr", genre: "Technical Death Metal (CA)", y: 1994, p: 2, via: "Thrash/Death", desc: "Death tecnico con Daniel Mongrain, que anos despues entro a Voivod, que ya tienes. Veta Cynic/Atheist pura, con armonia rarisima. Entrada: Warp Zone.", origin: "rec", pick: true },
  { name: "Believer", genre: "Technical Thrash Metal", desc: "[Comodín] No es thrash con un violín de adorno al final: en Sanity Obscure hay una pieza con soprano clásica y cuarteto de cuerda encima del riff, y Dimensions abre con una suite de cámara de varios movimientos antes de que entre la banda, todo escrito para que las cuerdas lleven contrapunto contra la guitarra en vez de doblarla. El riff de fondo ya es técnico y de compás cambiante por su cuenta. Nadie más hizo esto en el thrash. Entra por Sanity Obscure.", origin: "rec", p: 1, y: 1986, c: 3 },
  { name: "Spiral Architect", genre: "Progressive Death Metal (NO)", desc: "Un solo disco y les basto: compases que cambian sin parar, estructuras que no se repiten y polirritmias con contrapunto real, con Asgeir Mickelson guiando esos cambios a la bateria y Lars Norberg tocando lineas de bajo independientes. Se les describe como Watchtower cruzado con Psychotic Waltz. Aviso: la voz de Oyvind Haegeland es un gusto adquirido. Entrada: A Sceptics Universe.", origin: "rec", p: 1, y: 1993, c: 2 },
  { name: "Incantation", genre: "Death Metal", y: 1989, p: 2, via: "Thrash/Death", desc: "Death cavernoso que alterna blast beats con doom arrastrado dentro de la misma cancion. Riffs que suenan grabados dentro de una cueva. Entrada: Onward to Golgotha.", origin: "rec", pick: true },
  { name: "Terrorizer", genre: "Grindcore / Death Metal", y: 1986, p: 3, via: "Thrash/Death", desc: "World Downfall: un solo disco esencial, grabado con Pete Sandoval (luego Morbid Angel) definiendo lo que significaba rapido en 1989. Entrada: World Downfall.", origin: "rec", pick: true },
  { name: "Deicide", genre: "Death Metal", y: 1987, p: 4, via: "Thrash/Death", desc: "Pionero indiscutible, pero formulaico y construido sobre el shock mas que sobre la musica; no evoluciona entre discos. Va al nivel de contexto junto a Cannibal Corpse. Su unico gancho real es Steve Asheim en la bateria. Entrada: Legion.", origin: "rec", pick: true },

  // ----- GUITARRA INSTRUMENTAL -----
  { name: "Dixie Dregs", genre: "Prog Rock / Fusion", y: 1970, p: 1, c: 1, via: "Guitarra instrumental", desc: "Instrumental entero, sin una sola voz, mezclando bluegrass, prog, fusión y música clásica dentro del mismo tema, con violín y guitarra turnándose la melodía y una sección rítmica que cambia de estilo por debajo. What If, Dregs of the Earth y Free Fall funcionan igual. Entrada: What If.", origin: "rec", pick: true },
  { name: "Shawn Lane", genre: "Jazz Fusion / Instrumental", y: 1985, p: 2, c: 1, via: "Guitarra instrumental", desc: "Probablemente el guitarrista mas rapido que ha existido, pero esa es la parte aburrida: lo que importa son sus ritmos bulgaros e indios, la microtonalidad y sus duos con el bajista Jonas Hellborg. Murio a los 40. Entrada: Powers of Ten.", origin: "rec", pick: true },
  { name: "Freak Kitchen", genre: "Prog Metal (SE)", y: 1992, p: 2, c: 1, via: "Guitarra instrumental", desc: "Mattias IA Eklundh usa cuartos de tono, konnakol indio y toca con taladros y objetos domesticos, con humor negro encima. Tecnica extrema al servicio de la rareza, no del lucimiento. Entrada: Land of the Freaks.", origin: "rec", pick: true },
  { name: "Allan Holdsworth", genre: "Jazz Fusion / Instrumental", y: 1969, p: 1, via: "Guitarra instrumental", desc: "Construye los solos con escalas simétricas y acordes de más de cuatro notas que no pertenecen a la tonalidad de la base, y el legato es tan continuo que no se oye el ataque de cada nota: suena más a viento que a guitarra. Lo sostiene a lo largo de toda su obra en solitario, de I.O.U. a Metal Fatigue a Secrets, y también en su etapa con Soft Machine y Bruford. Entrada: Metal Fatigue.", origin: "rec", pick: true },
  { name: "Jason Becker", genre: "Neoclassical / Instrumental", desc: "Su ficha era estuvo en Cacophony con Marty Friedman (personal) y su historia con la ELA (biografía), sin una palabra de cómo suena, y su historia es admirable pero no es un criterio musical. Cómo suena, en dos etapas muy distintas: Perpetual Burn es shred neoclásico de 1988, arpegios barridos a velocidad extrema sobre armonía menor armónica, o sea virtuosismo como fin, igual que Planet X. Lo posterior, dictado nota a nota con los ojos, es otra cosa: piezas orquestales con arreglo de cuerda y desarrollo temático real, y ahí sí hay composición. Entra por Triumphant Hearts antes que por Perpetual Burn.", origin: "rec", p: 2, y: 1986, c: 2 },
  { name: "Guthrie Govan", genre: "Jazz Fusion / Instrumental", y: 2006, p: 2, via: "Guitarra instrumental", desc: "Ya lo tienes via The Aristocrats, pero su disco solista Erotic Cakes es otra cosa: una clase magistral de fusion con sentido del humor. Entrada: Erotic Cakes.", origin: "rec", pick: true },
  { name: "Panzerballett", genre: "Jazz Metal (DE)", y: 2004, p: 2, via: "Guitarra instrumental", desc: "Jazz-metal aleman: cogen standards de jazz y los reescriben en compases imposibles con distorsion de metal. Absurdo y virtuoso a partes iguales. Entrada: X-Mas Death Jazz.", origin: "rec", pick: true },
  { name: "Tribal Tech", genre: "Jazz Fusion", y: 1984, p: 2, via: "Guitarra instrumental", desc: "El eje fusion de verdad, con Scott Henderson viniendo del blues retorcido y Gary Willis al bajo fretless. Entrada: Face First.", origin: "rec", pick: true },
  { name: "Béla Fleck and the Flecktones", genre: "Jazz Fusion / Bluegrass", desc: "[Comodín] Béla Fleck toca líneas de bebop en un banjo de cinco cuerdas, un instrumento que no está pensado para esa armonía, y Victor Wooten al bajo usa doble pulgar y slap melódico para llevar contramelodías en vez de acompañar. Es virtuosismo enorme sobre estructuras de fusión bastante convencionales y con groove accesible, y ahí está el techo comparado con Mahavishnu o Weather Report. El comodín se queda: Roy Wooten se construyó el Drumitar, una batería electrónica con forma de guitarra. Entra por Flight of the Cosmic Hippo.", origin: "rec", p: 2, y: 1988, c: 3 },
  { name: "Blotted Science", genre: "Technical Death / Instrumental", desc: "[Comodín] Cómo suena primero: metal instrumental sin una sola voz, con riffs atonales y angulares que no resuelven nunca donde esperas, cambios de compás continuos y el bajo de Alex Webster (Cannibal Corpse) haciendo líneas propias en vez de doblar la guitarra. Es denso y agotador de seguir, en el buen sentido. Lo que le da el comodín es que Ron Jarzombek (de Watchtower, ya tuyo) lo compuso con un sistema dodecafónico propio, el Sonic Titan, con reglas estrictas de doce tonos, pero el tier está por lo que suena, no por el sistema. Entra por The Machinations of Dementia.", origin: "rec", p: 2, y: 2007, c: 3 },
  { name: "Michael Manring", genre: "Jazz Fusion / Instrumental", y: 1986, p: 2, c: 3, via: "Guitarra instrumental", desc: "[Comodín] Cambia la afinación de las cuerdas mientras toca, así que la armonía se mueve por debajo de una nota que sigue sonando: un solo bajo haciendo melodía, bajo y armonía a la vez, sin overdubs. Entrada: Soliloquy.", origin: "rec", pick: true },
  { name: "Stick Men", genre: "Prog Rock / Instrumental", y: 2007, p: 2, via: "Guitarra instrumental", desc: "Tony Levin (King Crimson) al Chapman Stick, Pat Mastelotto (King Crimson) a la bateria y Markus Reuter al touch guitar. Instrumentos de tapping que cubren bajo y armonia a la vez: el trio suena como un sexteto. Entrada: Deep.", origin: "rec", pick: true },
  // ----- AÑADIDOS POR PETICIÓN DE KEN -----
  { name: "Spawn of Possession", genre: "Technical Death Metal (SE)", y: 1997, p: 1, via: "Thrash/Death", desc: "Uno de los picos absolutos del death tecnico: riffs laberinticos de tono neoclasico que se pliegan sobre si mismos, sin caer en velocidad boba. Incurso (2012) es su obra maestra y su ultimo disco. Veta directa de Obscura, Necrophagist y Spiral Architect. Entrada: Incurso.", origin: "rec", pick: true },
  { name: "Retromorphosis", genre: "Technical Death Metal (SE)", y: 2024, p: 2, via: "Thrash/Death", desc: "La continuacion real de Spawn of Possession: cuatro de los cinco miembros de su formacion final se reagruparon en 2024 bajo este nombre. Psalmus Mortis (feb 2025) retoma justo donde quedo Incurso. Entrada: Psalmus Mortis.", origin: "rec", pick: true },
  { name: "Dying Fetus", genre: "Brutal Technical Death", y: 1991, p: 3, via: "Thrash/Death", desc: "John Gallagher compone toda la música y su estilo de riff es de los más reconocibles y técnicos del death brutal, con el bajo de Sean Beasley siguiendo esas figuras nota a nota. Pero llevan treinta años sin mover la fórmula, y la estética de gutural y groove de slam con raíz hardcore de Nueva York es lo que los deja en este nivel. Entrada: Reign Supreme.", origin: "rec", pick: true },
  { name: "Consider the Source", genre: "Prog Fusion / Instrumental", y: 2004, p: 2, via: "Guitarra instrumental", desc: "Fusion sci-fi de Oriente Medio: guitarra de doble mastil sin trastes, escalas arabes y turcas sobre estructuras prog. Trio instrumental. Entrada: World War Trio.", origin: "rec", pick: true }
];

// ===========================================================================
// === INSTRUMENTISTAS Y COMPOSITORAS (ago 2026) =============================
// Eje distinto al de "voz femenina": aquí la mujer ES la sustancia
// instrumental o compositiva. Todas justificadas por el instrumento, la
// técnica o el sistema de composición, nunca por quién es.
// ===========================================================================
const INSTRUMENTISTAS = [
  { name: "Hiromi", genre: "Jazz Fusion (JP)", y: 1999, p: 1, via: "Mujeres instrumentistas", desc: "Pianista y compositora que cruza stride, post-bop, rock progresivo, clasica y fusion dentro de una misma pieza, con tecnica descomunal. Su Trio Project la puso con Anthony Jackson al bajo de seis cuerdas y Simon Phillips a la bateria: composicion compleja ejecutada por un trio donde los tres instrumentos son protagonistas. Entrada: Move o Alive.", origin: "rec", pick: true, female: true },
  { name: "Jlin", genre: "Electronic / Experimental", y: 2011, p: 1, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Salio del footwork de Chicago y termino FINALISTA DEL PULITZER DE MUSICA 2023 por Perspective, suite en siete partes escrita para el ensamble Third Coast Percussion. Su materia prima es la complejidad ritmica pura. Ha compuesto para el Kronos Quartet y en Akoma (2024) colabora con Bjork y Philip Glass. Entrada: Akoma.", origin: "rec", pick: true, female: true },
  { name: "Mary Halvorson", genre: "Avant-garde Jazz / Guitar", y: 2002, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] La beca MacArthur la premio citando literalmente 'un sonido singular en su instrumento'. Pua percusiva, string-skipping y un pedal de delay manipulado para funcionar como pitch-shifter, sacando armonicos y texturas que no existen en otra guitarra. Angular y descolocada a proposito. Entrada: Amaryllis, luego Cloudward.", origin: "rec", pick: true, female: true },
  { name: "Sarah Longfield", genre: "Prog / Instrumental", y: 2013, p: 2, via: "Mujeres instrumentistas", desc: "Guitarrista de ocho cuerdas con enfoque pianistico de tapping a dos manos: usa el mastil como un teclado. Sus influencias declaradas son Meshuggah y Animals as Leaders, las dos en tu ①. Ha girado con Marty Friedman y Polyphia. Entrada: Disparity.", origin: "rec", pick: true, female: true },
  { name: "Anika Nilles", genre: "Jazz Fusion / Prog", y: 2013, p: 2, via: "Mujeres instrumentistas", desc: "Baterista y compositora alemana; su banda Nevell hace fusion de jazz, funk y prog escrita por ella, construida sobre polirritmias (3-contra-4, 4-contra-3) usadas como material compositivo y no como adorno. Toco con Jeff Beck y en 2026 es la baterista de la gira de Rush. Entrada: Nevell.", origin: "rec", pick: true, female: true },
  { name: "Anna Meredith", genre: "Electronic / Art Pop (UK)", desc: "Compositora escocesa de formación clásica (escribió para la BBC Symphony antes de esto) que se pasó a la electrónica sin dejar de componer como compositora: FIBS son cuarenta y cinco minutos donde la métrica se reinventa casi en cada sección, con clarinete, tuba, chelo y sintetizadores entrando y saliendo como voces de una partitura en vez de como capas de producción. Nominada al Mercury por FIBS, y Varmints ganó el Scottish Album of the Year por delante de Franz Ferdinand y Chvrches. Entra por FIBS.", origin: "rec", p: 1, y: 2012, c: 1 },
  { name: "Lucrecia Dalt", genre: "Experimental / Electronic (CO)", y: 2005, p: 2, c: 1, via: "Mujeres instrumentistas", desc: "Colombiana, y de las artistas experimentales mas respetadas que hay. ¡Ay! (2022) fue disco del ano para The Wire y top-10 en Pitchfork, NYT y NPR. A Danger to Ourselves (sept 2025) lo construyo con el percusionista Alex Lazaro sobre la interaccion de lineas de bajo, ritmos y textura. Entrada: ¡Ay!", origin: "rec", pick: true, female: true },
  { name: "Wendy Carlos", genre: "Synth / Electronic", y: 1968, p: 1, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Buscando sistemáticamente picos de consonancia fuera del temperamento occidental dio con tres escalas que NO se repiten a la octava, alfa, beta y gamma; las usó en Beauty in the Beast (1986) y suenan genuinamente ajenas, porque la referencia armónica que el oído espera no existe. Antes de eso, Switched-On Bach: mil cien horas grabando cada voz por separado en un Moog monofónico y montándolas a mano, dando expresión línea a línea en vez de teclear acordes. Compuso para La Naranja Mecánica, El Resplandor y Tron. Entrada: Switched-On Bach, luego Beauty in the Beast.", origin: "rec", pick: true, female: true },
  { name: "Delia Derbyshire", genre: "Experimental / Electronic", y: 1962, p: 3, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Estudio musica y matematicas en Cambridge y creo el tema de Doctor Who en 1963 cortando y empalmando cinta a mano, midiendo longitudes fisicas, antes de que existieran los sintetizadores. El metodo no tiene par. La citan Aphex Twin, Chemical Brothers y Bjork. OJO: su obra es fragmentaria (musica de biblioteca de la BBC); el unico disco real es An Electric Storm de White Noise.", origin: "rec", pick: true, female: true },
  { name: "Kylesa", genre: "Sludge / Psych Metal", y: 2001, p: 2, via: "Mujeres instrumentistas", desc: "Sludge con DOS BATERISTAS simultaneos paneados fuerte a izquierda y derecha: el estereo es parte de la composicion. Laura Pleasants es guitarrista y co-vocalista. Estuvieron en hiato desde 2016 y volvieron con shows de reunion desde 2025 (Roadburn, ArcTanGent). Entrada: Spiral Shadow.", origin: "rec", pick: true, female: true },
  { name: "Zeena Parkins", genre: "Avant-garde / Experimental", y: 1984, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Toca el arpa fuera de todo lo que se supone que hace: estira las cuerdas más allá de su rango para doblar la afinación, las prepara con objetos y las enruta por procesamiento analógico y digital, pasando de texturas delicadas a retroalimentación distorsionada dentro de una misma pieza. Improvisación libre, no repertorio. Ha trabajado con Björk y Anthony Braxton. Entrada: The Adorables.", origin: "rec", pick: true, female: true },
  { name: "Kali Malone", genre: "Ambient / Experimental", y: 2014, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Compone para ORGANO DE TUBOS usando sistemas de afinacion historicos y just intonation, reinterpretando metodos polifonicos de hace siglos. Microfonia cercana para que se oiga cada detalle textural del instrumento. Disco lento y exigente, pero tu paciencia con Bell Witch y Sleep lo aguanta. Entrada: The Sacrificial Code.", origin: "rec", pick: true, female: true },
  { name: "Ikue Mori", genre: "Experimental / Electronic", y: 1977, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Monto DNA, banda clave del no-wave, con una bateria completamente propia: kit minimo, todo el peso en los toms, patrones entrecortados pero propulsivos. Luego improviso con cajas de ritmos y encontro como hacerlas sonar 'rotas' quitandoles la cuantizacion, y hacia 2000 paso al laptop. Lleva decadas con John Zorn, cuyo Naked City ya tienes en ①.", origin: "rec", pick: true, female: true },
  { name: "Terri Lyne Carrington", genre: "Jazz / Fusion", y: 1989, p: 2, via: "Mujeres instrumentistas", desc: "Cuatro Grammys, NEA Jazz Master, y baterista-COMPOSITORA-productora, no solo interprete. Fundo el Berklee Institute of Jazz and Gender Justice. We Insist 2025! reimagina la Freedom Now Suite de Max Roach y le valio nominacion al Grammy 2026. Entrada: The Mosaic Project.", origin: "rec", pick: true, female: true },
  { name: "Divide and Dissolve", genre: "Doom Metal / Instrumental (AU)", y: 2015, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Formacion que no existe en ningun otro sitio: Takiaya Reed toca SAXOFON Y GUITARRA y Sylvie Nehill bateria. Doom instrumental con el saxo como instrumento pesado, no como adorno jazzy. Insatiable quedo preseleccionado para el Australian Music Prize 2025, y en 2025 Reed compuso una sinfonia interpretada por la BBC Concert Orchestra. Entrada: Gas Lit.", origin: "rec", pick: true, female: true },
  { name: "Hildur Guðnadóttir", genre: "Experimental / Chamber (IS)", y: 2006, p: 2, via: "Mujeres instrumentistas", desc: "Chelista de formacion clasica cuya obra entera se construye desde el cello. Antes de los Oscar toco y grabo con Sunn O))), Throbbing Gristle, Pan Sonic y Mum: viene del drone y lo industrial, no del cine. Primera compositora en solitario en ganar Oscar, BAFTA y Globo de Oro por la misma partitura. Entrada: Without Sinking.", origin: "rec", pick: true, female: true },
  { name: "Esperanza Spalding", genre: "Jazz Fusion / Prog", y: 2006, p: 2, via: "Mujeres instrumentistas", desc: "Bajista, compositora y vocalista. Emily's D+Evolution es un disco conceptual de prog-rock angular con guitarra electrica, fusion jazz ritmicamente densa, cambios de acorde poco ortodoxos y melodias angulares: la critica lo considera mucho mas complejo que todo lo anterior suyo. Coproducido con Tony Visconti, el productor de Bowie. Entrada: Emily's D+Evolution.", origin: "rec", pick: true, female: true },
  { name: "Kaki King", genre: "Instrumental / Math Rock", y: 2003, p: 2, via: "Mujeres instrumentistas", desc: "Toca la guitarra PLANA SOBRE EL REGAZO, con tapping a dos manos y golpes percusivos sobre el cuerpo, aplicando incluso tecnica de slap de bajo a las cuerdas. Viene de la bateria y por eso usa la guitarra como instrumento ritmico. En discos posteriores toca ademas bateria, bajo, teclados y lap steel. Entrada: Legs to Make Us Longer.", origin: "rec", pick: true, female: true },
  { name: "Meshell Ndegeocello", genre: "Jazz / Soul / Funk", y: 1993, p: 2, c: 1, via: "Mujeres instrumentistas", desc: "Bajista, compositora y productora con una carrera que ha cambiado de piel muchas veces. The Omnichord Real Book (2023) gano el PRIMER Grammy que se otorgo a Mejor Album de Jazz Alternativo: doble, sin genero fijo, atravesando neo soul, funk, afrobeat, hip-hop y experimental. Entre sus colaboradores esta Jeff Parker, el guitarrista de Tortoise. Entrada: The Omnichord Real Book.", origin: "rec", pick: true, female: true },
  { name: "BIG|BRAVE", genre: "Experimental / Sludge Metal (CA)", y: 2012, p: 2, via: "Mujeres instrumentistas", desc: "Robin Wattie a la guitarra y voz en un trio que hace metal hipnotico y monolitico cruzado con drone y folk. En 2025 sacaron OST, improvisado en estudio y enteramente instrumental, y en junio de 2026 in grief or in hope: un disco de metal SIN BATERIA, construido sobre armonicos y sutilezas tonales grabadas en vivo, con bajo, amplificadores, armonica y altavoces preparados. Entrada: Vital.", origin: "rec", pick: true, female: true },
  { name: "Crypta", genre: "Death Metal (BR)", y: 2019, p: 3, via: "Mujeres instrumentistas", desc: "Death metal brasileno fundado por Fernanda Lira (bajo y voz) y Luana Dametto (bateria), ambas ex-Nervosa. Dos discos solidos y bien recibidos. Honestamente: competente pero no excepcional instrumentalmente, esta dentro de la plantilla del death melodico, por eso ③ y no mas. Entrada: Shades of Sorrow.", origin: "rec", pick: true, female: true }
];

// ===========================================================================
// === BARRIDO ANCESTRAL Y DE CONTENEDORES (ago 2026) ========================
// Encontrado con el método nuevo: en vez de preguntar "que saco esta banda",
// enumerar ancestros de los tier 1, sellos, productores, festivales, premios
// y escenas, y cruzar hacia atras. Saco ~215 ausentes; esto es lo que pasa
// el filtro #1. Lote 1.
// ===========================================================================
const ANCESTROS = [
  // ----- LOS ANCESTROS DE TUS TIER 1 -----
  { name: "Queen", genre: "Art Rock / Hard Rock", desc: "Brian May graba capas de guitarra armonizadas entre sí para imitar una sección de metales o una orquesta, escribiendo cada voz por separado, y las canciones encadenan secciones sin volver al estribillo. The Prophet's Song lleva un canon vocal a varias voces hecho solo con la voz de Mercury superpuesta. Y reinventaban de disco a disco: ópera, funk, rockabilly, synth-pop, gospel. Entra por A Night at the Opera, luego Jazz.", origin: "rec", p: 1, y: 1970, c: 1 },
  { name: "Miles Davis", genre: "Jazz Fusion", y: 1955, p: 1, c: 1, via: "Ancestros", desc: "Cambió de sistema cinco veces y en cada uno escribió algo que antes no existía: el nonet de Birth of the Cool, el quinteto de hard bop, Kind of Blue montado sobre modos en vez de sobre cambios de acorde, el segundo quinteto tocando sin cifrado fijo, y Bitches Brew grabado como improvisación larga y armado después en la mesa de edición. Cuarenta años sin repetir formato. Entrada: Kind of Blue, luego Bitches Brew.", origin: "rec", pick: true },
  { name: "Celtic Frost", genre: "Avant-garde Metal / Thrash (CH)", desc: "Into the Pandemonium (1987) metió orquesta completa, soprano, timbales y cuerdas en un disco de metal extremo, más una versión de new wave y percusión tribal, cuando eso no se hacía. Tom G. Warrior lo explicó así: odiaban los límites no escritos de la escena metal. Y no es solo el arreglo: los riffs van a medios tiempos pesadísimos con acentos desplazados y su famoso golpe de voz corta la frase en sitios raros. Monotheist (2006) volvió a cambiarlo todo otra vez. Entra por Into the Pandemonium, luego To Mega Therion.", origin: "rec", p: 1, y: 1984, c: 1 },
  { name: "Bathory", genre: "Black Metal / Viking Folk (SE)", desc: "Tempos lentos y machacones, coros épicos de una sola voz multiplicada, pasajes acústicos entre medias y una grabación cruda a propósito, hecha casi entera por una sola persona. Es enorme de atmósfera y deliberadamente primitivo de ejecución. Entra por Hammerheart.", origin: "rec", p: 2, y: 1983, c: 1 },
  { name: "Can", genre: "Krautrock / Experimental (DE)", y: 1968, p: 1, c: 1, via: "Ancestros", desc: "El catalogo no tenia ni un grupo de krautrock. Jaki Liebezeit, apodado la caja de ritmos humana, tocaba un kit de jazz centrado casi solo en toms y caja bajo el mantra 'tienes que tocar monotono', y fue uno de los creadores del beat motorik. Ancestro del post-rock, de Talking Heads y de Radiohead. Entrada: Tago Mago.", origin: "rec", pick: true },
  { name: "Killing Joke", genre: "Post-Punk / Industrial (UK)", y: 1978, p: 1, c: 1, via: "Ancestros", desc: "Acordes abiertos de guitarra repetidos como un solo gesto sobre un bajo que lleva la melodía y una batería casi tribal: la canción avanza por presión acumulada y no por progresión de acordes. Y lo han sostenido cuarenta años, del post-punk metálico del debut de 1980 al disco de 2003 y a Pylon (2015). Geordie Walker murió en 2023. Entrada: Killing Joke (1980).", origin: "rec", pick: true },
  { name: "Led Zeppelin", genre: "Hard Rock (clásico)", y: 1968, p: 1, via: "Ancestros", desc: "John Bonham toca detrás del pulso con un sonido de bombo enorme y un pie derecho que hace tresillos rapidísimos con un solo pedal, y su forma de colocar el golpe es de las más estudiadas que existen; John Paul Jones toca bajo, teclados y mandolina, y escribe los arreglos. Y los discos son más raros de lo que su fama sugiere: el III es folk acústico y Houses of the Holy tiene funk y reggae. Entrada: Physical Graffiti.", origin: "rec", pick: true },
  { name: "Motörhead", genre: "Heavy Metal / Speed (UK)", y: 1975, p: 2, via: "Ancestros", desc: "El puente entre punk y metal del que sale todo el thrash que ya tienes: Metallica, Kreator, Testament. No es complejo, es inconfundible, que es el otro lado de tu filtro. Entrada: Ace of Spades, luego Overkill.", origin: "rec", pick: true },
  { name: "Possessed", genre: "Death / Thrash Metal", y: 1983, p: 2, via: "Ancestros", desc: "Seven Churches (1985) es, para mucha gente, el primer disco de death metal que existio. Ancestro directo de Death y Suffocation, los dos en tu ①. Entrada: Seven Churches.", origin: "rec", pick: true },
  { name: "Wishbone Ash", genre: "Hard Rock (clásico)", y: 1969, p: 2, via: "Ancestros", desc: "Inventaron la armonia de guitarras gemelas que definen a Thin Lizzy y a Iron Maiden, los dos en tu ①. Tenias a los discipulos arriba y no a quien creo la tecnica. Argus es el disco donde queda establecida. Entrada: Argus.", origin: "rec", pick: true },
  { name: "Blue Öyster Cult", genre: "Hard Rock (clásico)", y: 1967, p: 2, c: 1, via: "Ancestros", desc: "El ancestro directo de Ghost, que ya tienes en ①: rock ocultista con letras crípticas y conceptos de ciencia ficcion, mucho mas raro y literario de lo que su fama de banda de un solo hit sugiere. Imaginos es un disco conceptual delirante. Entrada: Secret Treaties.", origin: "rec", pick: true },
  { name: "Mayhem", genre: "Black Metal (NO)", y: 1984, p: 2, via: "Ancestros", desc: "Uno de los dos pilares que faltaban del black noruego. De Mysteriis Dom Sathanas define el genero del que descienden Emperor, Enslaved, Ulver, Behemoth y Deathspell Omega, todos en tu ①. Entrada: De Mysteriis Dom Sathanas.", origin: "rec", pick: true },
  { name: "Darkthrone", genre: "Black Metal (NO)", y: 1986, p: 2, c: 1, via: "Ancestros", desc: "El otro pilar noruego, y ademas mutan de verdad: empezaron como death metal tecnico, se pasaron al black mas crudo posible, y llevan quince anos haciendo crust y heavy metal setentero. Pocas discografias cambian tanto de piel. Entrada: A Blaze in the Northern Sky.", origin: "rec", pick: true },
  { name: "Melvins", genre: "Sludge / Experimental", desc: "Cómo suenan: riffs bajísimos tocados a tempos absurdamente lentos y estirados hasta incomodar, con Dale Crover haciendo de batería una parte protagonista y no una base, y una discografía que salta del drone más pesado al punk más rápido y a discos de puro ruido, a veces dentro del mismo álbum. Sacaron disco conjunto con Napalm Death en 2026. Entra por Bullhead, luego Lysol.", origin: "rec", p: 2, y: 1983, c: 1 },
  { name: "My Bloody Valentine", genre: "Shoegaze / Dream Pop (IE)", y: 1983, p: 2, via: "Ancestros", desc: "El ancestro del blackgaze que ya tienes fundado con Alcest y Deafheaven, y de la textura de Deftones. Kevin Shields invento la tecnica de glide guitar, tocando con la palanca del tremolo constantemente durante el acorde para que todo suene desafinado y liquido. Entrada: Loveless.", origin: "rec", pick: true },
  { name: "Sonic Youth", genre: "Noise Rock / Experimental", y: 1981, p: 2, c: 1, via: "Ancestros", desc: "Construyeron su lenguaje sobre afinaciones alternativas inventadas y guitarras preparadas con destornilladores y baquetas metidas entre las cuerdas. Ancestro del noise rock entero y de medio indie de los 90. Entrada: Daydream Nation.", origin: "rec", pick: true },
  { name: "The Velvet Underground", genre: "Art Rock / Experimental", y: 1965, p: 2, c: 1, via: "Ancestros", desc: "La viola electrica con drone de John Cale, que venia de la vanguardia minimalista, metida dentro de canciones de rock en 1967. Ancestro de Bowie, de Swans y de todo el art rock que ya tienes. Entrada: White Light/White Heat.", origin: "rec", pick: true },
  { name: "Throbbing Gristle", genre: "Industrial / Experimental (UK)", y: 1975, p: 2, c: 1, via: "Ancestros", desc: "No hay canción: construyen con cinta, sintetizador y voz procesada sobre estructuras que no vuelven, y en 20 Jazz Funk Greats el disfraz de música ligera de ascensor es parte de la pieza, no una broma aparte. Cuatro discos de estudio y ninguno se parece al anterior. Escucha incómoda a propósito. Entrada: 20 Jazz Funk Greats.", origin: "rec", pick: true },
  { name: "Helmet", genre: "Alt Metal / Noise Rock", y: 1989, p: 2, via: "Ancestros", desc: "Page Hamilton venía del jazz y aplicó esa formación a riffs de una sola nota, staccato y con los silencios colocados como parte del ritmo: el groove está en lo que no suena. Strap It On, Meantime y Betty funcionan con la misma mecánica. Entrada: Meantime.", origin: "rec", pick: true },
  { name: "Funkadelic", genre: "Funk / Psych Rock", y: 1968, p: 2, c: 1, via: "Ancestros", desc: "Ancestro de OutKast, Thundercat, Flying Lotus y RHCP, todos ya tuyos. Y el solo de Eddie Hazel en Maggot Brain, diez minutos grabados de una sola toma, es de los grandes de la guitarra. Entrada: Maggot Brain.", origin: "rec", pick: true },
  { name: "Fela Kuti", genre: "Afrobeat / Funk (NG)", y: 1969, p: 2, via: "Ancestros", desc: "Invento el afrobeat cruzando ritmos africanos con improvisacion jazz: polirritmia, secciones de metales y desarrollos instrumentales de veinte y treinta minutos. Brian Eno le presento su musica a Talking Heads y de ahi salio la polirritmia de Remain in Light, el disco por el que estan en tu ①. Ezra Collective le debe, segun ellos, una cantidad colosal. Entrada: Zombie.", origin: "rec", pick: true },
  { name: "Pentagram", genre: "Doom Metal", y: 1971, p: 3, via: "Ancestros", desc: "Proto-doom americano que estuvo grabando en los 70 sin publicar casi nada, y por eso su influencia llego tarde. Ancestro de Candlemass y de todo el doom tradicional que tienes. Valor mas historico que instrumental. Entrada: Relentless.", origin: "rec", pick: true },
  { name: "Glenn Branca", genre: "Avant-garde / Experimental", y: 1979, p: 2, c: 3, via: "Ancestros", desc: "[Comodín] Compuso sinfonías para orquestas de guitarras eléctricas, cien de ellas en la 13 y la 16: el material no son acordes sino masas de armónicos que baten entre sí, con la afinación como parte de la composición. Y el dato que lo ancla a ti: en sus primeros grupos tocaron Thurston Moore y Lee Ranaldo de Sonic Youth, Page Hamilton de Helmet y varios miembros de Swans incluido Michael Gira; su sello Neutral publicó los primeros discos de Swans. Rhys Chatham hizo el mismo camino en paralelo. Entrada: The Ascension.", origin: "rec", pick: true },

  // ----- SELLOS, PRODUCTORES Y ESCENAS -----
  { name: "Zu", genre: "Avant-garde / Jazz Metal (IT)", y: 1997, p: 2, c: 3, via: "Sellos y escenas", desc: "[Comodín] Trio romano de SAXOFON BARITONO, BAJO Y BATERIA, sin guitarra: instrumentacion de jazz con la agresion sonica del metal extremo, todo instrumental. John Zorn dijo que su musica barre con lo que hace la mayoria de bandas. Igneo lo produjo Steve Albini; Carboniferous salio en Ipecac. Entrada: Carboniferous.", origin: "rec", pick: true },
  { name: "Behold... The Arctopus", genre: "Prog / Instrumental", desc: "Sube porque es de lo más ajustado a tu filtro que hay aquí: metal instrumental de Brooklyn alimentado por música clásica del siglo XX, sin voz, con Colin Marston a la Warr guitar de doce cuerdas y una densidad de escritura brutal. Sale de comodín porque la Warr es un instrumento comercial que ellos no inventaron ni rediseñaron, y porque tiene pares evidentes que ya están en el catálogo: Blotted Science, Spiral Architect y Dysrhythmia, donde toca el propio Marston. Complejidad extrema con pares no es singularidad. Entra por Skullgrid.", origin: "rec", p: 1, y: 2001, c: 2 },
  { name: "Amenra", genre: "Post-Metal / Sludge (BE)", y: 1999, p: 2, via: "Sellos y escenas", desc: "Pilar del post-metal europeo y nucleo del colectivo Church of Ra. Su serie de Masses y un directo descrito como de los mas intensos del metal moderno; hicieron cinco noches agotadas seguidas en Ancienne Belgique en 2025. Entrada: Mass VI.", origin: "rec", pick: true },
  { name: "Thinking Plague", genre: "Avant-garde / Chamber Rock", y: 1982, p: 2, via: "Sellos y escenas", desc: "RIO americano en Cuneiform: duraciones epicas e instrumentacion rica cruzadas con improvisacion libre y collage sonoro. In This Life salio en el sello de Chris Cutler, el de Henry Cow, que tienes en ①. Entrada: In This Life.", origin: "rec", pick: true },
  { name: "Samla Mammas Manna", genre: "Avant-garde / Chamber Rock (SE)", y: 1969, p: 2, via: "Sellos y escenas", desc: "El tercer miembro fundador del movimiento Rock in Opposition, junto a Henry Cow y Univers Zero, los dos en tu ①. Virtuosismo con referencias circenses y humor absurdo, comparado con el estilo compositivo de Zappa, sobre ritmos complejos e instrumentos raros en el rock: marimba, bouzouki, veena y acordeon. Entrada: Maltid.", origin: "rec", pick: true },
  { name: "Nik Bärtsch's Ronin", genre: "Jazz Fusion / Chamber (CH)", y: 2001, p: 2, via: "Sellos y escenas", desc: "Pianista suizo con un concepto propio que llama ritual groove music o Zen funk: construcciones modulares, pulsos polimetricos y patrones entrelazados en compases impares y pares que se mezclan. La critica lo describe como el matrimonio del minimalismo de Steve Reich con los grooves de Sly Stone, y sus estructuras miran a Weather Report. Entrada: Stoa.", origin: "rec", pick: true },
  { name: "Virus", genre: "Avant-garde Metal (NO)", y: 2000, p: 2, via: "Sellos y escenas", desc: "Czral hizo primero Ved Buens Ende, black avant de acordes disonantes, y luego Virus para llevarlo aun mas lejos del metal. La critica lo compara con el Voivod de la era Nothingface, justo el que tienes en ①, y su bajo es protagonista y reclama atencion constante. Entrada: Carheart.", origin: "rec", pick: true },
  { name: "Pyrrhon", genre: "Dissonant Death Metal", y: 2008, p: 2, via: "Sellos y escenas", desc: "Death disonante de Brooklyn, comparable a Gorguts y Ulcerate pero con mas grindcore y math rock encima. Forma la segunda ola disonante junto a Imperial Triumphant y Artificial Brain, que ya tienes ambos. Entrada: The Mother of Virtues.", origin: "rec", pick: true },
  { name: "Ad Nauseam", genre: "Dissonant Death Metal (IT)", desc: "La guitarra derecha y la izquierda viven bajo ritmos distintos y se cortan mutuamente a traves de los compases, unificandose solo en los climax. Se afinaron un sistema propio para alejarse de los patrones melodicos habituales, y sus influencias declaradas son Stravinsky, Shostakovich, Xenakis, Scelsi, Penderecki y Ligeti, cosa que se oye. Es durisimo de escuchar. Entrada: Imperative Imperceptible Impulse.", origin: "rec", p: 1, y: 2011, c: 2 },
  { name: "Il Balletto di Bronzo", genre: "Prog Rock (IT)", y: 1969, p: 2, via: "Sellos y escenas", desc: "Tienes Banco y Area en ① y faltaba el lado negro del prog italiano. Ys (1972) es uno de los rarisimos ejemplos de prog italiano oscuro: Gianni Leone, descrito como una especie de Keith Emerson italiano, teje una trama opresiva y claustrofobica con organo, moog, mellotron y espineta. Entrada: Ys.", origin: "rec", pick: true },
  { name: "Motorpsycho", genre: "Prog Rock / Psych (NO)", y: 1989, p: 2, c: 1, via: "Sellos y escenas", desc: "Veintiocho discos y rara vez pasan dos anos sin material nuevo, saltando de psych pesado a prog a hard rock setentero. Su homonimo de 2025 es doble y una resena lo llamo el mejor disco progresivo del ano; en febrero de 2026 sacaron The Gaia II Space Corps. Antes, la trilogia The Tower / The Crucible / The All Is One. Entrada: The Tower.", origin: "rec", pick: true },
  { name: "Shakti", genre: "Jazz Fusion (IN)", desc: "Fusión indo-británica de John McLaughlin con L. Shankar al violín y Zakir Hussain a la tabla. Todo va montado sobre talas, los ciclos rítmicos indios de siete, nueve o más tiempos, y Shankar y la guitarra se turnan frases construidas sobre esos ciclos, con pasajes de konnakol (percusión recitada con la voz) marcando la subdivisión antes de tocarla. Es de lo rítmicamente más complejo del catálogo entero, y lo sostienen desde los tres discos de los setenta hasta This Moment, su primer disco de estudio en 46 años. Entra por A Handful of Beauty.", origin: "rec", p: 1, y: 1973, c: 2 },
  { name: "Konono Nº1", genre: "Experimental / Funk (CD)", y: 1966, p: 2, c: 3, via: "Sellos y escenas", desc: "[Comodín] Tres likembes congoleños repartidos en grave, medio y agudo tocan patrones cortos que se repiten y se desfasan entre sí, así que la música avanza por el roce entre las tres capas y no por acordes, sobre percusión de ollas, sartenes y piezas de coche. Y la decisión que lo define: adoptaron como material las distorsiones que su propio equipo producía sin querer. Entrada: Congotronics.", origin: "rec", pick: true },

  // ----- LA DECADA QUE FALTABA: 2020s -----
  { name: "The Callous Daoboys", genre: "Mathcore / Avant-garde", y: 2016, p: 2, via: "Escena 2020s", desc: "Mathcore con violinista fundadora (Amber Christman) y saxofon (Rich Castillo) dentro de la formacion, no de invitados. I Don't Want to See You in Heaven (mayo 2025) los llevo a estatus casi legendario y a muchas listas de disco del ano. Es la linea Dillinger, Fall of Troy y Number Twelve actualizada, con instrumentacion ampliada. Entrada: Celebrity Therapist.", origin: "rec", pick: true },
  { name: "Slift", genre: "Psych Rock / Prog (FR)", y: 2016, p: 2, via: "Escena 2020s", desc: "Trio frances. Ilion (2024, Sub Pop) saco 86 sobre 100 en Metacritic, aclamacion universal: cruza prog, psych, post-rock, space rock y stoner, uniendo la furia del metal con las heroicidades de guitarra del psych y la escala epica del post-rock. Entrada: Ilion.", origin: "rec", pick: true },
  { name: "Green Carnation", genre: "Progressive Metal (NO)", y: 1990, p: 2, via: "Escena 2020s", desc: "Noruegos con ambicion estructural real: estan publicando una trilogia entera, A Dark Poem, con la Pt. I Shores of Melancholia (sept 2025) y la Pt. II Sanguis (abril 2026) en Season of Mist. Su Light of Day, Day of Darkness es una sola pieza de 60 minutos. Entrada: Light of Day, Day of Darkness.", origin: "rec", pick: true },
  { name: "Kardashev", genre: "Progressive Deathcore", y: 2012, p: 2, via: "Escena 2020s", desc: "Inventaron lo que llaman deathgaze: deathcore atmosferico cruzado con shoegaze, con dinamica real entre lo brutal y lo etereo. Alunea (abril 2026, Metal Blade) es su tercer disco y secuela narrativa directa del anterior. Entrada: The Baring of Shadows.", origin: "rec", pick: true },
  { name: "Nospūn", genre: "Progressive Metal", y: 2019, p: 2, via: "Escena 2020s", desc: "La critica lo describe combinando los cambios complejos de Between the Buried and Me con la rareza de Devin Townsend y Native Construct: tres bandas que ya tienes. Opus (2023) y el EP Ozai (2025). Entrada: Opus.", origin: "rec", pick: true }
];

// ===========================================================================
